INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(1, '2016-06-19 22:12:00', 'Tak jsem si pro ocenění dnešní dne všech OTCŮ musel dojet až do Olomouce i s celou rodinou. Ale výlet to byl krásný. Dvojčata byla uchvácená cestou, atrakcemi i deštěm, já jsem si těch 600 Km náležitě užil za volantem a má milovaná polovička se neustále usmívala, takže i pak, když nebylo sluníčko, všechno kolem ní zářilo ;-)'),
(2, '2016-06-20 06:12:00', 'Z ničeho nic to začalo. Už od rána. Cokoli jsem udělal, bylo okomentováno, respektive slovně prozkoumáno.\n"Tatínku a co to je? JAK SE TO MENUJE?!" zkoumá dcera činnost obrušování zahradního nábytku, který posléze natřu.\n"To je šmirgl papír," zamachroval jsem ve slangu smirkového papíru.\n"Šmršgl papir," zopakovalo spokojeně dvojče.\n"A proč to děláš?" \nKrátce vše vysvětleno, spokojenost je doprovázena odchodem se houpat. Jdu jim tedy opravit hřiště, protože jejich váha jde nahoru a tím se začíná odpoutávat od země těžký přístřešek s pískovištěm a nerad bych, aby jednoho krásného houpání vše spadlo.\n"Tatínků, já ti pomůžu!" zase se vetře to samé dvojče a druhé mu chce mistrně sekundovat. Popadnou do ruky akuvrtačku a (bože!) kladivo.\n"Tatínku a co to je?" ukazuje prstem na vrtačku.\nZase kratší odpověď s názornou ukázkou, vyjmutí akubaterie a vrácení vrtačky (bez vrtáku) do rukou dcery, která začíná vrtat díky své vlastní, z úst se linoucí, zvukové kulise.\n"Já ezmu to KLADAVO a budu ti pomáhat," nadšeně se vrhla na devastaci kolíku na zatlučení. Chvíle ticha mé drahé polovičky nebyla až tak matoucí, přeci jen si chtěla vypít odpolední kávu. A tak jsem naše dítko trochu poupravil.\n"Ne, KLADIVO do ruky takovým malým pomocníkům NEPATŘÍ..."\n"Cože? Ona chtěla KLADIVO?" téměř vstala má drahá.\n"Ano, ci tlukat kladavem," hrdě se stále hlásila k manuální práci dcera. \n"Kladivo," kantorsky zasáhla milá a dcera, k naší spokojenosti, slovo zopakovala dobře. Nu co, čekám, kdy se z našich dvojčat ozve to, z čeho jsme si my, jako malé děti dělaly někdy velkou legraci - "A PROČ?"'),
(5, '2016-06-28 23:54:09', 'Nabitý (nebo spíše vybitý) tolika dojmy a emocemi sedím u PC a už poněkolikáté všechny počáteční věty mažu, protože se zkrátka nedokážu vyjádřit. Nebo dokážu, ale asi ne tak, abyste mne pochopili, protože (a to si už někdo mohl všimnout), nedokážu vykreslit příběh ku zájmu čtenáře, který jen stěží pak pochopí celý děj. Uf. I tato věta mi dala zabrat. A tak jen zásadní zpráva celého týdne (když pominu psychoteror našich dvojčat). To, že jsem stále samotný chlap v naší domácnosti, se nezměnilo. Ale zato jsme se rozrostli o další dámu. Zatím se krčí pod pohovkou nebo pod skříní, ale navečer se zálibně uvelebuje v naší manželské posteli a nechává se hladit. Ano, po roce se v naší domácnosti pomalu zabydluje, tentokráte kočičí tříletá dáma z útulku, která to neměla v životě jednoduché a tak snad u nás najde klid hlavně na duši (i když moc nejásám, protože ji určitě aspoň na začátku nedají pokoj naše holky, ale my si je usměrníme). Už aspoň vím, jak se bude jmenovat další pokračování ságy našeho rodu.'),
(6, '2016-06-29 13:10:45', 'Jsem všemi směry nechtěný a zavrhnutý. Kočka mne ignoruje a vychází z úkrytu až po setmění (že by upír?) a ještě jen do náruče mé polovičky a děti se už od rána ptají na příjezd mé drahé.\r\n "Už je tu maminka? Teď jo nebo ne nebo jo?" \r\n Asi jen mlčím. Mohl bych se svou mlčenlivostí přihlásit na post tajného agenta, kterého vždy chytí. Ale nic z něho nedostanou. \r\n Ještě, že aspoň ta naše fenka mne na procházce trochu poslouchá. Nebo poslouchám já ji?'),
(7, '2016-07-04 06:14:12', 'Po týdnu, kdy se k nám nastěhovala další účastnice našich životů lady kočka, jsem ji viděl přesně devětkrát. Zatím. Ale třeba se to zlepší. Dvojčata za to vídávám pořád a to za každých okolností (maminky na mateřské jistě tuší a chápu). Sednete si, je tam jedno z dvojčat, jdete něco dělat, ať je to na zahradě, doma nebo v autě, za zády číhá nějaké dvojče jako skrčený jaguár, aby v mžiku vyrazilo do útoku. Holky nechodí ještě do školy, ale tento způsob závěru školního roku a začátek prázdnin zdá se mi poněkud nešťastným. Už jen proto, jak střídavě prší a svítí slunce, protože ty naše tygřice pak v dešti nemohou ven a doma vymýšlí bejkárny, které ale s drahou polovičkou registrujeme na půl oka, protože nám už veškerá energie odešla do věčných lovišť. A abych nezapomněl, naše dcera o minutu mladší se vehementně dožaduje za každých okolností jakékoli jízdy osobního řízení automobilu. Už jsem jí i názorně ukázal, že zkrátka nedokáže dosáhnout na pedály a při tom vše sledovat za čelním sklem. Takže pokud jsou tu nějací policisté, vydávám prohlášení, že pokud uvidíte v našem autě blond šošolku na straně řidiče, tak rozhodně kauci neplatím.'),
(8, '2016-07-07 09:41:08', 'Jo! Po rozboru našich fyzických i duševních rezerv jsme se s mojí milovanou polovičkou dohodli, že si naše holky přes prázdniny zaslouží každý týden jeden den ve školce. Budiž pochváleno využití času bez přisátých dětí na noze nebo na zádech. Sundávám i cedulku "Zákaz pištění" a možná vylezou ze svých úkrytů i naše zvířátka. Nu, aspoň se na ně pak budeme víc těšit.'),
(9, '2016-07-12 10:07:01', 'Nevím, zda doba jde dopředu a už i malé holky všechno umí, nebo už já myslím zpátečnicky. Trochu tu máme rozvrtaný dům a k tomu předělávám plot (na lepší, hezčí, větší). A tak mám nářadí připraveno na vrtání, řezání, smirkování, vyměřování, seřizování, upravování. Jenže - to bez asistence dvojčat zkrátka asi neudělám. Takže se můj čas předělání plotu neúměrně prodlužuje už jen z důvodu neustálého hlídání si svých věcí, potažmo odhánění obou asistentek alespoň o tři metry dál (i když si někdy myslím, že mají ruce delší než Saxána).\r\n "Tatínku, já ti pomůžu..." tahle věta se sice ku potěchu ucha ozývá stále častěji, ale ku potěchu mysli a oka už to tak vábné není. \r\n "Jestli mi chceš pomoct," beru dceři z ruky vrtačku, "zkus si uklidit svoje hračky u pískoviště." Snažím se být důsledný otec, ale asi to nejde.\r\n "Ne! Já ti pomůžu, já to UMÍM!" zaryla vrtačku do prvního dřeva, které bylo po ruce. Hbitým hmatem jsem si svoje nářadí ukořistil nazpět. Ale nejsem chobotnice, i když si to asi přeji. A tak odebírám pilku, protože to taky UMÍ, strkám si do kapsy všechny smirkové papíry, protože nebrousí jen dřevo, ale i plastové krabičky se šroubky a kladivo, to jsem raději hned uložil. \r\n "Tak já ti pomůžu s tímhle," bere do ruky prkna na plot a málem mě zezadu nabere. \r\n A tak jdu do domu hledat čapku s bambulí, protože toto předělávání plotu rozhodně zavání dalším celovečerním filmem á la Pat a Mat.'),
(10, '2016-07-15 23:04:56', 'To je tak, když emancipace žen dosáhne osvícení a povýší na nejvyšší level. Zkrátka vzkaz ženy muži. Papírek jsem našel volně ležící a na něm napsáno - NECH JE VENKU.\r\n Ale dobře, aby se mi pak má drahá polovička nepomstila, že zde uvádím lid v klam, přidávám kvízové odpovědi (tak, která to bude ta pravá?): A) Mám nechat všechnu havěť venku, tedy i děti B) Mám nechat venku dozrát meruňky C) Mám JE (vršek nebo spodek?) nechat zkrátka venku v tomhle počasí.'),
(11, '2016-07-17 22:46:07', 'Někdo se tu mění na pořádné harpyje a já to rozhodně nejsem. Mám taky pocit, že žiju v zemi skřítků, kteří na mě skáčou ze všech možných pozic a co horší, kam se podívám, nějaké to maličké vřeštící stvoření pohledem potkávám, proběhne a znovu zmizí v Zemi Nezemi. Když zrovna není oční kontakt, dostávají zabrat moje uši, které, kdyby byly sonary, by jistojistě už skončily ve šrotu. Někdy si připadám jak v jedné hře Cimrmanů - TADY VŠUDE SEDĚL(Y).\r\n Ale jinak ty naše dvojčata mám rád. Třeba právě nyní, když píšu tyto řádky. Poslouchám chůvičkou (no ano, ještě ji máme, protože když dole třeba píšu, tak holky poslouchám, zda se třeba neprobudí, PROTOŽE nechávám svou milovanou polovičku pořádně vyspat, neboť je to důležitý - pracující - článek naší domácnosti) tikot hodin u dvojčat v pokojíku a slyším i jejich malé chrápáni. Tak jsme je snad konečně dnes o dost víc utahali...'),
(12, '2016-07-19 23:47:35', 'Pondělí mělo být naše. Bez dvojčat, která se tou dobou bažila pozornosti ostatních dětí ve školce (fakt díky, že někdo pracuje s nejmenšími i o prázdninách). a tak jsme zase stihli něco málo - více - zařídit ohledně domácnosti. Čas letěl podle Karla "jako bláznivý" a "já nechytím ho, ani vy," což bylo evidentní hned jak jsem zasedl do křesla na terase, protože k dotazu mé milované kolik je hodin, se naštěstí ozvala za poza plotu naše príma sousedka, která je shodou okolností čerstvá mamina:\r\n "Bude půl pátý..." prolétlo hodinové numero až k nám na zahradu a za mého spokojené brblání, že bychom takové živoucí hodiny potřebovali, jsem se znovu zvedal a s polovičkou odcestoval směr školka. \r\n To, že jedna chtěla okamžitě domů a druhá tam chtěla zůstat (možná by tak i klidně přespala), ani nemusím psát. Jenže my se tak rychle domů nedostali. Vezl jsem s sebou i recyklaci. A ta se dala vyhodit jedině u DALŠÍHO DĚTSKÉHO HŘIŠTĚ. Prima. Holky chtěli ještě na houpačky a tak nezbylo, než vypnout motor a zkorigovat hraní našich dcer. První zvítězil písek, který tam byl vlastně všude. Druhou atrakcí byla houpačka. Naše dcera o minutu mladší ale zrovna asi trénuje do kosmodromu a tak naše jednohlasné "přestaň se houpat to moc" vzala poněkud laxně. \r\n Opožděně začala žadonit, abych jí zastavil v houpání. Zastoupil mne vedle stojící tatínek malého caparta, i když jsem k ní co nejrychleji utíkal vykonat zastavovací povel osobně. Mrška, jakmile ji pán zastavil, hned utíkala na jinou atrakci. A tak má drahá zavolala:\r\n "A jak se říká, když ti pán pomohl?"\r\n "Dobrý den," ani se naše dvojče neohlédlo a upalovalo na skluzavku. Maminky, co tam byly s jinými dětmi se málem udusily pískem, jak se smíchy ohnuly...'),
(13, '2016-07-24 22:38:50', '"Nemělo pršet?" zazněl právě z mých úst dotaz na velké vedro a dvojčata skočila do bazénu. Mají na rukou křidélka a vypadají jak dva přerostlí motýlci, respektive jak obtěžující hmyz, protože když nejsou v bazénu, chtějí se válet za každých okolností po nás, což třeba při kopání vsakovací jámy pořádně nejde. Tak si jdeme udělat s mou drahou polovičkou kávu, abychom se posléze usadili naproti bazénu a sledovali koupající se panoramata našich holek.\r\n "Skoč tam, máš rukávky..." instruuje jedno dvojče.\r\n "Ne, já neumím plavat," kontruje druhé.\r\n "Ono tě to nadnese, neboj se," stříká na ní vodu.\r\n "Já se bojím," žvatlá první a ručkuje po bazénu. \r\n Druhá se vrhá střemhlav doprostřed bazénu a v tu chvíli se mění z motýlka na mořskou bójku. Dát ji na hlavu zvoneček, tak má nové zaměstnání. Nu co, my jdeme s mou drahou raději v tom horku sázet další novou květenu přivezenou ze zahradnictví (asi už třístá padesátá druhá várka na naší zahradě).'),
(14, '2016-07-25 23:46:25', 'Jedeme autem a zpíváme s mou polovičkou dvojčatům dětské písně. Asi jsme nebyli pochopeni, respektive náš dvojhlas nebyl na širší nominaci v Superstar. Dcera o minutu starší začala pusou pípat a pak řekla:\r\n "Ticho! Už jsem vám ztlumila zvuk..."'),
(15, '2016-08-01 21:30:45', 'Písnička s xylofonem ...zavoláme na dědečka, ten má velké KLADAVO... Nevím, co je snesitelnější. Zda neustálé komolení názvu věcí nebo vysoké tóny xylofonu.'),
(16, '2016-08-01 21:31:04', 'Dnes jsme byli v nedalekém lázeňském městě na projížďce lodí po druhé nejznámější řece. Nebo že by první nejznámější? Jenže to by o ní musel pan Smetana jaksi taky napsat nějakou symfonickou báseň, takže asi opravdu druhá. Naše dvojčata se těšila jak na domácí rajskou od mé milé polovičky.\r\n "Už půjdeme na loď? Já už to NEVYDRŽÍÍÍÍÍM!" gestikulovala dcera o minutu mladší jak při herecké etudě na konzervatoři a jistojistě by za projev dostala jedničku a hned by ji obsadili aspoň do oscarového filmu. \r\n Loď dorazila, my si sedli. Asi i ta hodina je pro naše holky moc. Plavba je bavila do poloviny, než jsme se obrátili a pluli nazpět, a tak nám druhou polovičku znovu znepříjemňovaly svými vrtochy, které neskončily ani po návštěvě mého dlouholetého dobrého kamaráda, kterého tímto zdravím a věřím, že jsem mu dostatečně ukázal, co ho jednou čeká a moc se mu omlouvám, že místo demoverze mu bylo nedopatřením ukázáno pravé nefalšované odpoledne s dětmi na návštěvě.'),
(17, '2016-08-02 14:48:52', 'Zašli jsme si na procházku podél řeky. \r\n "Holky, tady někde by měla být taková zvířátka, nechcete se podívat?" pátral jsem v paměti, jestli to tam opravdu bylo. Bylo. \r\n "A co to je? Jak se to zvíře jmenuje?" vyzvídala dvojčata.\r\n "To jsou nutrie," hrdinně oznamujeme a několikrát znovu opakujeme pro snazší zapamatování. \r\n Rodinka nutrií nebyla plachá, dokonce se dožadovala krmení. Ale už musíme odcházet a tak je ještě pozorujeme z dálky, jak si plavou sem a tam. A ještě jedni rodiče s dětmi je tam přišli nakrmit a hází jim tvrdé rohlíky. Prochází také kolem párek postarších manželů.\r\n "Podívej se, ty velký... myši jedí i rohlíky," byla docela překvapena paní.\r\n "To by ses divila, co všechno jedí," kontroval jí manžel. \r\n Procházeli zrovna při tomto hovoru kolem nás a dcera zamračeně poslouchala jejich družný rozhovor. \r\n "Mamíííí, jak jsi říkala, že se to jmenuje? Paní říkala, že je to myš!" zatahala za rukáv mou polovičku.\r\n "Nutrie to je," znovu, po stopadesáté, zopakovala má drahá.\r\n Dvojče zaujalo bojový postoj, nahrbilo se, zamračila se ještě víc a našpulila pusu. Opřela se do odpovědi, která se nesla až ke starším manželům.\r\n "Nutrie! To jsou NUTRIE!" \r\n Paní se na nás podívala, zasmála a opravila se.\r\n "Nutrie. To nejsou myši, omlouvám se, já jsem to tak jenom řekla, máš pravdu."\r\n No, někdy holky zlobí, ale o to víc pak dokáží rozesmát.'),
(18, '2016-08-04 10:17:13', 'Televize Nova dnes spadla jen z části. Její trosky budou vystavovat jako exemplární případ. Kdo neviděl, může se zítra podívat na web novy :) To jediné jim zbylo.'),
(19, '2016-08-05 11:37:24', 'Fotky a videa zatím na tyto stránky nezavedli. Pokud se chcete pokochat i vizuálně, podívejte se na facebook. Všem hezký den.'),
(20, '2016-08-07 09:07:41', 'Když se vrátím ke včerejšímu oslavnému výletu, tak docela rychle zjišťuji, že dvojčata co neví, to nepoví. Moje kamarádka, která mi zcela pohodově svezla dvojčata na konících, se za tu hodinu dozvěděla tolik novinek o naší domácnosti, že pan google a bonzák facebook je proti tomu neškodný software II. kategorie. Vehementně jí zkrátka musely vyžvanit cokoli z našeho okolí a když si nakonec hřebeček vykonal potřebu, a Emu to začalo zajímat, došlo i na rozdělování pohlaví a důležitou dětskou otázku: Na kterou stranu že se to kamarádka vlastně taky dala, jestli má onoho nebo onu. Přestávám tedy v domácnosti mluvit, vše si s drahou polovičkou budeme psát a poté papírek spálíme jako tajní agenti. Bude to tak jistější.'),
(21, '2016-08-07 16:04:29', 'Už vím, jak na naše dvojčata. Dobře, přiznávám, asi toho máme hodně, nezastavíme se a pak to najednou přijde. Už když jsme dnes jeli do zahradnictví, říkám polovičce, že jsem už unavený, jestli nechce řídit, což s díky odmítla. Přijedeme a už mi hlásí, že jí "taky nějak těžknou oči." Resumé všeho bylo, že jsme oba usnuli na pohovce v obýváku na celé dobré dvě a půl hodiny a naše divy si dokázaly vyhrát společně, potichu, bez hádek a rozbitých věcí. Už trochu otevíráme oči, když mou drahou probudí zcela a k smíchu tento rozhovor:\r\n "Mám koníka a jdu ho krmit. Bude mít těstoviny," glosuje Amálka.\r\n "A co má pejsek?" zvídavě zasahuje do krmení plyšáků Emča. \r\n "Ten má čůrání..."\r\n "Neeee, neeee! Čůrání neeee, to se NESMÍ! \r\n Dobré ranní nedělní odpoledne všem.'),
(22, '2016-08-10 11:48:22', 'Žily byly dvě Karkulky, které si neustále hlídaly záda, takže vlk na ně nikdy nemohl... Stavili jsme se všichni v lese na houbách, ale přinesli jsme jen ostružiny a pár houbiček na malou bramborovou polévku. A protože (zase) pršelo, nebylo dvojčatům moc po chuti si vzít nepromokavé červené pláště. Zkrátka nemohou být neustále jak na přehlídkovém mole.'),
(23, '2016-08-13 17:52:27', 'Když jsem nemocný já, musím mít roušku, abych nikoho nenakazil. Protože jsou doma všichni nemocní, zas musím mít roušku já, abych se nenakazil. Dvojčata i přes nepřízeň počasí a teplot spolu s kašlem stejně pořád dovádí a dělají vše pro to, aby si v noci synchronně zakašlaly z "plných" plic. Už spíme i na malých polštářcích, protože ty velké jsme dávno darovali do dětských postýlek na podložení marodů. Má drahá už též ulehla. Tak teď tu rýmovou nemoc čekám taky.'),
(24, '2016-08-15 20:23:40', 'Při každodenním venčení naší fenky jsem rád, když jdeme bez holek, protože se s nimi vždy děje něco navíc a místo relaxu se neustále cokoli řeší. Dnes jsem ty naše spomalovače chůze vzal s sebou. Procházka na poli byla završena sběrem těch dosti lámavých stébel plodin po sklizni.\r\n"Holky, to neberte! Nebudeme dělat nepořádek  na zahradě!" marně oponuji.\r\n"To je pro sněláky!" hrdě hlásí Ema.\r\n"Pro co?" snažím se pochopit myšlenku. "Ale i tak to neberte!"\r\n"Pro SNĚLÁKY! Až ho postavíme." opakuje i Amálka.\r\n"Jo! Pro sněhuláky!" pochopil jsem zbožné přání dvojčat.\r\nTakže kdybyste nevěděli, ono divné počasí je díky kouzlům našich holek. A zítra už začne sněžit!'),
(25, '2016-08-19 09:19:21', 'Jsme na Starých Hradech. Dvojčata si užívají pohádkovou prohlídku s princeznou, kterou si prohlížejí s otevrenou pusou. Princezna se přítomných dětí ptá na rozličné pohádky, az nakonec využije kouzelné zrcátko.\r\n"Tak se podíváme, jestli funguje a vidíte tu v zemi nejkrásnější," glosuje všeznámého "čuribrka." Je to divné, ale jak děti tak i dospělí se stydi pochvalit se v odraze skla. Až na naši tři a půl letou Amálku. \r\nZakroutila se a pochvalně a spokojeně si broukla. Je v zemi nejkrásnější.'),
(26, '2016-08-29 13:38:38', 'Měl jsem tu už od rána mládežnický sabat. Obě holky se ani nechtěly pořádně učesat, takže z vlasů měly stejný paskvil jako divoženky a vehementně se dožadovaly svých šatiček kvůli jedinému důvodu. Tanec. Sledoval jsem je dobrou půlhodinu, dokonce jsem si to ladné labutí jezero i natočil. Pak jsem však musel odložit i to natáčení, protože s žádostí o tanec jsem zkrátka nemohl odmítnout. Nečekal jsem, že to bude více jak pět minut. Další půlhodina to jistila. Takže jsem měnil i tričko.'),
(27, '2016-08-31 08:28:57', 'Ještě tři měsíce budu mít tu super úžasnou práci na plný úvazek 24/7 s benefity jako dvě minuty na vypití kávy, stále přeplněný prostor na WC nebo nedochvilnost nezaviněnou mnou. Při tomto zaměstnání je prokrastinace zcela utlumena, i když to mnozí stejně nevidí a závidí vám zdánlivý klidný odpočinek. Ještě tři měsíce a pak budu na hodinu propuštěn bez možnosti návratu. Odeberou mi titul RnRD. (rodič na rodičovské dovolené) jako v Plzni a už budu jen rodič. Za tu dobu, co ty naše dvě čertiska existují, se stalo mnoho věcí, zážitků, trapasů nebo jen se zkrátka něco stalo, co stojí za povšimnutí ale i mávnutí ruky. Když jsem Dvojčata na útěku začal psát, byli jsem už v novém domečku. Co se ale dělo před tím, to skoro nikdo neví (jen děda Vševěda a dvě naše kamarádky). A tak mi za chvíli říkejte Jardo Vrchlický nebo Emile Frído, to je jedno, protože se jdu prohrabat rodinnými bájemi a pověstmi. Bude to psina.'),
(28, '2016-09-01 23:05:35', 'Už od rána nemohu naše holky nikam dostat okamžitě. Ani do koupelny, ani na jídlo, ani na zahradu. Jakoby instinktivně vycítily nejhorší dětské datum 1. září. Dokonce si udělaly z gauče domeček a nevěděl jsem o nich dobrých dvanáct minut. Jsem zvědav, co budou dělat, až opravdu půjdeme do školky, potažmo jaký bude ten jejich první školní den. Ale to už budu připraven: páčidlo, hever a pro jistotu dvakrát denně zvedání činek. Tak vítej nový školní roku. I všem ostatním a nejen dvojčatům.'),
(29, '2016-09-05 15:12:39', '"Nezlobte, nebo nikam nepojedeme," ano, tato věta zní asi ve všech domácnostech s dětmi. Jenže děti jaksi asi už od narození vědí, že vyhrožování je jistá forma terorizmu a s teroristy se nevyjednává. Pokud by to tak bylo doopravdy i mezi dospěláky, banky by se nevylupovaly, nikdo by se neunášel a byl by klid. Takže se s teroristy ve formě rodičů, kteří mají nerealizovatelné požadavky na děti á la "přistavte sem hned letadlo s plnou nádrží a chci azyl v Kanadě," tak to se zkrátka neujme téměř nikdy. Takže to, že naše holky v sobotu zlobily, nebránilo obměkčení mě i mé drahé, že jsme je vzali na jejich vlastně první pouť, když nepočítám tu, kdy ještě byly v kočárku a nic jim neříkaly ani balónky nebo kolotoče. V kočárku je zajímala jen hudba z kolotočů. Teď se to obrátilo. Opravdu jsme vyzkoušeli všechno. Tedy děti. Mne má polovička nedostala ani na výškový řetízák a když mi ukázala jakési kyvadlo a následně v horkém dni prozkoumala letmým pohledem mou i přes opálení bílou pokožku, usoudila, že ani to ji letos nečeká. Pozor! Ano, vlastně jsme všichni šli na malou horskou dráhu. Už chyběli jen ti permoníci kolem, i když horská dráha u vody se taky dobře vyjímá. A druhé pozor! Dvojčata si vyzkoušela každou atrakci jednou a hned se bez odmlouvání vrhaly na další nabízenou. Jen ti koníci, ti museli být dvakrát.'),
(30, '2016-09-06 10:39:48', 'Ema stále nazývá čokoládu ŠOKOLÁDOU. Možná je to ten správný výraz, protože když ji někdy dostane, jsme šokováni my nabitím její energie.'),
(31, '2016-09-08 00:27:02', 'Chcete zažít kousek hororu? Mějte zapnutou u sebe při práci večer dětskou chůvičku. Jako dnes. Už je pozdě. Ještě dodělávám práci na PC a všudypřítomné ticho protíná jen vteřinové cvakání hodin z reproduktorů chůvičky. Ano, mám ji nastavenu na nejvyšší citlivost. Možná jsem se i v této půlnoční hodině zamyslel. Avšak nelidský tón pištící Amálky mnou trhl že i mráz po těle projel jak kulový blesk a Jája (moje žena) prý málem spadla z postele. Trochu jsem si na chvíli i myslel, že jsem v nějakém Hitchcockově filmu. Odteď si dávám chůvičku daleko od sebe a s hlasitostí to nebudu přehánět.'),
(32, '2016-09-12 12:04:20', 'V pátek jsme cestovali metrem. Holky mají vláčky rády. Ale nedokážou pochopit, že metro , tedy ta souprava metra zkrátka nemá komínek, ze kterého se kouří. Projeli jsme si jak staré vagóny, kde se sedí po stranách na dlouhé lavici tak i to novější, kde už jsou ty sedačky jak na matějské pouti u hlavní atrakce, která se v nekontrolovaný okamžik převrátí a sedačka stokrát otočí kolem své osy. V té staré soupravě ještě nebylo tolik lidí a tak měly dvojčata možnost více vše kolem sebe pozorovat. Jako paní, která seděla nedaleko nás. Amálka se na ní zaměřila a svá slova umocnila ještě ukazováním na příslušný objekt zájmu, což jsem jí pro jistotu několikrát zatrhl, ale ne asi v čas. \r\n\r\n"Tatínku, ta paní má šaty jako já," nadšeně zvolala a prst ukazováčku se jí na dálku zaryl do šatů paní, která se věnovala svým poznámkám, které si zrovna vypisovala na papír z telefonu. Ať žije technika. \r\n\r\n"Neukazuje se," radím etiketu dceři, ale ta dál pokračuje.\r\n\r\n"A má taky motýlky, jako já," raduje se Amálka dál a usmívá se na paní jako sluníčko. Jiná žena by byla spíš naštvaná. Nosit podobné šaty v okruhu pěti kilometrů je přece přísně zakázáno.\r\n\r\n"Ano, paní má skoro stejné šaty i s motýlky, jako ty," snažím se jí tu vtyčenou ruku stále dávat dolů.\r\n\r\n"Ano, ale paní je má větší, já menší" začíná víc a víc zářit Amálka, že by téměř celé metro mohlo své osvětlení vypnout. Možná ta zář nebo spíše slova vedená na její adresu paní vytrhává z přemýšlení a podívá se směrem k nám.\r\n\r\n"Pardon, to bylo na mne?" zeptá se opatrně dáma a usměje se. "Nebo ne?"\r\n\r\n"Že máte podobné šaty jako dcera i s motýlky," vysvětluji paní na dálku, že to zaujme i pár dalších cestujících. Paní se na holky ještě několikrát usměje a je asi potěšena zájmem o své šaty. Já jsem rád, že máme prostor zmapovaný. Ale cesta bude dlouhá. Třeba nás potká přímo profesor se sbírkou motýlů.'),
(33, '2016-09-15 12:20:20', 'Je vidět, že v domácnosti jsem jediný chlap. Pro hvězdopravce bych názorně přirovnal naši rodinu ke sluneční soustavě, kdy já jsem středobod, žhnoucí slunce s kódovým označením R1 a kolem mne rotují dvě malé planetky Amalkus a Emčoid s jednou větší planetou Jájodemou (manželka), kolem které obíhají dva měsíce Leonid (fenka) a Terkos (kočka). Jenže i slunce má své povinnosti a jenom svítit prý nemůže. Protože třeba dnes - no tolik direktiv jsem snad nedostal za celý svůj celkem dlouhý život. Ráno je první na nohou Emča a hned se dožaduje pohádky, kterou ji (jako vždy) zatrhnu do té doby, než si udělá ranní hygienu a sní snídani. Ségra jí za chvilku následuje, ale jen dívání se do zrcadla jí zdrží o nějakou minutu (dvě, deset) víc. Při jídle mi zklamaně hlásí (už asi celý týden ve stejnou dobu), že si myslely, že už přilétl Ježíšek a že tam bude stromeček a že budou Vánoce. Kdo by chtěl, půjčím holky na tento dlouhý dialog, abych jej již nemusel absolvovat. Po snídani už vyrábím svačinu, která je doprovázená slovní hrou CHCI-NECHCI, takže se ingredience na připravovaném jídle mění každou vteřinou. Ne, nenechám si do toho mluvit. Nakonec stejně dostávají to, co jsem si vymyslel už při vstávání (dělám jim to samé, co mám já :D) Odhazuji rondon kuchaře Kuřátka a za švitoření dvojčat, ať jdu s nimi tančit, ať jim ukážu obrázky v knížkách, ať s nimi připravím imaginární polívku, ať jim pořádně utáhnu copy, co jsem právě udělal, ať jim konečně pustím tu pohádku, ať, ať, ať... Švitoření jak na letišti. Ale vlastně se u nás nic neděje. Jdu se zase transformovat na slunce. Dvojčata mi visí za ruce a mačkat písmenka s patnáctikilovým závažím je dosti nereálné.'),
(34, '2016-09-15 23:44:46', 'Vždy jsem kolegy a kolegyně z práce dříve iritoval jistým číslem, které se neustále zmenšovalo. Nyní, maje stále rodičovskou se tak trochu užírám, komu bych to zase podsunul. Takže jste to odnesli vy všichni na této stránce :D - VÁNOCE JSOU PŘESNĚ ZA 99 DNÍ!!!'),
(35, '2016-09-19 11:15:21', 'Náročnost víkendu podtrhl razantní přechod z léta na podzim. Pro někoho rovnou na zimu. respektive někdo se z Antarktidy přestěhoval zpátky do Čech, neboť se podmínky v obou destinací vyrovnaly. Holky počasí moc nezajímá (až na to, proč už nemohou nosit celý den šatečky) a poklidný sychravý víkend podrývají svými neustálými zápasnickými výstupy. Ale zvládáme to (musím se zdrogovat hořkou čokoládou). Dostatek energie jsme završili nedělní domácí schovávanou. Poznámka: nemám se v domě kde schovat. Prostor se nedokáže přizpůsobit mému tělu a tak vždy něco vyčnívá (ruka, noha, hlava, bačkora pod závěsem). Jája (žena) splynula i s digestoří. Raději se ohlížím, zda místo v práci někde na mne nevykoukne.'),
(36, '2016-09-19 14:11:23', 'Není nad upřímnost dětí, když mají třeba jíst.\r\n "Holky, oběd!"\r\n "Nechci guláš, chci jen těstoviny!" hlásí Emča.\r\n "Bude něco jiného..." už skoro neodpovídám, neboť jsem unaven jejich nekompromisní pondělní neposlušností a dávám jim ohřáté misky chutné mňamky na stůl.\r\n "Fuuuuuuuj!" letí vzduchem až do kuchyně Emčina poznámka a dál pokračuje v nabádání ségry. "Amálko, řekni taky fuj!"\r\n "Fuuuuuj" ječí obě jako duo Yamaha.\r\n "Dobře," zachovávám klid (což je nezvyklé). "Až přijde maminka, řeknu jí, že jste to její výborné jídlo označily jako FUUUUJ. Asi nebude moc ráda..." Zkrátka jsem zkusil psychologický teror.\r\n "Mňaaaaaam, to je dobrota!" vrhají se obě na lžíce. \r\n Ha! Takhle se na ně musí!'),
(37, '2016-09-21 23:19:42', 'Buď je to podzimem, nebo nárůstem domácích deliktů dvojčat, ale už jsem nevydržel (a to je teprve úterý) a přešel z obyčejného hrníčku na kávu na mega brutal lavor na kafe, kam se vejde přesně dva a půl šálky kávy. Poradíte někdo ještě nějaký jiný stimul (kromě hibernačního spánku)?'),
(38, '2016-09-21 23:19:57', 'Dnes slyším ty naše (pod)vodnice zcela nekompromisně lákat cizí děti k nám na zahradu. Zaručeně v "dobrém úmyslu." Nu, posuďte sami:\r\n "Ahoj holčičko..." haleká na zídce Emča.\r\n "Ahoj druhá holčičko," sekunduje jí Amálka ve snaze nalákat i druhou oběť (oboje oslovení je autentické)\r\n "Pojďte k nám na zahradu. Půjdete? I s koloběžkou?" haleká dál Emča...\r\n Tak ony prachsprostě bez našeho dospěláckého požehnání dohadují gardenparty za účelem získání koloběžky, tedy aspoň na chvíli ježdění! Pořizuji ceduli na vrata: Pozor, pes a záludné děti!'),
(39, '2016-09-26 12:42:24', 'Je tu něco špatně? Před chvilkou vstávám. Holky se už dívají na nedělní pohádku a tak je na mě, abych jim připomněl slušné mravy.\r\n "Ahoj holky..."\r\n Nic\r\n "Ahoj holky!" zase nic. Žádná registrace osoby tatínka u nich stojící.\r\n "Ahoj holky!" stoupám bezmocně před obrazovku.\r\n "Ahoj holky..." odpovídá Amálka.\r\n Už mne přehlížejí a to jim nejsou ani čtyři roky...'),
(40, '2016-09-27 09:05:03', 'Od té doby, co jsme si (hlavně z iniciativy mé drahé) pořídili z útulku další dvě dámy (jednu psí a jednu kočičí, takže jsem osamocen v ryze dámské domácnosti a ještě na rodičovské, takže tyto dvě příměsi mne každý u zrcadla nutí prohlížet mou hruď a s hrůzou čekám na den, kdy budu muset kupovat první podprsenku, protože můj mužský genom v této velké přesile nemůže dlouho obstát), se nestarám jen o naše holky, ale i ty zvířecí. A to doslova ve dne i v noci. Jako dnes po půlnoci. Fenka vyje. Zaposlouchám se, ale žádné houkačky integrovaného záchranného sboru neslyším. ťukání na okno nepomáhá, vycházím ven. Volání nepomáhá, vytí se ozývá z boudy. Volám do tmavého otvoru boudy jako do jeskyně a jen doufám, že nevyleze místo psa medvěd. Chvilka ťukání na boudu spolu s mým hlasem konečně zabírá a totálně dezorientovaná a rozespalá vylézá madam ven a když mne viděla, samou radostí by mi skočila do náruče. Takže i psům se zdají strašidelné sny! Jsem zvědav, koho budu budit příště.'),
(41, '2016-09-28 23:08:28', 'Oslavy dnešního svátku jsme pojali zcela jinak - místo gratulacím svatého Václava jsme chtěli uctít památku jeho věrného oře. Bylo dohodnuto s naší kamarádkou, že se dvojčata svezou na konících a na tajňačku jsem dohodnul druhé duo na koních - mě a mojí ženy Jáji. Holky koně milují, Amálka až tak, že si vybírá barvu koně, na kterém bude jezdit, což nám moc neulehčuje, protože poníka narůžovo přebarvovat rozhodně nehodlám a ochránci zvířat by mi urvali jistojistě ruce. Druhá varianta byla mít koně černého, ale k dispozici byl jen hnědý. Problém byl po pár minutách zažehnán. Jen co slezly z koně po projížďce, chtěly k nám na ramena, takže z opravdových koní rovnou přesedlaly na naše hřbety. Kdyby to šlo, bude nějaký kůň i na naší zahradě.'),
(42, '2016-09-29 09:49:16', 'Včera bylo svatého Václava. Abyste byli svatí, musí u vás zaznamenat prokazatelně aspoň dva zázraky, respektive za jeden jste blahořečen za blahoslaveného, za druhý už jste svatý :D toliko z teologie. Všichni rodiče by tím pádem měli být svatí. I já. Vybavuji si dvě věty, které sem tam slýchávám: "Jakým zázrakem se vám povedly dvě (děti)?" a "To je zázrak, že to jejich pištění vydržíš." Pak tu ještě máme malé zázraky ve smyslu: "Zázrakem přežil útok svých dětí z rána," "Vy máte doma taková dva malé zázraky, co?" nebo méně lichotivé: "To je zázrak, že to ty děti s tebou tak dlouho na rodičáku vydržely..." \r\n\r\nTak jsem při tom psaní vypil svou ranní půllitrovou kávu a raději jdu holkám nakreslit zase sluníčko, které si tu vystřihují z papíru (prý jim dneska Jája koupí raději nůžky pro děti, takže mne už nebudou zbytečně ohrožovat) a  držte se, rodičové (nebo ti budoucí). Jsem s vámi! ;-)'),
(43, '2016-09-30 12:48:14', 'Postoupil jsem do vyšší politiky. Nemám to lehké, ale dokážu to ukočírovat jak starý Humberto celé šapito rozhádaných artistů a komediantů. Od rána se totiž (no, možná už od včerejška) hádají o jednoho ledního medvěda. Patří Emče. Ale dlouho ho nechtěla (čert ví proč) a když ho nyní objevila Amálka, hned jí padl do oka. Jenže se k němu stará majitelka zase přihlásila (čert ví proč) a začaly hádky. Amálka pláče, že ho chce, EMča prohlašuje, že jí ho jen na chvíli (na pár hodin) půjčí, mě z toho jde hlava kolem a neustále je obě přesvědčuji. Jendu o dlouhodobé zápůjčce medvěda, druhou, že má toho svého, hnědého, tak ať si ho vezme a nepláče. V poslední fázi přesvědčování je dokážu roztrhnout. Umlčet dav však nelze. A tak nedělám skoro nic jiného, než přesvědčuji, slibuji, vyhrožuji, lstivě argumentuji a hystericky pochytávám reakce dvojčat. Jo, je pátek, ale proč v sobotu a v neděli nechodí děti do práce?'),
(44, '2016-09-30 23:06:35', 'I to dnešní koupání rozjetých dvojčat vypadalo jak boj Poseidona s Krakenem. To tuhého začalo jít, když se obě malá individua začala štípat. Nejvíc na zadku. \r\n"Nechte si ty kaďáky!" chtěl jsem zůstat drsně chlapsky nad věcí.\r\n"Ne, to jsou sedínky, tatínku," opravovala mě se smíchem žena.\r\n"Rozhodně kaďáky," nedal jsem se obměkčit. \r\n"Počkejte! Chci vám něco říct!" rozhodila rukama jako v rozstřelu Emča. Zhluboka se nadechla a s vážnou mimikou sdělila jádro věci:\r\n"Jsou to KADÍNKY!"'),
(45, '2016-10-02 18:24:58', 'Už je říjen a dýňový měsíc máme před sebou. Já osobně mám rád dýni jako JÍDLO, ale holky někde zase viděly ty hrozivé dýňové hlavy a tak nás čeká ozdoba plotu á la dýňové strašidlo. Ale aspoň tím jídlem jsme začít všichni museli. Jsou to výborné A ZDRAVÉ recepty z Jájiných pokusů - ano, podle receptů mé ženy, protože mě to tak chutná a kamarádům taky, že mě přemlouvali, abych já ji přemluvil, aby se ona přemluvila k založení stránky (https://www.facebook.com/jajinypokusy/) - třeba někomu také udělají radost jako nám. A našim dětem taky moc chutná, což je dobře. Ještě, že se po tom určitě nebude dát ztloustnout na metráčka. P.S. Holky se učí už od tohoto týdne aspoň jíst vidličkou a nožem. Baví je to. Pak už jen pozvat pana Špačka na hodinu slušného chování a máme doma rozené andílky (s ďáblem v těle).'),
(46, '2016-10-02 22:23:03', '"Amálko! Seď na tom záchodě normálně!"\r\n"Ano... lalalala"\r\nZa chvíli je ticho, BUM, tupá rána, brek, dítě se valí z pootevřených dveří WC s kalhotami u kotníků.\r\n"Amálko!"\r\n"Maminkoooo, já spadla! VZLYK! Bolííííí!"\r\n"Kolikrát jsme ti říkali, že se nemáš na prkýnku nahýbat dopředu?"\r\nNevychytala to, zkrátka přestřelila těžiště. Snad už si ty fyzikální zákony i Amálka bude pamatovat.'),
(47, '2016-10-03 15:01:44', 'Další připomenutí (krom adekvátního počasí) podzimu ve formě slibovaných hlav dýní jsem započal dnes. Holky se těšily, až ta dýně bude svítit a horlivě radily (tady to máte dámy, už nám dirigujete domácí práce od útlého mládí :D) jak mám každou dýni udělat. Jedna se mračí, druhá se směje. Zcela a jednoznačně podle zadání a následných požadavků. Trochu v mém výtvoru vidím Amálku i Emču, ale teď jenom označit, která je která.'),
(48, '2016-10-03 23:23:13', 'Dnes dodána na FB profil předělaná, remasterovaná, vytuněná hlavní fotografie stránky :)'),
(49, '2016-10-04 13:19:23', 'Protože za všechno, co se u nás stalo, nyní se děje a bude dít mohou naše dvojčata, chtěl bych prásknout, že i za toto nehorázně deštivě sychravé, zkrátka nevlídně odporné či ošklivě pošmourné počasí mohou zas a znovu naše holky!'),
(50, '2016-10-06 22:35:42', 'Bože, poprvé jdeme na tvůrčí rukodělný koutek dětí od 4 do 6 let. (Nám nejsou ani čtyři, hihi). Holky tam budou samy. Jsem zvědav, kdy mi paní poprvé zavolá. Vypisuji kurz 1:1,5, že do půl hodiny určitě ano. Je mi to nějak jedno, vypil jsem čaj na nervy a půjdu si konečně zformovat tělo. Třeba ho zase za rok dostanu do kondice. Protože už nyní si moje svaly, stejně jako dvojčata, pořád se mnou hrají na schovávanou.'),
(51, '2016-10-06 22:36:17', 'Když se dívám na televizi, nerozpálí mne doběla jen některé "pořady". Pokud se chci vyřvat na balkóně z proletářů, musím i určitě protnout ticho tmy lamentováním nad jménem všech z druhé strany finanční barikády, tedy všech od filmu a televize, respektive od reklam. Ano, reklamy, zvláště ty, které jsou adresovány něžným polovičkám.\r\n"Mami, mami...mami.......mami. Na všechno jsou tu maminky." Nebo: "Výrobce si váží všech maminek..." Co tohle: "Maminka je jen jediná, to ví každý, proto všem maminkám doporučujeme.... " Uroním slzu. Zase se na tatínky zapomnělo. Jak mám být hrdý otec, když už i celosvětové reklamy na nás zapomínají. Když rovnoprávnost, tak i pro tatínky (i ty na rodičovské!) :D Hned zítra zašlu prosebný dopis do nějaké reklamky, že chci příště v polovičce pořadu vidět otce s pracím práškem, který s úsměvem říká, že JEDINĚ TENHLE PRÁŠEK SE ZBAVÍ VŠECH SKVRN! A PAK HO OBEJME DCERA, KTERÁ VYHRÁLA ZÁVOD V NOVÉM TRIČKU. No, a já jdu dát zase další prádlo do pračky. Nestihnu napsat ani jeden text a už mám zase vypráno.'),
(52, '2016-10-07 12:29:14', 'Začínám nacházet nedojedené zbytky jídla po celém přízemí našeho domu. DO něčeho jsem i šlápnul. Bylo to na rychlou výměnu ponožek, neboť jsem určitě nechtěl zkoumat pod mikroskopem, z čeho se daná věc skládala. Vím jen, že jsem ponožky vkládal do pračky ve vesmírném skafandru a i když je venku 8°C, nechal jsem otevřenými všemi dveřmi lehkým vánkem 30 Km/h projet několikrát celý dům. Proč dvojčata chtějí nějaké jídlo, které (samozřejmě jen, když se otočím, na chvilku odejdu nebo jen zkrátka vyrábím další hodnoty naší domácnosti) najednou zmizí, vy si myslíte, že jim to chutná a ono je to naopak a vy pak najdete zcela černou misku bývalých šťavnatých žlutých malin, protože ji holky ukryly do své malé dětské kuchyňky. Jo, v jejich "ledničce" jsem našel uschlé švestky. Ale vždyť já uklízím! Potichu si povídám, když utírám rozlitý hrnek, který se najednou ocitl pod pohovkou a já na něj šlápl. Ne, já na něj nešlápl, byl už rozlitý, tedy aspoň z řeči dvojčat to bylo zřejmé:\r\n"Amálko, to ty jsi rozlila tu vodu?" ptá se šeptem Emča.\r\n"Obě, když jsme lezly na stolek..." uchichtává se Amálka. Ono jim to ještě připadá vtipné! Začne teror. To přísahám. Toho bohdá nebude, aby český tatík z rodičovské po čtyřech utíkal! '),
(53, '2016-10-09 22:35:05', 'Ne, v neděli budeme doma zachumlaní v dece. Aspoň tak mi to Jája den předem tvrdila. Toto tvrzení proťalo ranní pištění dvojčat na naší posteli, protože se (zase marně) pokouší hladit naší kočku. Na mém bělmu se objevily první krvavé žilky. \r\n"Pojedeme do Radotína na trh? Potřebovala bych tam něco koupit," usmála se na mě má milá polovička a mě se žilek na bělmu objevilo o dost víc. Nu což, souhlasil jsem. Rodinný výlet, kde se na Havelském posvícení holky projedou na nějaké atrakci a my si projdeme rukodělné stánky, mne od začátku nadchl. Je přece prima vyměnit teplo domácího krbu za venkovní sychravé počasí. \r\nNe, nelitoval jsem. Co musím vypíchnout byla pohádka pro malé (i dospělé) jak to s tou Karkulkou vlastně bylo doopravdy bylo, kterou sehráli dva pánové na malém jevišti. Nejen naše dvojčata stála přikovaná a bez hlásku poslouchala každou větu pana vlka nebo myslivce. Co se týká nákupu, pořídili jsme stejný, jako udělá průměrná rodina na Vánocích v nákupním centru. Nemohla chybět nezbytná tečka na závěr, projet se na konících. Že já těm (mým) ženským vždycky podlehnu.'),
(54, '2016-10-10 19:04:36', 'Karty se dnes obrátily. Emča má "šťastlivý" den. Už od rána mne objímá, pusinkuje, když něco děláme, vrhá se do toho s vervou (diesel 100), a je šťastná za každé pochválení. Přemýšlím, zda to je od ní nějaký nový tah, protože se každým dnem vyvíjí a možnost partyzánské války proti rodičům, respektive proti našim nervům, je tu stále větší, čím víc poznává své okolí. A samozřejmě, doprovází mne všude. Při praní prádla, při zametání, při venčení fenky (to stejně ráno musí obě, i Amálka), a samozřejmě i na onu místnost, kam musel i císař pán pěšky. Radostna tam se mnou vedla monolog, kdy na konci mi dokonce chtěla dát na ruce mýdlo, aby mi pomohla s hygienou. Člověk tak nějak rezignuje, nechá děti tak nějak automaticky všechno dělat a jen si představuje v nejhlubší paměti modrou oblohu s tyrkysovým mořem a bílou písčitou pláží, na kterou se naklání zelené palmy s velkými hnědými kokosovými plody. \r\n"Tati, tati, tady je Maminka!" ukazuje mi s nadšením na mýdle Emča písmeno M.\r\n"Ano, to jsi poznala správně," jsem trpělivý a čekám na příležitost, kdy budu moci dceru vyexpedovat do krajů obývákových.\r\n"A co je tohle?" ukazuje dál na písmeno F.\r\n"To je písmeno ef, je u E jako Emča, ale je bez jedné čárky. Ef." zřizuji si okamžitě kantorskou učebnu i v té nejmenší místnosti. \r\nEmči prst se zastavuje na dalším písmenu na konci slova. A dvojče doslova vyjekne:\r\n"Tatíííí, tatíííí, tady je poklad! To je mapa! Tady musí být poklad, Vidíš?! Je tu křížek!"\r\n"To je písmeno X..." ohnu se, abych zachoval dekorum a neprskal kolem sebe smíchy.'),
(55, '2016-10-11 21:34:56', 'Dnes jsme byli slamění vdovci a vdovečkyně. Po delší době. Kočka se ztratila na celý den a myslím, že i kdybychom bydleli na Sibiři, raději vyjde v ústrety zmrzlým myším, nežli poslouchat doma dvojí pištění. Fenka byla naopak ráda, že má pozornost a já, já si pozornost už snad ani nezasloužím. Já bych pozornosti na svou osob mohl s klidem prodávat v pojízdném autobuse projíždějícím jihočeskou vískou. Už slyším paní v holínkách jak mi říká:\r\n"Pane vedoucí, dneska mi dejte aspoň třicet deka tý pozornosti. Von mi dědek přijede dřív z pole, tak ať je doma připraveno."\r\nOno mé dny začínají být stále více vyšperkovány představivostí. Můžu si představit, že to dobré jídlo jím (a dojím) sám, že v autě mi křičí jedině rocková hudba nebo v neposlední řadě má nejoblíbenější představa, že dvojčata na všechno ten den poslechnou na jednu dobrou. Ale i dnešek jsem zvládl. Zvládám každý den. A večer si jdu lehnout jako generál, který zase ukočírovat rozvášněnou armádu krvelačných žoldáků toužících po skalpu snad všeho, co se hýbne.'),
(56, '2016-10-12 22:01:06', 'Už sem ZASE našel ustřižené blond vlasy u postelí i s nůžky.\r\nPodlily se oči krví rozsupenému tatínku, pozvedne se, povyskočí, u holek je za chvilinku. \r\n"Co to je? No běda, BĚDA! Počkej, až maminka přijde z roboty! Za to budeš bez oběda! Pro tebe ty, zlobo TY!!"\r\nV poledne, v tom okamžení, dcera skáče z postele, tvrdí, že to ona není, a pak řekne vesele:\r\n"JÁ UŽ TAM DOSÁHNU, BUDEŠ TY NŮŽKY, TATÍNKU, MUSET DÁVAT VÝŠ!"'),
(57, '2016-10-13 12:57:52', 'Když už na nás taky zaklepal ten pestrobarevný pán se severním větrem pod starým kloboukem, nezbylo nám nic jiného než se vydat koupit dvojčatům nějaké ta botky pro sychravý čas. Takové ty super vypolstrované dřeváky, které přečkají i pana Rampoucha. Tak jsme zajeli do obchodního střediska, které se vždy stává velkou závodní dráhou pro obě naše holky a marně jim vysvětlujeme, že kolemjdoucí lidé nejsou slalomové branky. Vejdeme do obchodu s obuví a naštěstí je zadržím dříve, nežli proběhnou prostřední stometrovou uličkou až dozadu za 9,59 sekundy, což je o setinu pomalejší než samotný Bolt jen díky špatnému startu, kde ovšem vládnu já a moje chobotniček ruce. S Jájou se zkušeně radíme, jaké boty vybrat. Holky jsou v ráži a všechny nabízené na ukázku okamžitě stahují z pultů do svých náručí. Emča začíná v návalu svého "srdíčkování" všechny vystavené boty líbat a kvílí opakovaně dvě vaty stále za sebou:\r\n"Milujuuuuu všechny boty! Líbí se mi ty botýýýýýý!!\r\nOpravdu po mně nechtějte, abych s nimi jednou chodil nakupovat, až vyrostou.'),
(58, '2016-10-14 12:23:18', 'Tak ono se nám nevěří! Když se dcera napomene, že po pití se nekrká, má 456 výmluv, proč to muselo ven, ale jen nějaký Myšák v televizi napomene pomocníka Ouška, že se to nedělá, tak mají obě najednou oči jak outloň a hned mi hlásí, že je to ošklivé, že se to nedělá, že Myšákovi se to nelíbilo... Myšák Mickey X Rodiče - 1:0'),
(59, '2016-10-14 16:06:53', 'Dnes je plodný den. Prohlížíme knížku, kde jsou písmenka a podle nich jsou namalovány obrázky. K - kůň (to jediné je zajímá), H - policajt (horník), I - indián!\r\n"Tatínkůůů, to je indián! Ten, jak honil pindika!"\r\n"Cože?!" Jakýho pindika?" jsem docela zděšen.\r\n"No toho brouka od Ferdy přece!"\r\n"Aha! Ty myslíš PYTLÍKA!"\r\n"Vždyť to říkám!" gestikuluje Emča.\r\nTo je zase konverzace....'),
(60, '2016-10-17 20:09:01', 'Něco se nedá ani perem vyjádřit tak, jako ústní slovesností přednést. Jako nyní. Emča vyprávěla mamince o tom, jak rychle snědla oběd. \r\n"Já... já jsem ho snědla (číst rychle) RYCHLE, RYCHLE, RYCHLE!" hlásí hrdě a pokračuje: "Zato Amálka ho snědla jenom (číst pomaleji) RYCHLE........RYCHLE........RYCHLE! A teď si to přeříkejte sami bez pokynů. Já jsem se smíchy dusil velkým chutným dýňovým nokem, který jsem právě vložil do úst. P.S. Odteď už není opakem "rychle" POMALU.'),
(61, '2016-10-21 11:00:27', 'Hlídejte si svoje telefony! Já si svůj evidentně neuhlídal. Potřebuji zavolat Jáje. Hledám všude. Překvapivě na zeptání Emča vylézá z pod pohovky (asi se tam ještě ty trpaslice dlouho vejdou) i s telefonem v ruce.\r\n"Tady, tady je!" odzbrojuje mne hned v úvodu, že doličnou věc hned na první dobrou odevzdává. To však ještě netuším, co tam po několika dnech najdu. Obrázek o obrázku (je na FB) si udělejte sami. Mě málem trefilo. Nejen operování u PC, kam jinak nechodí, protože to mají zkrátka zakázáno, ale i malebné zátiší s rumba vajíčkem pod pohovkou je extrémní. Ale nebojte holky, já si všechno (i díky vám) dokumentuji. A že už máte velikou složku!');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(62, '2016-10-23 22:29:33', 'Dnes celý den v autě. Všichni čtyři. Emča, jako oslík ze Šreka, se půl cesty náruživě poptávala na poslední metr našeho cíle, což nám na klidu nepřidalo. Amálka byla kupodivu hodná a celou cestu (i nazpátek) vůbec nespala, což se projevilo při příjezdu nevrlostí, hysterií, následným rychlým povečeřením a ještě rychlejším spánkem. Emča ji následovala. Konec cesty se změnil na koncert dua Mama a Tata (a Americe by nám říkali Mamas&Papas) s repertoárem "Kočka leze dírou, Pec nám spadla, Prší, prší nebo složitější melodií Skákal pes. Proč jsme tuto cestu však podnikli mohu nastínit až nyní. Sečteno podtrženo, dojeli jsme si (zase) do Ostravy pro další FENKU z Moravskoslezského spolku na ochranu zvířat, tentokráte roční švýcarskou ovčandu Fergie. Fenka chudák bázlivá, nedůvěřivá, jelikož byla týraná. U nás se bude mít jako pes v žitě (mase). Jenže to ona neví. Tak nám u první benzínky utekla. Tedy utekla Jáje. \r\n"Než přineseš kafe, tak ji dám vyčůrat..." zněla jediná klidná věta mojí polovičky, když jsem odcházel na nákup. Pak už jen následoval rychlý sled událostí. Ještě v klidu jsem donesl kávu, pak jsem zahlédl Jáju, jak sedí nahoře na poli, brečí a prosí Fergie, která se z kšír vyvlíkla prý jako Copperfield, aby se k ní vrátila. Ta se nehodlá chytit, utíká, kam se jí zamane, moje polovička za ní, já za mojí polovičkou, děti řvou, že chtějí čůrat, já řvu že to byl sakra hloupý nápad, Jáji řev se nese polem až k vzdáleným srnkám, které raději rychle mizí v lese v traumatu, že by je místo Fergie okamžitě někdo narval do auta. \r\nPomohl až telefon k pěstounce po půl hodině nahánění, u které Fergie doteď byla, a ta nám pomohla vyřešit případ. Musel jsem ale díky tomu porušit 140 dopravních předpisů, abych se z benzínky dostal až k poli a otevřel kufr auta, jak nám poradila. Fergie ale auto zcela ignorovala, takže jsem zase nastoupil já a s mírným nadběhem jsem fenku nasměroval zpět k autu. Tam si Jája s ní ještě zahrála na honěnou a tak pomohly i dvojčata, které ji také lanařili dovnitř. Nutno ještě dodat, že naše nahánění nepolapitelné bílé vichřice Fergie najednou sledovalo několik statných kamioňáků, kteří si asi v té chvíli všichni chtěli vykonat svou potřebu za keři na poli. Možná jsem od nich mohl vybrat pár drobných za šou. \r\nFenka i my už jsme doma. Jsem stále samotný chlap v naší domácnosti a těch šest bab, co tu nyní všechny už spí mám na starost. Jdu to tedy ven (i dovnitř) vše překontrolovat.'),
(63, '2016-10-25 17:59:33', 'Joooooo!!! Emča ztratila hlas (z neustálého křičení). Od rána jen šeptá a v domácnosti je konečně slyšet i tikot hodin v obýváku. Je zajímavé, jak tichou máme vlastně Amálku. Nyní se decibelové hodnoty obou holek konečně vyrovnaly.'),
(64, '2016-10-31 15:35:20', 'Byli jsme na lampionovém průvodu. Emča stále lampionu říká ŽAMPION.'),
(65, '2016-10-31 23:02:12', 'Jsem *****, jsem *****, jsem *****!!!! Právě jsem díky jedné z dcer ztratil telefon. Sice mi holky pomáhaly hledat, ale i tak jí je to asi jedno. Ptala se, kde je naše kočka. Tou fakt volat nejde! :('),
(67, '2016-11-02 10:14:59', 'Byli jsme na otočku v Ostravě. Jeďte si v autě samotní nějakých 700 Km a za sebou, v sedačkách, mějte půl cesty doslova Sodomu s Gomorou (solný sloup jsem hrát nechtěl, neměl by pak kdo řídit). Díky opravářům na silnicích si teď všichni cestáři určitě vypravují, že viděli týrané dítě, které má takový hlad, že dost nechutně líže okýnko auta (dneska si ho půjde uklidit TO dítě!) Nehledě o podávání a braní věci zezadu od dvojčat. Nebo neustálé skandování o chtíči stahování zadních okének (bože blahořečen buď za rodičovské zámky i v autech!). Malou útěchou mi je krásných 83 Km hlubokého spánku (ne mého). Dnes se jen bojím otevřít auto, aby se ty odpadky všeho na mne hned nevyhrnuly. Příště, maminko, příště jedu popelářským autem! \r\nP.S. - Ha! Děvčata, ženy, maminy, dámy! I my chlapi dokážeme nemožné v autě a s dětmi! Moje geny se přepisují a naši zmutovaní potomci vám už budou rovni!'),
(68, '2016-11-06 21:29:29', 'Nevím, jak jsem to udělal, ale po páté hodině jsem přijel s holkami domů. Už spaly v autě. A spaly dál. Spí, spí a spí. Jsou v postelích. Přiznejte se někdo, že jste jim dal napít odvar z makovic. Po téměř čtyřech letech první večer bez hluku. Jen já a má milá polovička. Dobře já!'),
(69, '2016-11-06 21:29:53', 'A máme tu seriál. Něco jako Ulice, Ordinace, Cesty domů a Dallas. Tohle totiž na pokračování určitě bude! Cítím se jako Rocky, co vyběhl schody, nebo jako Messi, co rozstřílel Klapzubovu jedenáctku. Pro dámy bych to přirovnal k vytvoření obědu z francouzské kuchařky od michelinského kuchaře, kdy vám ten oběd pochválí maminka manžela, co právě přijela unavená z dlouhé cesty. Dnes nám kamarádka mezi řečí zcela vážně nabídla, že nám přes víkend vyvede dvojčata mimo náš azimut. Jako po 4 letech někdo dobrovolně přijde a nabídne nám zcela dobrovolně ,bez lámání kostí a žhavení lebky zvané budík, záštitu nad našimi čerticemi. Jo! Bude VÍKEND (slovy: dva a půl dne!!!!) VOLNO!!! Přejte mi to :)'),
(70, '2016-11-08 10:54:04', 'Znělka. Seriál pokračuje. Je úterý. Tatínek se těší (i s maminkou) na pátek jak rolba na sníh a dvojčata v domnění nějakého výjimečného stavu neustále vymýšlí skandovací hesla. Včera bylo na programu provolání: "Já chci ŠOKOLÁDU!" (Hm, dík této za její dovoz :)) Dneska cokoli řeknu, sice udělají až na druhé škytnutí, za to s průpovídkou: "Jaaaaasně, ka-pi-tá-ne!" Doufám, že si nehrajeme na Titanic.'),
(71, '2016-11-10 09:03:20', 'Tedy svatý Evžen přijel dřív než Martin, i když toho sněhu je tak nějak na nás všechny málo. Ale holky hned ráno přiběhly dolů už s kulichy a rukavicemi, samozřejmě v pyžamu, že chtějí jít stavět sněhuláky. S rychlostí fotbalisty ve skluzu ve stylu "pocemkamjdeš" odchytávám obě aktérky prvních skoro zimních radovánek a to byste nevěřili, jak rychle se najednou děti dokáží obléct. Píšu si to do kolonky "tak ony to umí pořádně, a ne že ne" a vypouštím ven veškerou zvířenu doteď zevlující doma. Útěchou mi buď, že oželí i ranní pohádku oblíbených Wings a jsou venku. P.S. Příště bych potřeboval tak půl metru sněhu, aby si mohly prohrabávat eskymácké cestičky. P.P.S. Jdu dopsat na papír další tunu teplého oblečení na víkend k tetě. Nebo ne, poradím jí, ať je rovnou vždy celé dá do ždímačky.'),
(72, '2016-11-10 17:40:45', 'Čas je relativní pojem. Za vteřinu se dá třeba přečíst první věta. Za minutu se dá stihnout mnohem více a mnohem zajímavějšího. Za pár minut se dá stihnout přivést třeba tatínka do blázince. Už si nemůžu ani odskočit, ani nemůžu mrknout očima, abych něco nepromeškal. Dnes jsem však právě pro to odskočení poskočil, až jsem vypadl z bačkor. Už dvojčatům nestačí se fintit JAKO maminka, ale ony se chtějí krášlit JAKO maminka. Odnesla to její řasenka. Doma to vypadalo jako na mexickém karnevalu svátku mrtvých. Nebo jako když Tim Burton točí další ze svých ponurých scének. Jestli já nemám svatou trpělivost, no, posuďte sami. Ty černé oči, oči černé...'),
(73, '2016-11-12 12:19:18', 'Seriál "máme z domu děti" je téměř ve své polovině. Od rána je tu ticho. Největší hluk dělal presovač a naše hrající si fenky na zahradě. Je tu naprosté, nevyčerpávající, dlouhé, nerozkrájené, dlouhotrvající, jedinečné ticho. Jsem tu jak Robinsoni. Asi pojedu koupit palmu a budeme se slunit při horském slunci do odpoledne a večer prožijeme famózní nokturno a možná i se sklenkou vína.'),
(74, '2016-11-13 18:30:41', 'Děti nám dorazily domů. Já s Jájou jsme energii ani nestihli načerpat, takže nám jí nikdo nemůže ani nanovo vzít. Dvojčata si svoji energii asi vozí v nějakém pytlíku, který se každou hodinou aktualizuje a dobíjí. Teta se strejdou, ten hrdinný pár, který nasazoval přes víkend to nejcennější, a to život i nervy, dorazil také s mírně větším úbytkem energie a přiznám, že jsem potajmu začal hledat na internetu, kde by se dala objednat hromadná zakázka koupi nových, dlouho nabitých baterií pro dospělé. Asi zavolám distributorovi energií, že mám pro ně perpetuum mobile. Tolik energie z našich holek by pro Čechy, Moravu a Slezsko určitě žádný jiný energetický závod nedodal.'),
(75, '2016-11-14 11:08:28', 'Ráno je jako každé jiné. Vstáváme, sníme si rozmixované ovoce, venčím pejsky, venčím děti. Holky se zaujetím pozorují, že jim od úst vychází pára a hrdě hlásí transformaci na komín, potažmo kamna a od úst jim kouří daleko více. Dobré na tom je to, že do nich nemusíte dát ani polínko. Svoje polínko však chtějí hned po příchodu domů. \r\n"Tatíííí, dáš mi šokokoládůůůů?" \r\nDlužno říci, že jim chutná jenom ta hořká od 75% kakaa a více. \r\n"Jasně, jen jeden čtvereček, " chci být hodný.\r\n"Ne, hodně, hodně, hodněěěě!" \r\nJasně, ještě, že jsem rodič a jako šerif domácnosti tu zákony a míry určuji já. Jsem prozíravý. Čtvereček Emču (a teď si povšimněte krásné českého spojení) dočista ušpiní na rukou i puse. \r\n"To je v pořádku," uklidňuje moje zděšení. Ne, že je špinavá, ale že může kdykoli a kdekoli provést očistu á la Ježíš Kristus a já pak budu mít její obtisk na gauči, utěrce, nebo dece.'),
(76, '2016-11-16 10:47:54', 'Poslední dobou Emča používá nátlak k tomu, aby si vydobyla zrovna to, co by chtěla. Což jí samozřejmě ani já ani Jája nedovolíme a tak volí poslední ze svých triků, o kterých si aspoň trošku myslí, že třeba v tu chvíli zabere. \r\n"... tak ahoj, já ODCHÁZÍM!" otočí se zády, založí ruce a se vztyčenou bradou hrdě provede pár kroků směrem k hlavním dveřím. \r\nMě třeba v tu chvíli začínají cukat koutky a jen tak ledabyle mávnu pravačkou a při tom pronesu:\r\n"Tak pa. A nezapomeň si vzít z věšáku batoh."\r\nEmča se okamžitě otočí a letí nám do náruče. \r\nZa 15 let to určitě (doufám, že ne) opačně. Akorát nám před nosem zabouchne dveře a my budeme moci obejmout jen kliku, protože než vyběhneme ven, zmizí i s tím batohem. TAKŽE raději zatím beru tuhle první variantu. Ta se mi zdá o hodně přijatelnější.'),
(77, '2016-11-20 15:13:27', 'Nejenom jedna persona se mne soukromě ptala, zda napájím holky odvarem z makovic nebo jsou tak umravněny, že se nic zásadního neděje. Děje, ale nejsem přítomen rejdění. Jsme od čtvrtka pracovně v Brně (zdravím Moraváky :D)). Amálka je nemocná, z manželky je superžena s omezenou dobou superschopností (myslím na ni a držím jí pace) a zvířectvo se prý taky drží stranou veškerého dění. P.S. Emča mi každý den volá, že chce vidět ty čerty, co slyšela v telefonu (žádní tu nejsou, jen tribuny bouří :D) Krásný víkend všem.'),
(78, '2016-11-22 12:07:28', 'Za necelé dva týdny je tu Mikuláš a holky už vymýšlí (stejně to dělají celý rok, ale na intenzitě přidávají až nyní) všelijaké zákeřné ústupky, aby se jeho a hlavně čerta zbavily. Ještě, že si ty seznamy nemohou zapsat a při setkání na všechny nástrahy zapomenou. Již jsem zaznamenal chycení za rohy a vyškubání chlupů, kopnutí do nohy (to je já neučím), dají mu pěstí (to je taky neučím), budou ho táhnout za ocas (čerta) ven, plácnou koštětem, aby byl v klidu, zlechtají ho a pak ho vyhodí do popelnice. \r\n"Holky, nedělejte nic nezákonného!" nabádám je a hned tu mají variantu B.\r\n"Tak mu zazpíváme nějakou písničku, aby odešel," jsou fakticky zamyšlené. Mě se ulevilo. I když - hádejte, koho budu asi utěšovat po návštěvě Mikuláše a) čerta b) dvojčata?'),
(79, '2016-11-24 10:01:07', 'Stává se vám někdy, že při psaní čehokoli zkrátka usneeeeeeeeeeelkbjkblkabvlkbnd vxcmnvbnbvyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyyy kbdkajhbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbfslllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllllll................'),
(80, '2016-11-27 19:45:50', 'Emča nám tu skáče jak vibrační deska (pro dámy: jako stará ždímačka, na které jste musela sedět, aby neposkakovala po celé koupelně, ale stejně jste se cítila jak na splašeném býku) a vyjmenovává, co by všechno chtěla pod stromeček od Ježíška. Ano. Není to moc tiché a i to poskakování nepřidává klidu první adventní neděle. Rozhodli jsme se, že tedy všechno tomu miminku, co nechává bačkory a trenky pod stromečkem, napíšeme, aby tak trochu vědělo, jaké obchody má navštívit a kousek národního majetku utratit. Holky nakreslily celou naší početnou rodinu (nechápu, že sebe vybarvily a nás nechali zcela černobílé) a maminka svými nezaměnitelnými hieroglyfy napsala nad každého, co by kdo chtěl. Fotka tedy nic moc. Od té doby, co mi Emča ztratila telefon si musím všechny obrázky uchovávat v hlavě. Ježiškůůůůůůůůů!'),
(81, '2016-11-29 14:44:12', 'Už jen den si mohu říkat otec na rodičovské (s dvojčaty). Rychle to uteklo...'),
(82, '2016-11-29 15:50:57', 'Už jsem fakt ženská v domácnosti. To mne to dostihlo před koncem pěkně tvrdě. Myju okna na Vánoce, peru při tom záclony a chci upéct chleba. Ale - sakra - co jsem nechal v troubě, že tak divně voní? Zkontroluju, stojící zrovna židli a věšící jednu vypranou záclonu, linku, jestli jsem tam třeba nenechal kvásek. Ne. Vůbec nic mne nenapadá. No jasně!! (Upravuju si pak prsa v podprsence), nechal(a) jsem tam napůl vysušit utěrku. Jo, hezky voní....'),
(83, '2016-11-30 17:01:32', '30. 11. 2016\r\nDoufám, že tento text nebude dlouhý jako vyhláška EU o okurkách, i když, když se do toho ponořím, nejdu zastavit. \r\nDnes je poslední den mého působení jako tatínka na rodičovské (dovolené) s dvojčaty. Když se holky narodily, měl jsem strach, že mi je dají obě do náruče. Po pár minutách jsem je jak kukly nesl mamince zpátky na sál ukázat. Začátky byly opravdu krušné a až na menší pomoci jsme na všechno zůstali s Jájou sami. A pak jsem nastoupil na samostatnou stráž já. Doteď celých 1109 dní, kdy jsme mohli sledovat, jak holky rostou, rozvíjí se, začínají se smát, mračit, zlobit, odmlouvat, ale od toho by nebyly děti. Projít si tím musí každý. Veprostřed rodičovské, když jsme se přestěhovali do baráčku, aby měla dvojčata nějaký ten svůj prostor hlavně venku na zahradě, jsem přešel ze psaní do jejich knížek, které jsem vždycky nemohl najít nebo zapomněl napsat novoty, na psaní na FB. Dokonce jsem dlouho o svém "projektu" neřekl ani Jáje, ale protože se eskapády dvojčat stupňovaly, rozšířil jsem anonymitu této stránky a i s její pomocí se o to více rozšířila i do vašeho okolí. Přeci jenom tatínků s jedním dítětem na rodičovské je hodně, ale tatínků s dvojčaty a vícerčaty tolik není. A tak jsem chtěl vlastně i okolí ukázat a dokázat, že to my muži zvládneme a taky jsem chtěl ulehčit trápení maminek, že v tom nejsou samy, že se s tím trápí i jeden chlap, který do této řeky rodičovství vstoupil bez jakékoliv znalosti péče o dítě. A tak příspěvky pomalu gradovaly. Vše co zde doposud bylo napsáno se opravdu událo a nic jsem si nevymyslel ani nedomyslel. Chtěl jsem jen syrově přenést na virtuální papír dění našich dětí. Něco bylo úsměvné, něco možná trapné, něco syrové a něco by se dalo zlatem tesat. Neuvažoval jsem o nutnosti za každou cenu pobavit i za cenu pokleslého, možná i vulgárního humoru, za což se dodatečně některým omlouvám, pokud to ode mne čekali, zkrátka jsem si chtěl zachovat ryzí styl psaní, protože až by to eventuálně jednou četly moje holky, nechtěl jsem, aby se za to styděly. \r\nDnešním dnem mi končí tedy rodičovská. Ale stránky končit nebudou. Jen si k tomu ANEB dopíšu "otec na rodičovské a po rodičovské". S dvojčaty budu dál doma a tak o nějaké příběhy nouze nebude. Přichystal jsem i malé překvapení a to, že jsem po večerech a nocích, kdy po mě holky nelezly, psal. Psal jsem úplné začátky od zjištění, že budeme mít dvojčata, přes celých devět měsíců až... Ale to bych předbíhal. Je to celý příběh s mnoha kapitolami. Mohl by vyjít příští rok. A doufám, že pohled na život otce s dvojčaty by jako humorné čtení mohlo třeba i někoho snad zajímat. \r\nA tak, v tomto dlouhém a úplně nevtipném článku, bych chtěl vám, fanouškům a kamarádům této stránky hluboce poděkovat. Poděkovat za to, že jste si někdy něco přečetli, párkrát okomentovali a sem tam dali i radu. Poděkovat za podporu. A také poděkovat mé drahé milé polovičce Jáje - že mi pomohla při výchovně dvojčat, abych se nevrhnul už v prvních měsících ze čtvrtého patra hlavou dolů, že se se mnou podělila o slasti strasti při holkách a jejich vrtoších, že jsme takoví rodiče, jací jsme, protože být jinačí, asi by to ani naše děti nebavilo :)\r\nTak, dámy a pánové. Jdeme dál!\r\nRadim'),
(84, '2016-12-02 12:38:17', 'Nemám svůj osobní deník, tak to musím napsat sem:\r\nMůj (holek) milý deníčku,\r\nuž jsou to dva dny, co nejsem na rodičovské, ale holky to asi ani nepostřehly. Nemám srdce jim tu novinu říkat. Asi by se jim zhroutil dětský svět. Namísto toho stále okupují ten můj. Všude, kam se podívám, je z mého světa stále více ukrajováno. Už to zašlo tak daleko, že na mne z různých koutů skáčou. Ohnu se pro vytření podlahy, mám je na zádech. Posadím se na pohovku, mám je za krkem. Otevřu ledničku jsou tam jen jejich jogurty. Na schodech jsem šlápl na kostku. Bylo mi řečeno, že mám dávat pozor. Nakonec jsem byl dvojčaty přesvědčen, že jsem kostku napadl a rozšlápl já. Nyní toto píšu v temném stanu při baterce, bojím se i dýchat, aby mne neslyšely. Slyším zvuky. Panebože, NĚCO se blíží..... ÁÁÁÁÁÁÁÁááááááááááá..............'),
(85, '2016-12-04 22:11:19', 'V pondělí nás čeká pestrost osobních emocí dětí při kratičké návštěvě bělovlasého a bělovousého hodného dědy s mitrou na hlavě s chlupatým výrostkem s rohy a pytlem za zády. A tak jsme si to vyzkoušeli s dvojčaty nanečisto na dětském karnevalu s Mikulášem a čertem. Suma sumárum: holky opustila chtivost tance po vstupu do lokálu. Emča mi po celou dobu akorát neustále trhala mikrofon z ruky (já tam byl pracovně ;-)) a Amálka proseděla půlku rejdění Jáje na klíně (takže ani jedné nebyla vůbec zima, jak se k sobě tiskly). Ohledně básničky pro Mikuláše jsem však jako otec učitel byl téměř 100%. Amálka (s pomocí Jáji) vysekla hitovku "Skákal pes," že zítra čekám telefon od nejedné nahrávací společnosti. Jednu chybku to mělo. Celou dobu měla Amálka zavřené oči. Emču, stará muzikantská harcovnice, se postarala o Mikulášovu zábavu evergreenem, který si, neznaje všech slov, upravila po svém:\r\n"Mikuláš ztratil plášť, Mikuláška sukni..... seděli u nás na okně, byli oba SMUTNÍÍÍÍÍÍ!" \r\nPak už jen komandovala děti při židlované, kdy do mikrofonu říkala "sednout" nebo "stoupnout". Mikuláši, v pondělí se těš.'),
(86, '2016-12-04 22:19:53', 'Celebrita jménem Mikuláš u nás dále pokračuje strmě vzhůru. Emča se již od rána rozhodla potěšit naše uši opakováním zážitku setkání s Mikulášem (kdyby tak věděla, že jí to teď v pondělí čeká ještě jednou a pěkně zblízka). \r\n"A Mikuláš, tati, mami, Mikuláš má krááááásný fousy!"\r\nKývneme s Jájou u snídaně, ale to kafe, to jsem asi neměl pít protože Emča pokračuje:\r\n"Mikuláš je príma! Mikuláš nám dal ŠOKOLÁÁÁDUUUU! Mikuláš je hezkej! ZAMILOVALA jsem se do Mikulášeeeee!"\r\nJen stěží polykám kávu a Jája se směje do svého trička. Ale nechám jí v tom. Za pár týdnů už bude milovat mladší nebeskou "VIPku" - Ježíška.'),
(87, '2016-12-05 22:30:04', 'Tak naše Dorotky peklu zase unikly, ale ten seznam hříšků byl na hodně velkém papíře. Amálka zpívala mamince do svetru, takže tlumený zvuk slov Skákal pes simultánně překládala Emča přímo Mikulášovi. Tak zase za rok. Doufejme, že jim ty sliby, co daly Mikulášovi, aspoň dva a půl dne vydrží.'),
(88, '2016-12-05 22:36:15', 'Jééé, tak milá věc se změnila na nemilou :) Tak si tak brouzdám internetem bez surfařského prkna a vlastně se těma vlnama jen tak nechávám houpat, až jsem narazil na informační útes s názvem bloggerroku.cz a jehle - holky, respektive přímo web www.dvojcatanauteku.cz byl na bloggera roku nominován. A já to vůbec nevěděl :D Takže mi děvčata do finále nepostoupila. Ale co, za rok jim jistojistě ukážu, jak peču doma chleba :D :D :D\r\nP.S. To mi to pak musíte někdo říct, že jste to tam přihlásili, ale asi to mělo být překvapení na rok 2022 ;-)'),
(89, '2016-12-07 19:19:42', 'Šmíruji rozhovor mé polovičky s Emčou. \r\n"Emí, nelež na pohovce na té hlavě!"\r\n"Ale je to HEZKÉ!"\r\nOpravdu nevím, co je hezké na tom být neustále netopýr??'),
(90, '2016-12-12 12:42:29', 'Všechno tu jede na plné vánoční obrátky. Dvojčata pilně trénují sledování pohádek na Vánoce a já s Jájou pilně sledujeme usínání u televize. Pomalu, na žádost nejmenších, vyzdobujeme domek zvenčí i zevnitř, aby - jak s oblibou říkáme - k nám trefil Ježíšek, čímž mu asi trochu degradujeme jeho vytříbené smysly, ale proč si tak trochu nehrát na leteckého navigátora a pro jistotu nevydláždit "přistávací dráhu". Tak, určitě bude mít hodně dárků a počasí v ČR zase bude s přízemní mlhou bez sněhu. Tak aby trefil. Trochu nám to stěžuje v současnosti nejmladší člen rodiny, tříměsíční fenka Fergie. Už mi rozkousala druhé světýlka venku. Divím se, že nesvětélkuje ona. Mohla by, protože je černá a v noci o ní klopýtám. Amálka se stále ptá, kdy už napadne sníh, protože pak podle ní budou Vánoce, takže je to dobrý, my Štědrý den budeme mít až 20. ledna, kdy konečně napadne aspoň 6 cm sněhu. U Emči se projevují sklony k pyromanii. Neustále se dožaduje zapalování (a sfoukávání) svíček na adventním věnci. Už chápu text ve vánoční písničce Veselé vánoce: "...a pak táta s minimaxem zavlažoval byt."'),
(91, '2016-12-12 12:42:44', 'Je to zajímavý úkaz, to narození dětí. Člověk je s manželkou na sále při porodu a najednou vám děti skáčou po hlavě a zádech a dožadují se nepřetržitého zájmu. Dnes (a teď) už jsou tomu přesně 4 roky (12.12.2012 ve 12:04 a 12:05 :D)! Tak holky, všechno nejlepší a žádné (jen malinké) zlobení! Táta a mamka'),
(92, '2016-12-13 11:21:26', 'Procházíme městem, o kterém paní Němcová psala jako o kávové společnosti a pan Hrabal má na zdejším pivovaru pamětní desku ve výši psího čůrání. Je po dešti, sem tam na spravovaných chodnících zeje místo prohlubní pár malých kaluží. Holky nenapadne nic jiného, než začít skákat. Nejprve jen přes kulaté kanály.\r\n"Hele, hele, tati, podívej, už to UMÍM!" a Amálka snožmo bravurně skáče přes kanál. Emča se nenechá zahanbit a tak už tu mám dvě nekontrolovatelné gazely. Zrovna volám Jáje a tak jen vizuálně kontroluji jejich snažení. Proti nám jdou dva mladí lidé, ona a on. Život je někdy pěkná zákeřná mrška míchající v hrnci osudu jak se jí jen zlíbí. Emča, doteď skákající krásně přes vše, co se jí připlete do cesty, přichází k další kaluži. Chystá se pilně na další skok přes kalnou vodu, dokonce jí je vidět špička jazyku, jak se snaživě soustředí. \r\n"Ááááááááá... HOP!" přistává s vervou přesně doprostřed kaluže zrovna, když KOLEM PROCHÁZÍ ONEN PÁR. Voda stříká kolem, já třeštím oči a rychle ukončuji hovor.\r\n"Ježíš, promiňte..." vyhrknu. Pak mi dojde, někde jsem to už viděl, ale - neřešily toto někdy někde nějaké maminky? Ha! Mužská emancipace právě začíná!'),
(93, '2016-12-14 00:10:46', 'COŽE??? Člověk tady uklízí, maká, nerozptyluje se a ty dvě jak by řekla Růžičková v Slunce, seno.. "hajzle jeden" mi za pár minut, kdy si odložím telefon na stůl, dokáží zablokovat přístup do telefonu na 26 MINUT???!!!! Nebudu mít dvojčata, budou z nich čtyřčata s poloviční výškou!!!!'),
(94, '2016-12-15 09:46:35', 'Olalaaaaa, doznívají následky narozeninových dárků. Při koupání vezmu brusku a zkusím to z nich sedřít. Emča vypadá jak náznak Jokera.'),
(95, '2016-12-15 20:07:34', 'Jedeme autem. Holky vezu na dílničku, kde si vytvářejí různá udělátka pod dozorem povolané tvořivé dámy. Ale o tom až zítra, co Amálka vytvořila. Nyní se zaobírejme cestou. Jedu jinudy. U nás je to divně nesmyslně polozavřené a tvoří se kolony. A tak můžeme sledovat elektrický vlak, jak uhání naší cestou.\r\n"Holky, dívejte, vlak!" raději je upozorňuji na významnou chvíli.\r\n"Jé, mašinka!" začíná zářit Amálka a začíná si pobrukovat známou lokomotivní melodii.\r\n"... jede, jede do dáli, veze samý žirafy..." \r\nZde upozorňuji na rodičovský fakt, že vztah k alkoholu u nás netrpíme, což mi za vteřinu emotivně strhává Emča:\r\n"Ale jak se tam ty žirafy vejdou??"'),
(96, '2016-12-16 12:22:23', 'Chápu, že vaše děti jsou abnormálně inteligentní a potají v temné komůrce kopírují van Gogha, ale já se zkrátka neudržím a zveřejním slibovaný počin. Amálka sama od sebe, samozřejmě z nedávné šokové terapie Mikulášem, nakreslila tento skvost. Už mi volali i z Louvre, že by měli zájem o novodobou senzační a originální malbu nějakého svatého. Nazval jsem to "MIKULÁŠŮV GANG." (foto na FB stránkách)P.S. Jája se dme pýchou a štěstím, že konečně někdo po ní zdědil malířské nadání :)'),
(97, '2016-12-19 12:29:52', 'Tak jsem si tak říkal, že jak jsou dvojčata upovídané a mají rády mikrofon, že by naši trojku mohlo vzít na ráno nebo odpoledne nějaké regionální rádio. Tož taková malá dvojitá konkurence třeba Mareše :D Nebo mohu poskytnout základní znalosti odchovu dvojčat v nějaké rubrice ženského časopisu aneb jak to vidí mužský vetřelec :D Tak pokud tu někdo takový pracuje v periodiku nebo alespoň ředitelem rádia, jsme vám k dispozici :)'),
(98, '2016-12-20 10:30:11', 'Ano, i my jsme se pustili do pečení cukroví. Domek už nám svítí jak Las Vegas a pár zatoulaných jedinců už si chtělo u hlavních dveří měnit peníze za žetony, ale v čas jsme je zastavili (dolary vyměněny za knoflíky a posléze vyvěšena cedulka ZAVŘENO). A i přesto, že Jája napekla nakonec několik druhů cukroví, smetanu slízáváme my, protože se u toho zběsile fotíme jak Paris Hilton. P.S. Všechno to do Vánoc sníme.'),
(99, '2016-12-21 10:40:13', 'Ha! Dnešní den by měl být pro mě také velkým dnem a až budu dost starý a dvojčata trochu povyrostou, začneme to - třeba - slavit společně. Ano, není narozeninovým oslavám v naší rodině konec, respektive uzavírám je přímo já, tři dny před Vánoci. Dnes jsem se narodil. Na první zimní den, na slunovrat, na poslední den ve střelci. A mám jen jedno stránkové narozeninové přání (hihi). Pokud se vám stránky líbí a ještě jste jim nedali "tohle se mi líbí" (na Facebooku), není nic snazšího (tak šup na to :D). A klidně je rozešlete i dalším známým (hlavně taťkům), ať vidí, že se o tlupu dokáže postarat i táta.'),
(100, '2016-12-22 10:51:42', 'Když nemám doma Jáju, adaptovaly se na moji vlnu hned dvojčata. Pocítil jsem to na vlastní kůži už po ránu, kdy si ještě myslím, že holky spí, ale přitom už dávno je nepřítel spánku těsně před branami. O tom, že mám tvrdé spaní hlavně v ranních hodinách, jsem se již mnohokrát přesvědčil. Takže jsem si nevšiml, že se Emča vydala na obchůzku spícího domu. Zakotvila u nás v ložnici. Vleze si k nám do postele a hraje si. Do této chvíle o jejím působení ve výsostných rodičovských vodách nemám ani tucha. JENŽE!! Někdo do mě šťouchá!!!!\r\n"Tatínku! NEKRÁPEJ!!!!!" je rozhodnuta mne vzbudit, že jí ruším svým hlasitým chrápáním. \r\n"Když krápeš, tak nás budíš! I maminku!"\r\nTo nechceš. Takže tatínkové: rušíte maminky. A děti. A vůbec celou zemskou květenu a zvířenu.'),
(101, '2017-01-02 11:54:38', 'DOPLNĚNÍ PŘÍSPĚVKŮ PO DOBU NEMOCI CELÉ RODINY:'),
(102, '2017-01-02 11:55:07', 'Ano, i k nám zavítal Ježíšek se stromečkem. Sice to vzal spodním větrem přes Budějovice, ale dorazil, vyzdobil a tím rodiče zachránil před ranním zklamáním, že stromeček ještě nestojí. Nu, což. Asi až moc za rychlost Jájou pochválen nebudu, ale, ženo moje, celou dobu jsem na ty naše holky myslel, jak se jim to ráno bude líbit :) TAK ŠŤASTNÉ A VESELÉ!'),
(103, '2017-01-02 11:55:37', 'Shrnutí Štědrého dne je asi následující: děti jí pomaleji než rodiče, Ježíšek musí čekat (pardon všem, kteří díky nám měli taky opožděné dárky :)). Emča u stolu tančí za rytmu koled. Dokonce diriguje vidličkou.\r\nNa každý dárek Emča prohlásí: "HUSTÝ!"\r\nDvojčata rozbalují i dárky, které nejsou jejich. \r\nTatínek pro kopec dárků zapomněl dárky maminky za postelí a diví se, že maminka nerozbaluje. Ale jinak se tu měli všichni šťastně a vesele. Doufám, že u vás byla také dobrá nálada. Všem jsem ji přál'),
(104, '2017-01-02 11:55:54', 'Někdo se dívá na pohádky, někdo lyžuje, jiní stihli už padesát návštěv. Nám ty svátky, jako i jiným několika vyvoleným, začaly nemocí. Emča nám právě chrupe v posteli a ani nemusíme topit, protože je tu teplota vyšší jak 38,5°C'),
(105, '2017-01-02 11:56:13', 'Ne, bohužel neslavíme, nenavštěvujeme, nelyžujeme. Jak někteří ví, Emča nám hned po pár dnech od Štědrého dne ulehla, jenže se ten nezmar rozmohl téměř na celou naší rodinu. Nejprve na mne (a fakt, že jsem měl z těch horeček docela dobrý "halušky" a ani jsem nepotřeboval čaj z Alberta) a nyní to potkalo Jáju. Další díl o zombíkách se točí u nás. Je to křest ohněm. Protože poprvé s povzdechem musíme říct, že by to potřebovalo nějakou babičku...'),
(106, '2017-01-02 11:56:43', 'Asi bych měl zbilancovat i zde celý rok. Chystal jsem se k tomu, to mi věřte. Mělo to být dokonce i vtipné (aspoň jsem si to tak představoval), ale když zkrátka člověk potí bacily v posteli, nejde to a nejde. Doufám, že mne za to neukamenujete, nebo mi někdo nepodpálí stránky zbloudilou petardou. Nezbývá, než těch pár hodin do konce tohoto roku všem moc poděkovat. Že jste přišli, početli, něco okomentovali, dali zpětnou vazbu a nebo jen fandili. Vážím si toho! Přeji tedy všem ten nejhezčí závěr roku, do nového roku 2017 všeho dobrého a zůstaňte věrni mým čerticím, ony vám věrny zůstanou :) Dvojčata na útěku a zkrátka jejich celá rodina'),
(107, '2017-01-02 11:56:59', 'Perlička hned prvního ráno. Jája vstává s úmyslem uvařit něco dobrého pro naše krky. A pak už jen pronese:\r\n"Emí, dneska udělám polívčičku. Dobrou."\r\nEmča vypoulí kukadla:\r\n"Čokoládovou?"'),
(108, '2017-01-02 11:57:14', 'TAK A POKRAČUJEME ROKEM 2017 :)'),
(109, '2017-01-05 13:17:31', 'Když máte z rodiny soukromý lazaret a ke všemu musíte obě děti udržet od sebe, aby jednu, nemocně dosluhující ta druhá, bacilově počáteční nenakazila. Amálka je dole, v obýváku, Emča má království nahoře. Už vím, že krokově po schodech nahoru a dolů vystoupám denně stejně jako na jakoukoli horu českého středohoří a klidně bych zdolal i Milešovku, která má 800 m nad mořem. Takže až v létě půjdeme na nějaký ten výšlap, budu mít krásně potrénováno. \r\nA pokud kurýrujete více jak jedno dítě tak vězte:\r\n1) Pakliže je neupoutá pod peřinu teplota vyšší jak 38°C, nedokáže to ani teplota v pokoji ani váš starostlivý hlas. \r\n2) Podávání léků je stejně tak těžké jako nakrmit veverku buřtem. \r\n3) Když nenajdete dítě v posteli, nezoufejte, nesublimovalo. Asi bude v psím pelechu nebo schované pod hromadou hraček. Zde je dobré, že dříve nebo později dítě najdete, protože ho prozradí velký kašel. \r\n4) Hlavně nepodléhejte panice, vlasy si umyjete až po kontrolní návštěvě dětského lékaře (pro dámy) - Hlavně nepodléhejte panice - ke svému protějšku se vrátíte až po kontrolní návštěvě dětského lékaře. Někdy i déle (pro pány).'),
(110, '2017-01-09 12:37:22', 'S dvojčaty každý den hraji POKER. Ano, je to takový denní hazard s nimi vycházet. Respektive hrajeme jeho nejzábavnější část a to takzvanou POKER FACE. Každé ráno si všichni, kdo zůstávají v domě, hází all-in. Pak přichází kýžený okamžik, kdo dříve položí karty. Zkrátka na mne nesmí být vidět, že mě to hrozně štve, co právě dělají, protože si mě pak podají horem i dolem a mě to stejně nebude nic platné. Nevím, kde se učily hrát poker. Určitě už v břichu mamky. Někdy vás oberou denně, někdy "až" za dva dny.'),
(111, '2017-01-11 11:04:51', 'Nikdy nebuďte zavřeni v baráku s opačným pohlavím více jak tři dny 24 hodin v kuse. A je jedno, zda to je dospělý jedinec nebo ještě dětský zámotek. \r\nDvojčata (tedy já to už nemůžu vydržet). Jejich agresivita stoupá každou minutou. Nesmím se k nim otočit zády - natož předkem. Tu nemoc nám byl čert s Mikulášem dlužen. Ale zítra už je konečně vyvezu za hranice města, zamávám jim a užiju si tu hodinu bez všech proseb, rozkazů, příkazů, neřízení, obsluhování, rozčilování, hubování a rvaček. Už zase slyším z dálky za sedmery dveře:\r\n"Tatííííííííííííí....!"'),
(112, '2017-01-13 10:14:29', 'Postřeh číslo 896: Nedávejte holčičkám (a to je jedno zda jen jedné nebo vícero v rodině) k Vánocům nebo k narozeninám či svátku autíčka na dálkové ovládání. Tedy pokud nejste milionáři a nedáváte plnohodnotná auta na silnici, za což vás asi protějšek přeci jen bude milovat o píď více několik měsíců (no, možná týdnů). Ale auto na dálkové ovládání je jiná liga. Liga na ničení vlasů. Ano, čtete dobře. Není totiž dne, kdy by jedno z dvojčat nepřišlo s tím, že se jim vlasy zamotaly do zadního kola. Tajně jsem je pozoroval, zda to nedělají natruc právě tomu, že nedostaly to pravé auto do garáže, ale dětská nevinnost je bezmezná a bezelstná. Zkrátka auto otočí, aby se podívaly, jak se točí kola, když tu jim sklouzne nekontrolovatelný pramínek vlasů který se zamotá do kola. V tu chvíli nastupuji na scénu já, jakožto hrdinný zachránce oněch zamotaných vlasů. No, nebude to trvat dlouho a zahrajeme si doma na Postřižiny.'),
(113, '2017-01-16 11:13:55', 'Už jsem si zvykl, že v nákupním středisku vypadáme jako malá rodina Homolkovic. Tedy soustředěný chumel, který se pohybuje konstantní rychlostí. A protože je drtivá část rodiny ženského rodu, mohu s klidem konstatovat, že "Tour de obchody" se rovná (díky nápovědě chytrého telefonu, který počítá kroky) destinaci delší než tři kilometry! I tentokrát jsme se rozhodli navštívit více jak desítku krásných obchodů, které pro mne ztrácí smysl už ve vchodu, kdy jen dohledem oka pokrčíte rameny s větou, že emancipace se dostala i spotřebního odvětví, neboť na osm obchodů najdete jen jeden a půl pánského zboží. A tak v každém obchodu dvojčata zrazuji z odnesení si požadovaného vystřelovacího deštníku. Aby toho nebylo málo, u jedné kasy holky stojí vedle fronty s Jájou a celá fronta si může krátit čas čekání vystoupením Amálky i Emči, které se právě hlasitě rozhodly obšťastnit sluchové ústrojí celého obchodu, ale bylo to určitě tím, že zrovna nehrála žádná písnička z reproduktorů, jak tomu vždy bývá. A tak hit střídá evergreen se zbytky nostalgie a vzpomínek na Vánoce a tím pádem zní Skákal pes, Rolničky, Mikuláš ztratil plášť, Houpy, houpy a všemocná Jede, jede mašinka. Naštěstí už platím a tak se nedostane na skandování dvojčat, protože mají ještě v záloze (nevím proč) "Tatínku, rychle!" Přiznám se, že nejraději asi budu vždy nakupovat jenom rohlíky.'),
(114, '2017-01-16 22:21:58', 'Emča, jakmile vstane, začne hlásit. Na cokoli a kdykoli. O to je to pak strašidelnější. Amálka se trochu drží zpátky, ale její popovídání s kýmkoli vždy začíná: "Něco ti řeknu!" \r\nAle zpět k Emče. Naženu je do koupelny, kde si hoví ve vaně Jája (jo, máme jednu koupelnu a zkrátka holky potřebujeme dát spát, protože vy, dámy, ve vaně trávíte podle britských vědců průměrně týdně více jak 9 a půl hodiny!) a holky si čistí zuby. I ten kartáček Emču nezastaví a stále něco mele. Když tu se otočí na ženu, vyndá kartáček z pusy a dětským údivem glosuje:\r\n"Týýý joooo, ty máš ale hezký prsa!" očima stále Jáju pozoruje a pokračuje: "To sis je vyrobila nebo ti takhle narostly?" \r\nJá v tom okamžení polykám celý kartáček a raději si do pusy strkám i celý ručník, jinak bych se smíchy udusil. Jája je v pohodě. Zrovna si sprchovala vlasy, tak pro vodu v uších nic neslyšela.'),
(115, '2017-01-19 12:27:00', 'Protože se tu včera a v noci zvracelo (jedna z dcer, nebudu jí bonzovat, chápu, je to nepříjemné, když někdo ve čtyřech letech nepřijde z flámu v půlnoci, ale mírně podroušená až k ránu se slovy: "No co, rodičové, někdy začít musím..."), dělám dnes (poprvé) nějaké to dietní jídlo - tedy cibulku, do toho mrkev, dusím to (to je slovo - dusit jídlo :D) a suché brambory. Co z toho vzejde? Shoří mi to jídlo? Hodím mi to dcera na hlavu? Vysměje se mi Jája?'),
(116, '2017-01-20 21:14:46', 'To je tak, když si člověk myslí, že už je všechno v klidu, ohlídnete se a najednou je ten klid pryč, a to k tomu stačí jen pár hodin v horším případě i vteřin. Dopoledne nejmladší člen rodiny fenka hovawarta Fergie utrpěla na sněhu zranění nohy a díky zkušenostem naší sousedky jsem byl trochu v klidu, že to není zlomené. V létě dáte dvojčatům trenky a tričko, pohrozíte jim, že dostanou úpal, když si nevezmou slušivý klobouček na hlavu, na nohy sandále a jede se. Jenže v zimě to trvá stejně tak dlouho, jako když stavíte trojpatrové iglú a ještě vám k tomu pomáhá pomatená banda tučňáků. Taková je naše výprava kamkoli. \r\nPřeskočím pár desítek minut a už se vracíme s obvázanou fenkou domů, když tu se ozve dcera (zase nejmenuji, pochopíte proč).\r\n"TATI, MĚ(šum) CHCE(šum) (šum, šum, šum)CET."\r\n"Co chceš, klacek?" zkouším vydedukovat v klidu požadavek a šlapu dál na pedál a krmím auto, abychom už byli doma. \r\n"NE!! MĚ - SE - CHCE - ZVRACET!"\r\nNeodpovídám, vlastně odpovídám, aby to ještě chvilku vydržela, řežu to přes všechny tři pruhy do krajního a modlím se, abychom už byli na benzínce, o které vím, že tam vždycky stojí. Ale co kdyby tam najednou nebyla?!! Dcera začíná huhlat:\r\n"Huž tho nevydrzhím!" \r\n"Vydrž!" prolítnu benzínkou, jako bych jí chtěl zapálit a dokonce mi ostudně škytne auto, jak vypálím z místa řidiče do místa za mnou, vytahuji jedním chmatem dceru ven, načež spoušť kolem na sebe nenechá dlouho čekat. \r\nV této chvíli se vypípívám (dcera to naštěstí neslyšela, ta druhá si nezúčastněně prohlížela mírumilovně Mateřídoušku v autě).\r\nNásledně už jen volám Jáju, která jela chvilku za námi, aby si aspoň odebrala fenku lazara, abych já mohl nějak normálně dojet domů. TOHLE je ten pravý pátek 13.!'),
(117, '2017-01-24 10:21:24', 'Kroutil jsem jednou hlavou, když v jednom komediálním filmu jedno dítě údajně nechtělo sundat svůj kostým fiktivního hrdiny po celý týden. Beru zpět. Stát se to může. Holky už pátý den nosí princeznovské šaty a nechtějí se jich jen tak vzdát. Naštěstí se aspoň večer převléknou do pyžama. Ještě, že tu nemáme doma třeba kostým draka.'),
(118, '2017-01-25 10:15:07', 'Ráno dvojčata vstávají a plody ovoce začínají dozrávat, neboť vzorově přejí dobré ráno. A Emča mi začíná vyprávět.\r\n"Tati, zdál se nám sen. Přišel Ježíšek a přines nám dárek. Dárek přímo do postýlky."\r\nA Amálka pokračuje.\r\n"Ano! A ten dárek byl terč! Ale byla hračka. Nebyl to živý terč!"\r\nTrvalo mi dlouho, než jsem pochopil význam slova "živý terč"...'),
(121, '2017-01-26 13:09:12', 'Zažívací potíže jedné z dvojčat stále pokračují a my už jsme z toho mírně řečeno na prášky (takže pokud by někdo věděl o dobrém a diskrétním dealerovi z ulice nebo renomovaném psychologovi z ordinace, dejte vědět). A tak jsme museli - zase - upravit i rozpis spáčů. Tím zase jedno dvojče (s potížemi) spalo u Jáji, já spal místo dvojčete s potížemi u druhého dvojčete (stále mají postýlky v jedné místnosti, naštěstí ty "postýlky" jsou normální velikosti). Už jsem z toho tak zblblý, že, když večer jdu ještě kmit naší zvěřenu, jídlo místo do mikrovlnky dávám do lednice a marně hledám tlačítko start. Posléze ulehám do dětské postele, která nějak podezřele pode mnou vrže. A nemůžu usnout. Jak by taky ne, když u nohou mám jednu miliardu hraček - od velkého medvěda až po velkou kosatku - takže se mi do postele nějak nemůžou vejít nohy. To jsem pak vyřešil. Jenže se pohnu a jsem napaden letkou dalších plyšáků, kteří doteď strážili sny přichyceni za větším čele postele. To jsem tedy nevěděl, že v dětském pokojíku mimo kostek na zemi může být tolik nebezpečných nástrah. P.S. Potřebuju namasírovat záda.'),
(122, '2017-01-30 11:47:35', 'Stále mi (nám) berou telefony. Tentokrát level 2. Už nevystřihnou 109 fotek z okolí, ale rovnou jsou ochotni zvětšit sebe. Tato fotka jakoby vyjadřovala jediné: "Hele, Amálko, dáme selfí i s mořskou pannou..."'),
(123, '2017-01-31 14:58:55', 'Ježíš, já se mám. V domě mi řvou dvojčata, venku na zahradě zase naše fenka. Když za mnou vlezou dole dvojčata na onu místnost, tak nahoře do oné místnosti mě chce zase doprovodit naše kočka. O manželskou postel se Jája dělí se mnou a našimi dvojčaty. Když vezmu do ruky jídlo, okamžitě se holky dožadují nějakého podobného sousta. Taktéž prudí i naše zvířectvo. Když však začnu uklízet, nikdo se v mé blízkosti jednoho a půl metru nezjevuje (kromě Jáji). Ježíš, já se mám.'),
(124, '2017-02-01 22:55:00', 'Beru fenku, beru holky a navlékám je téměř do skafandrů, protože tak opravdu vypadají. Ne, skafandr to není, vypadá to jako obleček na sumo a téměř i tak se v tom zimním oblečení pohybují. Než vyjdeme, beru do kapsy ještě náhradní rukavice, což se jeví po pár minutách jako dobrý nápad, protože "ten sníh je FAKT mokrý!" Když všechna tři zvířata vypustím na poli, aby se proběhla, zvažuji, zda jim neudělat bílé střapaté oblečky á la "hejkal" (jak to mají odstřelovači), protože by to na tom poli vypadalo pak jako běžící stádo Yettiů. A na otázku:\r\n"Tati, můžu spadnout?"\r\n(Tak jasně, na rozbláceném poli by to nebylo košer, ale teď, ať se klidně i do sněhu zavrtá)\r\n"Jo!" a Emča je dole. Amálka se nenechá zahanbit a vrhá se okamžitě do hlubin závějí hlavou napřed. Pak už jen sleduji polo synchronní výrobu andělíčků, než mi fenka podrazila nohy. Joooo, zima. Užívejte si na horách. Mě stačí i nížina.'),
(125, '2017-02-02 12:21:16', 'Zasedl jsem k zahraničnímu tisku. Za chvíli už budu normální chlap, co se stará o dvojčata. Asi nabídnu Jáje, zda bychom nedali ještě aspoň trojčata :D Jako kámoš Clooney (to je ten, co pije moc kávy jako já - třeba to máme po tom) čeká se svou partnerkou dvojčata a teď se k tomu přidala ještě Beyonce? Ne, dvojčata nejsou módní doplněk, asi si ještě nepřečetli mou stránku :D Takže Clooneyho už neuvidíte do roku 2020 v žádném filmu a holka Beyonce si vykřičí hlasivky tak, že nebude moci zpívat. Počkejte, vlastně oni budou mít chůvy. Aha, zase jsem někde něco zaspal....'),
(126, '2017-02-05 23:39:44', 'Dvě slova, která mne poslední dobou od Emči baví: \r\n"KAPSÁREK" a "LUSKOVAT". Význam je zcela jednoduchý. Uhádnete ho i vy?'),
(127, '2017-02-07 09:27:50', 'Takový ten všední den. Ráno vstanete, hned o vás zakopne první dítě, načež se z druhého pokoje ozve dítě druhé, protože se začíná taky probouzet. Je to stejné, jako když se probouzí dvouhlavá saň (která má ale virtuálně aspoň osm hlav). Takže pokračuji ve vstávacím rituálu, kdy dvojčata naženu na ranní očistnou hygienu, převlíkání, ustlání si postelí a já jdu dolů dělat snídani. Všechno tak nějak klape (už jste někdy slyšeli že by s dětmi něco každý den klapalo? Když napíšu TAK NĚJAK, znamená to, že moje hlasivky si už roztahuji od rána, protože začínám s holou větou, aby si pospíšily, a končím rozvinutou větou o hlučnosti 90 decibelů, co že mimochodem příznačné pro jedoucí vlak, kterým se s velkým funěním stávám, protože musím 6x vyběhnout schody, abych dvojčata usměrnil). Už dávám snídani na stůl, když uslyším družná rozhovor, ve kterém má Amálka prim:\r\n".... Emčo, já nemám podprsenku...!" \r\nAmálka je hrozná fintilka. Ale že by ve čtyřech letech potřebovala podprsenku se mi jeví jako zcela nemožné a už nyní se zříkávám jakýchkoli nákupů s našimi dcerami v pubertálním věku. P.S. Peněženky se taky nevzdám!'),
(128, '2017-02-08 12:48:04', 'Moji ženu vždy napadne něco geniálního. Třeba jako tuto neděli. Vzdělávací systém starých krásných pohádek a filmů pro děti začíná výborně fungovat a tak následovala nevinná otázka:\r\n"Holky, nechcete pustit krásný film o strašidlech? Je tam hodně dětí a milý rytíř - duch?" zeptala se Jája zcela bezelstně, když dvojčata po nás lezla, při tom řvala a tahala se o to, která se uhnízdí hned mezi námi. Tento návrh přišel právě včas, nebo spíš nějak mezi tím, kdy už si Amálka brala na Emču nunčaky a Emča odjišťovala několik oslepujících granátů, protože se stále nemohly dohodnout, která zrovna bude hladit ruku mamince. \r\n"Ano! Chceme!" zakopává válečnou sekyru Amálka a usazuje se na svém místě na gauči.\r\n"Jooooo!" odvolává štábní Maršálky a dělostřelectvo Emča a usazuje se také. \r\nV tuto chvíli nastupuji na scénu já, hledaje v dvoumetrovém sloupu jediné DVD, které nese název AŤ ŽIJÍ DUCHOVÉ!\r\nPrvní seznámení s tímto skvostným materiálem Amálka spíše nezhlédla na rameni Jáji. Ano, mohl bych ten film označit mírněji na dětský horor. Já, při dospěláckých hororech tam, kde se Jája směje, skáču ženě do náruče (zakrývám to momentální vášní). A to samé dělala Amálka (bez momentální vášně). Prokoušeme se na závěr filmu. Velkolepé finále a následná věta nás znovu vrhá na začátek.\r\n"My chceme vidět Ať žijí duchové!"\r\nFakt jsme měkcí a hodní. Film jde znovu, tentokrát už holky koukají samy a hltají každé slovo. \r\nJe středa. Už jsem to s dvojčaty viděl po osmé. Večer nám zpívají dunky žalky (nevím proč, u nás jsou šťastné) a při filmu už opakují písničky i nejznámější hlášky. P.S. Taky chtějí trpaslíky.'),
(129, '2017-02-09 12:27:47', 'Dvojčata dostala pro svoje maličké sponky, gumičky a budoucí prstýnky, řetízky a šminky takovou krásnou menší toaletku se zrcátkem a šuplíkem. Co si však Emča strčila hned do šuplíku rozesmálo i takového mrzouta, jako jsem já. Že by byla v budoucnu podvodný karetní hráč?'),
(130, '2017-02-10 11:15:42', 'Jáje mi vždycky říkala, že neumím fotit. Ono se špatně zaostřuje na něco, co je neustále v pohybu (Emča). Na to je lepší statická figura (Amálka). A tak, jako správný tatínek umělec, když jde dcerám umýt jejich dlouhé vlasy (fakticky rostou s nimi od narození), vzpomenu si na komedie s kadeřníky, zapnu fén a zahraji si na nejlepšího kadeřníka v okruhu 5 metrů. Resumé - mohu dělat jak kadeřníka tak fotografa, nebo ne?');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(131, '2017-02-11 12:57:43', 'Holky sedí nad talířem snídaně a my s Jájou uvádíme celý dům do pořádku po tornádu dvojčat i současné domácí zvířeny (pokud jsem doteď nadával na dívčí vypadané vlasy všude, všude a všude, kočičí a štěněcí chlupy, to je brutální mor). Jak to tak bývá, naše dcery se ošívají, pošťuchují a dělají úplně zcela něco jiného, než kousání do rajčete.\r\n"No to mě podrž!!" najednou se ozve Emča.\r\n"Co se děje?" zvedám hlavu. Jája ukončuje činnost také a přichází se přesvědčit, že se spíš nic neděje.\r\nEmča pokračuje dívaje se z onka za ní:\r\n"Venku je LÉTO!!"\r\nPodíváme se s Jájou z okna na zamrzlou zahradu, kde i nejotužilejší rostlinka schovává svůj stonek pod haldou hlíny. Představivost dětí bych chtěl někdy mít.'),
(132, '2017-02-13 10:26:30', 'Trochu málo osvěty také neuškodí. Tedy aspoň pro ty, co plánují, čekají nebo již mají dvojčata a vícerčata. Dnes jsem narazil na článek na novinkách: https://www.novinky.cz/…/428277-celebrity-ktere-maji-dvojca… \r\nDoupřesnil bych to - my všichni, co máme děti, ale hlavně i my, co máme dvojčata a vícerčata jsme CELEBRITY. Jen malý detail nás dělí od těch dam na obrázcích. My jsme s dětmi opravdu téměř 24 hodin v kuse. Nemáme (v 99%) chůvy a další lepší vymoženosti v pomoci s takovou nadílkou. A současným i budoucím tatínkům bych chtěl vzkázat, že pokud je to ve vašich silách (žena finančně lepší, nebo máte svobodné povolání), pokud chcete vidět své ratolesti růst a rozvíjet se, neváhejte a buďte s nimi doma na rodičovské, nebo dál s nimi doma, než půjdou do školy. I když je to někdy na nerva (ale to jsou všichni rodiče), je to prima mít dvojčata a všude to budu s radostí propagovat a dávat za vzor. RODIČOVÉ VŠECH ZEMÍ, SPOJTE SE!'),
(133, '2017-02-16 14:49:56', 'Když slyším z pokojíku nahoře Emču volající ségru:\r\n"Amálkoooo, neboj seee, ukaž seee, já ti NEUBLÍŽÍÍÍÍM..."\r\npřeběhne mráz i po mých zádech.'),
(134, '2017-02-17 11:43:45', 'Právě jsme na rychlostní návštěvě u Jáji v práci. Je tam dalších hodně tet. Na jednu se Emča stále věší na jednu z nich a teta říká:\r\n"Jó, teď se věšíš a až přijdeš příště, už mě nebudeš znát..." \r\nEmča se na tetu podívá, usměje se a prohlásí:\r\n"Ale budu..." zamyslí se a pokračuje. "A jak se jmenuješ?"\r\nTma, teta je zcela odzbrojená.'),
(136, '2017-02-20 11:43:54', 'Několik málo rad pro budoucí rodiče (hlavně pro muže, protože ty to ještě geneticky zakódované nemají a proto musí tvrdě trénovat) dvojčátek a mnohočátek (část I.):\r\n1. Je jedno, zda máte do porodu měsíc nebo jste to právě zjistili, ale od této chvíle se snažte co nejvíce naspat. Spěte. Spěte doma, u jídla, v práci, v tramvaji, na záchodě, všude. Nedoporučuji spát ve vodě a v autě na místě řidiče! \r\n2. Že jako budoucí rodič se bojíte dvojitého přebalování, protože tolik biologických zbraní nevlastnil ani obávaný Saddám je absolutní mýtus. Budete mít spíš starosti sami se sebou a proto se vám vyřadí nějaký ten smysl. Třeba smyl pro humor. Pokud se i přesto bojíte nové značky parfému, je tu vhodná příležitost pro potápěče a hasiče si potrénovat v maskách.\r\n3. Čím víc dětí, tím víc decibelů. A je jedno, zda jim je měsíc nebo deset let. Spíš se postupem času hlasitost zvětšuje. Pozor. Nemají hlasitostní kolečko. Ovládají se hlasem vaším. Zde ovšem hrozí ztráta hlasu vašeho z přetížení vašich hlasivek. DBEJTE o váš hlas. Nakupte si vincentky do foroty.\r\n4. Právní příručka pro děti NEEXISTUJE. Neprodává se ani v Plzni. Dělat nezákonné věci je pro děti největší adrenalin. Napište si prozatím, co jste vyváděli v dětském věku vy a vyškrtejte si, co byste chtěli u vašich potomků co nejvíce eliminovat. No, aspoň pak můžete lépe sledovat, kde jste pak selhali a dovolili cokoli vašim dětem. \r\n5. Nikdy, opakuji, nikdy neodmítejte pomoc rodiny, kamarádů (ti vám asi nikdy nepomohou s dětmi, ale třeba se nějaký nebojsa najde), kamarádek (ty vyvažujte po porodu zlatem). Protože i pastevec má na stádo svých oveček alespoň jednoho pasteveckého psa ku pomoci. \r\n6. Natrénujte si pohádky. Co neznáte, dožeňte. Ptejte se známých, hledejte na ulici, studujte v institutu pro shromažďování pohádek (ten sice neexistuje, ale aspoň si ho představte, že je a dodá vám to trocha klidu). Buďte na chvíli aspoň Boženou Němcovou. \r\n7. Začněte posilovat. Miminka skoro nic neváží. Tedy, pokud vás nepoloží celkových necelých 5 Kg. Až se na vás pověsí děti starší (nedej bože, že jich bude více jak dvě) vaše tělo to pak nemusí ustát (pokud nemáte 300 Kg a více, to byste pak dát mohli). \r\n8. (Tento bod se nevztahuje na ženy) Pokud jste nebyli na vojně, nechce na sebe od vaší ženy každý den křičet povely, nechte si rozhazovat věci ze skříně a následně je dávejte do komínků nazpět, vytírejte s nejmenším hadrem, jezte málo a raději potajmu, zaveďte si režim jak na vojně. Pomůže vám to při počátečním nájezdu na režim dvojčat a vícerčat. Pokud totiž oni nebudou mít pak režim, rozlučte se hned ze začátku s klidnějším (ano, jen s KLIDNĚJŠÍM) soužitím s těmito dravci. \r\nJdu si udělat druhé kafe. První bylo na probuzení jednoho oka, to druhé je na to oko druhé. Pokračování rad bude zanedlouho pokračovat. Čest všem rodičům! Stavte mi sochu. Zatím žiju, žádná cévka (nerv) mi ještě nepraskl.'),
(137, '2017-02-22 21:37:09', 'Ne, ženy se nezapřou. To, že jsme si se ženou každý udělal to svoje dvojče, takže Amálka je spíš moje kopie a Emča Jáji, to je celosvětově známo. Ale že ta malá kopie mé ženy začne vystrkovat růžky už teď, tak na to mě nepřipravil nikdo. Zabezpečuji chod domácnosti i našich dvojčat. Jsem mr. Jekyll i doktor Hyde, teda vlastně spíš mr. zástěra i kladivo. Ale jako každý chlap, tak i já na něco zapomenu (tak dobře, přenesu to na dny příští, ale UDĚLÁM TO!). Tento měsíc začala Jája s přípravou zahrady už v únoru. Prý bude za chvíli jaro. Já jaro nikde nevidím. Možná se přes mé zamrzlé brýle špatně hledá. Dobře, všechen přebytečný rákos, co roste na zahradě jsem vyhodil, jen jeden zůstal. \r\n"Vyhodíš ho pak?" uzavřela první kapitolu probuzení naší zahrady Jája.\r\n"Joooo," myslel jsem si něco o tlení v záhoně.\r\nUběhly dva dny. Jasně, přes den jsem růžová baletka nebo princezna s křídly a musím dvojčata česat jako u kadeřníka, nebo s nimi tančit i nejpomalejší písničku na světě. Večír jsme jedna celá šťastná rodina společně až do večerky, a to pochopte, že se mi už nechce (zapomenu) zbylý rákos vyhodit. \r\nDnes otcovsky vysvětluji Emče, že musí počkat, neboť přeci připravuji jejich oblíbenou kuřecí šunku. Jája si kuchtí vedle mne nějaký nový recept (to se podívejte pak vedle do Recepty Jájiny pokusy). \r\n"Nezlob, nebo nic nebude..." domáhám se uklidnění situace, kdy mne neustále slovně Emča nedočkavě nutí zanechat prací a věnovat se jejímu problému. Otočím se s myšlenkou, že už je to vyřešeno. \r\n"Mami," vidím i takhle dozadu při krájení masa, jak si dcera stoupá na špičky a dívá se z okna. "Tatínek tu trávu ještě neodvezl, je pořád na boudě..."\r\nTICHO\r\nPOMALU SE NA SEBE S JÁJOU DÍVÁME, nejprve jedním okem, ale i to stačí, aby viděl jeden druhého, jak zadržuje dech se smíchem. Ta potvora mne normálně bonzla, udala, prodala! \r\nP.S. Vyvázl jsem s podmínečným trestem. Když toto píšu, klečím už tři hodiny v koutě na hrachu ;-) Teda Emča, ne já. Za to žalování :D :D :D'),
(138, '2017-02-26 10:05:09', 'Pipi dlouhá punčocha byla Jánina dětská hrdinka už jenom proto, že dokázala sama zvednout koně. Holky se na ni právě dívají taky a námořníci tam chrápou jedna radost. \r\n"Jé, oni chrápou jako tatínek! To je ošklivý..." \r\nNevím, kdo v tu chvíli protáhnul obličej více (asi já).\r\n"Jenže tatínkové chrápu rádi!" oponuji. "A ty, Amálko," obracím se na jednu z dcer, která ty kyselé obličeje na chrápání dělá nejvíce, "ty chrápeš TAKY!" \r\n"Nene, já nechrápu, já jen dýchám, hele..." a ukazuje pravidelné oddychování, jak když se vypouští trochu páry.\r\n"Ne, chrápeš taky! Slyšel jsem to..." oponuji a mohu to dokázat dlouhodobým průzkumem.\r\nTak a teď byste ten její obličej vidět nechtěli.'),
(139, '2017-02-28 16:52:56', 'Jsou chvíle, kdy jste tak rádi za to, že si můžete říkat táta od dvojčátek. Třeba, když po náročném dni, kdy korigujete celou domácnost (v oblasti domácího manažera mám vývojový stupeň dvě sta z desíti) a jdete si sednout ke stolu, abyste si vypili to druhé kafe, protože to první vám vyteklo v presovaru do spodního žlábku, protože jste si tam zapomněli dát hrníček a jedna z dcer se k vám nenápadně přiblíží, opře se něžně o vaši ruku a prohlásí:\r\n"AHOJ, FEŠÁKU!" a nevinně se na vás usměje...'),
(140, '2017-03-02 10:42:48', 'Otevřu jedno oko. Respektive mi někdo otevře jedno oko. Jde to tak těžko, jako když do tlustého ledu sekáte díru. Nade mnou se sklání bytost jak z jiného světa. Všude vlasy, že se málem leknu, jestli na mně nepřišla ona dáma z hororu Kruh. Pokouším se vstát, protože druhá vlasatá příšera jak z Hvězdných válek se po mém těle snaží projít tam a zpět. Nevstanu tak lehce, zdá se mi, že moje tělo funguje stejně jako naftový motor, do kterého se právě nalil benzín. Doškytám do koupelny a při mytí obličeje mne napadne jediná myšlenka, že mě dnes už ani svěcená voda nepomůže, protože se změnil tlak tak, že mi hlava zaručeně exploduje již při vysokém C. Posléze mi málem kartáček zarazí do pusy jakási meluzína motající se kolem mne. Není to k rozeznání jak je to rychlé a piští to. Bude to tedy opravdu meluzína. Ne, meluzína to nebude, protože když odtemním všechny záclony, rozprchne se to na všechny strany, že ani nevím, kolik toho doma je a začíná se to schovávat ve všech nepřístupných a malinkých škvírách. Že by nějaký hmyz? Ne, ten nemá dlouhé vlasy. Zkusím všechno živé v domácnosti sebrat a vystavit mým rozkoukaným očím. Mezi domácími mazlíčky rozeznávám konečně naše dvojčata hlavně podle zvuku, protože se hned rozutečou do svých pokojíků s hlasitým chichotem. Ráno rodiče může začít.'),
(141, '2017-03-04 09:16:44', 'Jednoznačně děti slovně vítězí, když to nečekáte. To, že jsou dvojčata ve věku, kdy každé nové slovo s radostí opakují, aby se v pozdějším věku mohly chlubit bohatou slovní zásobou (která stejně bude čítat jen "Hmmm" a No jo"), je normální a nemělo by mne nic překvapit, leč někdy si pusu musíte zašít chirurgickou jehlou a zalepit páskou, protože byste se mohli smát hodně nahlas. Zrovna jdeme celá rodina na procházkou s fenkou a já nesu rákos (ano, ten rákos, co jsem ještě neuklidil), aby se vyhodil k ostatním tlejícím rostlinám na místo, které je na to určeno. Už jsme skoro tam, a protože mi holky pomáhaly nést břímě a v rukou každá měla po jednom stonku rákosu, říkám Emče:\r\n"Pojď, vyhodíme to do kontejneru..."\r\nEmča nadšeně běží za mnou a opakuje:\r\n"Joooo, vyhodíme to do KRETÉNÉNU!"\r\nRákos mi padá málem z ruky, naštěstí jen do KONTEJNERU.'),
(142, '2017-03-07 10:35:39', 'Dvojčata dostala brýle. Nejsou to ty NADOŽIVOTÍ, tedy aspoň v to doufám, ale proto, aby se jim spravil zrak. Nechat změřit zrak Amálku je totožné jako dostat ze šéfa navýšení platu o padesát procent. Nyní už mají holky brýle doma, potažmo jim již sedí na nose, čímž má problém ZASE Amálka. Nejprve je nechtěla nosit. Zde nastoupilo přemlouvání, vyhrožování, vyděďování, vyhlášení války a nepomohla ani nabídka kvalitní čokolády. A to já s Jájou jsme v pohodě. Já nosím brýle od osmé třídy ve stylu start - stop, tedy celý den, Jája jen na čtení po porodu holek. \r\nDnes je holky naštěstí mají už od rána a už mi tu půl hodiny vymýšlejí hru točení se a následné narážení na nábytek. Zkrátka mi chtějí dokázat, že v těch brýlích nevidí, i když vidí. Jsou to malé brýlové teroristky.'),
(143, '2017-03-08 20:44:57', 'Všem ženám přeje tatínek, který si prochází tou samou "trnitou" cestou jako vy, co největší lahev vínka, nejpevnější otěže na děti a nikdy nespící obušek z pytle ven. Dobře, přeháním, zkrátka jen to dobré pro vás a celou rodinu. Hezké MDŽ!!'),
(144, '2017-03-16 09:42:27', 'Vstáváme do krásného slunného rána, kdy ani na obloze nejsou mráčky vidět a Amálka hrdě hlásí, že když nejsou mráčky, je venku určitě teplo a tak její horlivost zastavuji na větě o venkovním koupání. Emča si asi hraje na politiku, protože neustále navštěvuje cizí pokoje jen ne ten svůj a k tomu si prozpěvuje notoricky známé "Dunky, žalky a co já..." (díky Jardo Uhlíři)\r\n"Co ty? Hybaj, dítě neposedné, do svého kutlochu a převlíkni se." používám určitě slang dnešních mladých, protože mi rozumí a opravdu si jde do svého pokoje - hrát. \r\n"Panenky až potom," zní můj druhý příkaz tohoto rána a jdu připravovat veškeré vybavení na ranní hygienu. Najednou slyším hlasy. Naštěstí ne v mé hlavě, ale družný rozhovor holek. Nevím, jak mi mohly proklouznout kokem koupelny, ale ZASE jsou spolu. Emča zrovna smutně Amálce vypráví, že je malá oproti své sestře. Tak ano, holky už od narození nejdou nejen stejné (taky aby dvojvaječná dvojčata byla) což se podepsalo i na výšce i váze. Amálka na to šla vědecky a tak odteď už vím, jak to je:\r\n"Ano, Emičky jsou MALINKATÉ a Amálky jsou VELIKÉ." \r\nMá v tom jasno.'),
(145, '2017-03-16 20:25:04', 'Jak jsem vařil.\r\nNe, nejsem ani pejsek natož kočička, ale přes protesty Jáji se někdy dřevěného žezla také chopím a vyčaruji michelinské delikatesy typu míchaná vajíčka nebo domácí šunka s domácím chlebem. A protože i já někdy i já plánuji, řekli jsme si se ženou, že dvojčatům dnes udělám aspoň bramborovou kaši s rybou. Což o to. To se dá, ale když jsem byl veprostřed přípravy bramborové kaše, našel jsem v lednici sabdží s rýží, což holky už jedly a moc jin to chutnalo a tak jsem se rozhodl jídlo šéfkuchaře přesunout na večeři a na plotýnce jim ohřát variantu B. \r\nA hoj ty večere přišels brzy, jdu všem, takže i naší věrné zvířeně, připravit pochutiny. Kastroly chrastí, voda pomalu do varu se dostává, bramborová kaše se již pomalu připravuje na ohřev. Mám připravenu rybku malou, ne však zlatou, tím pádem poživatelnou, jen ji uvařit. Ukazuji Jáje můj VELKÝ problém s malými kostmi v rybě (no jo, to se prý jí. Jenže já třeba i pstruha pižlám 3 <!!!!> hodiny). A do srdce mne zasáhne jediná věta:\r\n"Už jsem tam připravila pro holky naši šunku, tak jim to ohřej s kaší a rybu uděláš zítra..."\r\nBeru hrnec a osolenou vroucí vodu vrhám do škopku. Krásně jsem si dnes zavařil. Za vroucí vodu si dávám 5 hvězdiček. Už můžu jít do Prostřena.'),
(146, '2017-03-18 10:43:48', 'Holky mají rády kosatky, delfíny a mořské panny. Je to na denním i nočním pořádku, že s nimi dělají vlastně úplně vše, což se mi zase moc nelíbí, ale asi to neovlivním. Sice předcházím hysteráku kompromisy, takže třeba opravdu delfín do auta může, k doktorovi však už ne, aby tam nic nechytnul. Horší je to s hlasy zvířátek. Přeci jen malé holčičky mají tenké hlásky, ale když nasadí ještě vyšší než vysoké C, aby si odlišily svoje švitoření s mluvou zvířátek, je dobré nemít migrénu nebo kocovinu, protože to pak můžete rovnou svou explodovanou hlavu vyměnit za jiný exemplář. Právě se nám tu Emča s Amálkou dohaduje o jednoho delfína, protože zkrátka toho druhého nehodlají hledat a je jednodušší se do krve pohádat o jednu hračku, než si tu druhou najít. Emče už dochází očividně trpělivost a završí to jedinou větou:\r\n"Amálko! Okamžitě mi dej toho delfína! Počítám do TŘÍ!! - Dva - jedna - osm - deset - dvanáct - šestnáct...!!"\r\nTo se té trojky Amálka asi nedočká. Delfín jí zůstane na doživotí.'),
(147, '2017-03-20 13:02:58', 'Právě si za mne Emča sedla s jejím hřebenem na vlasy. Je to taková ta holčičí drátěnka na vlasy, kde je asi miliarda malých umělohmotných jehliček, které ti zaručeně vlasy nejen rozčešou ale vytrhají zbylou kůži, možná se ten hřeben dostane i k mozku, protože vám na té hlavě pak už nic jiného nezůstane. A právě s tímhle hřebenem mne chce česat. Vím, co mne čeká a tak už rozmrzele v poledne v tom okamžení odmítám její služby zdarma. \r\n"Tati, počkej, já ti učešu vlásky!"\r\nNelze už ustoupit, nelze odmítnout dětskou natěšenou dušičku. Emča zcela v euforii pomalu, ale o to víc s vervou její vlastní zabořuje jehličky hluboko do mé kůže a s průpovídkou, že mám krásné vlásky a že mi po učesání mých deset centimetrů rychle naroste do mohutné hřívy hned zase opouští své stanoviště za mým krkem a odplouvá za Amálkou co by mořská panna s hlasitým voláním:\r\n"Amálkoooo, Amálkoooo, už můžu dýchat pod vodou, už jsem pravá mořská panna!"'),
(148, '2017-03-21 10:57:32', 'Několik málo rad pro budoucí rodiče (hlavně pro muže, protože ty to ještě geneticky zakódované nemají a proto musí tvrdě trénovat) dvojčátek a mnohočátek (ČÁST II.):\r\nTéma OBRANA\r\nPokud zrovna nejste ministrem obrany či z lepší strany nejste její vrchní velitel, tak vás před touto armádou zhola nic neochrání. Jen je tak trochu zpomalíte. \r\n\r\n1) Dobré je bydlet do výšky prvního patra. Ocení to zvláště pro ti, kteří si nechtějí ublížit a zároveň hodlají vyklidit bojový prostor v cuku letu. Máte-li vlastní domek s nedej bože zahradou, nevycházejte hlavně v noci bez rozsvěcených halogenů ani na milimetr z terasy. Pokud tak učiníte, zaručeně vás zatknou za rušení nočního klidu a mravního pohoršování vulgarismy, když šlápnete na hrabičky, kyblíčky a vozíčky a další. \r\n\r\n2) Ze starožitnictví si objednejte aspoň dva páry železných rytířských bot. Pokud je nemají na skladě, zamiřte do prvního hradu ve vašem okolí. Tuto domácí obuv tatínkové ocení hlavně v zimním období, kdy se dům mění podle přání malé armády, která všude zapomíná nášlapné miny. Nejčastějšími nášlapnými zbraněmi rodičovského ničení nohou jsou chlapecké kostky a dívčí špičaté korálky. Také tomu předejdete, když tuto munici zcela vypustíte z vašeho plánovaného rozpočtu. \r\n\r\n3) Čím víc máte známých, tím větší je riziko zvýšení počtu malých rekrutů. Máte dvě možnosti. Nikoho takového dalšího neznat. Na dalších dvacet let. \r\n\r\n4) Nenechte se zaskočit. Hlavně pláčem. Voják NIKDY nepláče. Je to krycí manévr k dosažení cíle. Pokud podlehnete, stane pláč teroristickým útokem všedních dní. V tom se řiďte pravidly světovým mocností, což vlastně jste i vy: s teroristy se nevyjednává. \r\n\r\n5) Naučte se tři jednoduché povely. Ze čtyřstránkových depeší si vaši malí vojáčci nebudou vědět rady. "Sedni si" - "jez už konečně" - "nedělej to" postačí. Doplním ještě: "Spi už!"\r\n\r\n6) Je jedno, kdo z vás, rodičů, je doma generál major a kdo plukovník. Pokud zaúkolujete daleko více jeden druhého než několik svých podřízených, váš domov se změní v obléhací tábor. Nepřipusťte to. Leda byste byli starověká Sparta...'),
(149, '2017-03-27 11:19:06', 'Nemám to jednoduché. S dvojčaty jsem právě na dětském hřišti. Houpou se na speciální provazové houpačce. Emča neposlouchá, skáče z ní a málem ji trefí. Domlouvání nezabírá a při otcovské řeči jí chci upravit čepici. Reakce zlobivého dítěte je samotrestající. Emča mi chce utéct a naráží na sloup houpačky. Je to boule. Červená boule. Jsem fakt ďábelsky špatný, špatný otec.'),
(150, '2017-03-30 09:17:05', 'Teče mi z očí, ale slzy to nejsou...\r\nNevím, co dýchám, ale astma to není...\r\nČervený nos, ale zima mi není...\r\nCo je to, princi... ?\r\n.... jo, sakra rýma, Popelko... EEEEEEEEPČÍÍÍÍÍ'),
(151, '2017-03-30 18:47:16', 'Co nevidět tu bude duben a to už vyjde čtvrté číslo pravidelného měsíčníku Pravý domácí časopis (http://www.pravydomaci.cz/201704) Nejen, že tam najdete spoustu dobrých článků a chytrých odpovědí, nejen, že je opravdu domácí (tvořen jednou super rodinou), nejen, že má originální přebal, ale mám tu čest být jeho součástí, respektive moje dvojčata, protože tam píšu takové lehce humorné postřehy (i humorné obrázky, kterými vás taky někdy častuji) ze života tatínka na rodičovské dovolené (a samozřejmě po ní). Je to psáno zcela jinak, nežli jste zvyklí z těchto stránek a i název je jiný: Když táta vidí dvojmo. \r\nDoufám, že se vám jak časopis, tak i mé (i jiné) příspěvky budou líbit. Na to pravé domácí čtení je to jak dělané'),
(152, '2017-04-01 17:46:56', 'Právě jsem zjistil, že mi dvojčata vytunila auto. Božské "E", vyryté na skle, je mi svědkem, ze jsem opravdu neskákal dva metry vysoko už jen proto, že bych se bouchl hlavou o trámy. Ale dostat z nich přiznání je těžší, než ho dostat z Bonda. Asi jim i zabalím ruce do celofánu, aby je nenapadlo vzít v pozdějším věku třeba plamenomet do ruky.'),
(153, '2017-04-03 09:07:48', 'Už od rána se mi tu dvojčata hádají. Zcela o všem a musím říct, že i trochu oprávněně, protože Emča Amálce zkrátka nedá pokoj a zkouší, co všechno vydrží. Asi už dneska přetekl ten velký pohár trpělivosti, který má Amálka dosti vysoký, za což má můj skrytý obdiv, protože já startuji na první dobrou.\r\nNejprve pískot, pak jekot pak zamručení a následuje věta Amálky:\r\n"Chci jinou kamarádku!" \r\nChvíle ticha a pak Emča tázavě:\r\n"Ty si najdeš, Amálko, jinou kamarádku?"\r\n"Ne! To TY si najdeš jinou kamarádku!!!" vyhrkne Amálka. \r\nJeště, že ty žabomyší války končí vždy objímáním.'),
(154, '2017-04-04 20:45:56', 'V překrucování souvětí, vět i názvů jsou naše holky stejně tak dobré jako já sám. Zkrátka asi mají tu nejvyšší školu. Jako tuhle nyní. Dvojčata šla na procházku s Jájou a i naší fenkou Leou. Zkrátka takový idylický den, pohodová hodina. Holky skáčou, lezou, běhají, jenže Emča není nějak ve své kondici. Když se jí Jája zeptá, zda už byla vyprázdnit ten svůj malý břich, když viděla, jak se za něj pořád drží, hned odpověděla bez zaváhání:\r\n"Ještě ne, ale asi mám ZAMČENÝ PRDY..."'),
(155, '2017-04-05 11:00:23', 'Mnohokrát se slunce muselo obrátit od východu k západu, než nás doma svou jedinečnou návštěvou potěšil můj dlouholetý kamarád, chlap veliký jako hora Říp a zarostlý jako KRNAP, který kypí vždy dobrou náladou a pohoda je jeho druhou sestrou. Přijel ve dvou a jak už to tak bývá, naše dvojčata hned od začátku na jeho něžnějším doprovodu neustále visela, což se třeba projeví při pití kávy, kdy si ji člověk může vychutnat opravdu jen vší silou a při tom musíte ještě držet balanc, abyste nic nevylili. O co se však musím podělit je jistý fakt, že i Amálka dokáže mého kamaráda vypéct. Jistě je pochopitelné, že po pár hodinách návštěvy my, starší, potřebujeme navštívit onu místnost a leč je náš útulný domeček malý, toalet spolehlivě najít rovná se bloudění po rozsáhlém hradě. Naštěstí jsem mu třímetrovou cestu vysvětlil, dokonce tam i došel, leč světla prozatím nedohledal a tak, než jsem mu to zmateně vysvětlil a snad i proto, že s námi mezi dveřmi diskutoval o nepodstatné věci, proklouzla Amálka za něj a aniž by něco řekla, stáhla si kalhoty a jala se vykonávat to, co nutně potřebovala. \r\nPokrčil jsem s úsměvem - dobře, se smíchem - rameny.\r\n"Nezbývá ti nic jiného, než vyjít schody, tam je druhý..." \r\nJak se v mládí říkalo: KDO ZAVÁHÁ, NEMÁ... :D'),
(156, '2017-04-09 13:54:33', 'Člověk míní, příroda si mění jak chce, protože dvojčata zlobí (takže malí kriminálníci), já jsem neustále nervák (takže psychouš) a ke všemu přijdeme z procházky a naši nejmladší fenku najdeme v rozvrácené kuchyni nehybnou na přední packu (packy), takže rychlovka k veterináři, teď tu leží, dvojčata stále zlobí (asi to nechápou, což chápu dětský mozek, ale já už nechápu je a to jsem dospělák)... Mám to já ale krásné a vtipné nedělní poledne.'),
(157, '2017-04-11 12:56:56', 'Jedu si to tábořit Škodou 100 na Oravu... ne, vlastně jedu s dvojčaty směr hlavní město na kontrolu jejich optiky, kterou mají i tak sokolí, protože vidí i za roh. A protože si to auta zase rychlostní silnicí šinou pozvolna dvacetikilometrovou pomalostí, neváhám se zařadit mezi dva kamiony, což je ten pruh, který je vždy pomalejší a chci se dostat do hlavního Golfského proudu nalevo, kde to sviští o pár kilometrů v hodině víc. Ale jsem otec zodpovědný a nechci se hned hrnout před jedoucí auta a tak vyčkávám větší mezery, abych se zařadil, když v tom na mne vyhrkne Emča.\r\n"Tati! JEĎ SI DO DRUHÝHO PRUHU!!" \r\nNo, nevíte NÁHODOU, po kom to asi má???'),
(158, '2017-04-17 14:46:30', 'Už jsem hodinu vzhůru a přemýšlím, zda ty moje všechny holky už mám vzbudit jako uragán japonskou vesničku a vyšupat jim zadnice za celý rok. Ale pozor, čert nikdy nespi. Třeba Emča. Ta je chytrá. Začala používat novinku. Třeba tuhle, když jsme naše dvojčata chystali do postelí, trochu jsem zlobilky zlechtal, což ostatně samy vyžadují a pak následně žadoní o ukončení činnosti. Jo, to pak naslibují věcí jak politik před volbami. Ale najednou se Emča ozve:\r\n"Tatínku, dooooost, hihi, dost! Já ti dám peníze!! Hihi."\r\nNapadají mne dvě věci: jak malé dítě může vědět, co je úplatek a - kolik by mi asi, sákryš, mohla dát? :))'),
(159, '2017-04-23 11:21:52', 'Hledat parkovací místo, když se jede po úřadech v hlavním městě, je stejné jako hledat jednorožce nebo přemluvit modelku, aby opustila fotbalistu pro kámoše, co opravuje žehličky. Ale naše vědma Emča, ta ví všechno. Amálka se nechá vozit a nic neříká, ale Emča naviguje a ujišťuje, že tam místo bude.\r\n"Tati, jeď tam..." (neví kam, ale mám TAM jet) "...a tam ti ukážu tajné parkovací místo." \r\nZajel jsem do uličky za úřadem a jedno místo tam bylo.\r\n"Tak vidíš, že to tajné místo tu bylo..." byla na sebe hrdá dcera.\r\nTak mi tu teď o to víc mluví do řízení...'),
(160, '2017-04-23 11:22:28', 'Musím si asi detailně prozkoumat kalendář, zda se nějaký sváteční den ještě neschovává v tomto roce. Ne, že bych neměl svátky rád. Rodina je doma celá, přijedou i návštěvy, lednička je nacpaná od Jájinýho vaření, o tom žádná, ale například Vánoce, Tři králové či Velikonoce si vyžadují speciální zpívání nebo říkadla, které se s chutí naše dračice chtějí naučit, aby je v ten daný den použila. Paměť mají sloní. Hned se to naučí a já se hrdě dmu až málem prasknu pýchou, jak jsou to holky šikovné. Jenže, pak to přijde. Od Vánoc slyším: "Mikuláš ztratil plášť," "Rolničky s Kašpárkem", do toho filmová vsuvka á la "Dunky, žalky" s "Najednou, najednou chci skončit s tou hloupou hrou..." zakončeno "Hody, hody, doprovody..." Pak už jen zbývá asi rokenrolová písnička "Jan Ámos Komenský, to byl kádr na ženský," a až bude Jan Hus, raději jim zamlčím chorál "Kdož sú boží bojovníci." Ujistěte mne, že už žádné jiné svátky nejsou. Hledám tu s lupou v kalendáři nějaký ztracený a naštěstí už nic nevidím.'),
(161, '2017-04-23 11:23:08', 'Zabavte mi všechny chytré telefony a dejte mi jen Nokii 3210! Už mám ZASE prasklé sklo!!!!!!!!!!!!!!!!!!!'),
(162, '2017-04-24 10:03:21', 'Včera přijela teta Jíťa a s ní přijelo překvapení, které si rozhodně naše čertí dítka nezaslouží, ale co se dá dělat, džíny z toho pro sebe neudělám a tak jim ty šaty z Ledového království zkrátka zůstaly. I když se zamyslím, že by mi džíny se závojem a třpytky asi moc neslušely a vypadal bych jak ze 70. let a to bych si mohl nechat narůst i pejzy. A tak tu holky brázdí celý dům v šatech, neustále si upravují korunku a kdykoli je minu, vyzvou mě na malý tanec s větou:\r\n"Trsnem si, fešáku?"\r\nStejně se zákeřně bavím na jejich účet, protože (a ženy jistě tuší proč) ty velké princeznovské šaty jim dělají trochu peklo z každého kroku. Není chvilky, kdy by mi jedna z holek nezmizela z obzoru, protože si přišlápnou šaty. Jde to rychle. JE  a najednou NENÍ. Válí se po zemi se slovy:\r\n"To nic, jsem v pořádku..." \r\nMyslím, že dnes si smíchem prodloužím život o dalších dobrých pár měsíců.'),
(163, '2017-04-25 14:55:33', 'Já jsem musel být v minulém životě hodně zlý člověk a nyní se na mně všechny křivdy napravují. Jinak si nedokážu vysvětlit stávající situaci, kdy vytírám dům a mopem zajíždím snad do každé škvíry a podlezu (třeba pod pohovkou). Dvojčata to komentují (jako PROČ, proboha??)\r\n"Tatínku, krásně to děláš..."\r\n"Pozor, tatínek zanechává mokro, to je moře!"\r\n"Tatínku! To je KRÁÁÁÁSNÝÝÝÝ!"\r\n"Tatínku, ty jsi K(G)ENIÁLNÍ!!!" (při tom mne z pohovky Emča pohladí po vlasech - ano, lezu po čtyřech)\r\nProč jsem geniální, to nevím, ale i nejznámější filmová uklízečka paní Kiliánová byla asi geniální, protože se jí klaněli všichni doktoři.'),
(164, '2017-04-25 19:40:59', 'Právě se jdou dvojčata umýt a pak, po přečtení pohádky, rychle spát. Doprovodím je do koupelny a Emča se na mě otočí se slovy:\r\n"Tati, ty máš tričko jako svetr..." myslí tím, že mám triko s dlouhým rukávem a dál pokračuje. "Ty jsi jako zebra..." glosuje mé krásné pruhované triko s dlouhým rukávem.\r\n"Ty jsi náš krásný ZEBROUCH!" a pak dodává:\r\n"...a maminka taky." (Jája má totiž pruhovanou mikinu)'),
(165, '2017-04-28 08:33:40', 'Dneska Emča v šatech Elzy z Ledového království zpívala písničku:\r\n"Já jsem krásná princezna a vzala jsem si prince. A pak jsem si vzala druhého a na tamtoho jsem vykašlala." \r\nOtočila se dokola a dodala s úsměvem: "Je to krásná písnička, maminko, hezky jsem to zazpívala?"\r\nVynořil jsem se z kuchyně, kde jsem právě dělal dvojčatům večeři. Brýle mi spadly na špičku nosu a s otevřenou pusou jsem hleděl na konsternovanou Jáju. Padla otázka:\r\n"Kam na to chodí?!"\r\nJája jen pokrčila rameny. Už teď se "těšíme" na další písničku. Chudáci princové.'),
(166, '2017-05-03 23:18:14', 'Dnes jsem se mohl přesvědčit, že v tom nejsem sám. Teď konečně mohu s klidem říct, že co nevidět mohu zúročit měsíce Spartské výchovy a říci si, že z těch mých holek ty válečnice jednou budou. Ale neusnout na vavřínech. A taky si nelámat hlavu nad občasným brekem se smutnýma očima. Jdu z procházky s naší ovčandou. Zbylý ženský předvoj byl v tu chvíli již doma. Míjíme si to malebný baráček a to by nebyla naše čtvrť, aby všichni kolem něco na svých stavbách nedodělávali. A tak i zde je za humny i před humny hromada písku, kde si hají dítka malá, jak paní domu, tak její kamarádky. No což, jsem skorosoused, zastavím se na kus řeči. Živáčka na popovídání jsem už neměl pár delších týdnů a v práci si člověk nepotlachá. Zaujal mne klid obou dam, když se zjistilo, že děti hrající si na pískovišti jsou nejen celé od písku a dál si ho sypou na sebe, ale i fakt, kdy se zjistilo, že malá slečna vrhla na písek i okolní zem to, co měla strávit a kupodivu se při tom ještě smála. Sousedka, stále v klidu a s průpovídkou, že jsou to jen děti a mají si hrát a dělat všelijaké vylomeniny, vzala konev do ruky - tady jsem trochu čekal umytí dítěte od zvratek z konve - a očistila inkriminované místo na zemi. Tak jsme jako zdatní rodiče vybrali zajímavé téma "zvracení dětí v našich rodinách," ale to už si malé dítko štrádovalo dále po trávníku směrem ke skluzavce a při tom ztrácelo plínku. Samozřejmě k jeho blaženosti na rtech a spokojeně se usmívalo i tehdy, když zmizelo na onu avizovanou druhou hromadu písku za domem. Stalo by se toho asi více, ale to už mi zvonil telefon a volala má drahá polovička. A tak jsem si říkal: "Moc to řešíš. Až ti dvojčata spadnou z houpačky, když nenajdeš krev, je to v pohodě. Když snědí hlínu na našich záhonech, nevadí, je to naše hlína a žížaly ji tak jedí..." Klaním se hluboce sousedce i druhé sousedce. Mám se ještě co učit.'),
(167, '2017-05-04 15:53:52', 'Začnu vtipem. Starým vtipem. To se paní učitelka ptá dětí ve škole, co dělají jejich otcové. Maruška vypráví, jak její tatínek opravuje auta, Karel zase, že jeho tatínek je lesníkem, jen odrzlý Pepíček stále mlčí. Když však na něj dojde nakonec řada, odpoví: "Náš táta tancuje u tyče v gay baru..."\r\nPaní učitelka se zděsí a chce to trochu napravit: "Chceš říci, že uklízí s mopem v nočním podniku, že?"\r\nNačež se Pepíček kysele ušklíbne a vyjde s pravdou ven: "No to vlastně ne. Náš táta je politik, ale my doma se za to stydíme..."\r\n\r\nTak jsem si trochu připravil půdu, a ač zcela apolitické je toto tlachání o dvojčatech, dnes jsme se tomu v autě cestou domů z dílničky nevyhnuli. Že já si nedám na pusu lepící pásku. \r\nPřejíždíme nechráněné koleje, takže člověk musí zastavit, rozhlídnout se, jet dál, děti se stačí pokochat a vysondovat nové skutečnosti. Na kolejích se totiž "maká" a toho využila Emča ke konverzaci.\r\n"Tati, co tam ti pánové dělají?"\r\n"Nové závory."\r\n"A jak jim to bude dlouho trvat?" zamyslí se a hne si odpoví, "třeeeeeba patnáct MINUT?"\r\nTrochu se tomu zasměji a opravuji ji:\r\n"Ne, ale určitě více jak patnáct DNÍ ano..."\r\n"Tak dloooooouho? No to si snad ze mě děláš legraci?" skoro hláskuje. A tady následuje rodičovská chyba, že v té konverzaci dále pokračujete, jako by člověk hovořil s dospělákem.\r\n"Teda Emí, ty bys mohla být ve vládě. Všechno by hned odsýpalo..."\r\n"CO?! JÁ? TAK TO NIKDY! Já tam sama nebudu!"\r\nMusel jsem si uvědomit, že řídím, jinak bych klesl smíchem k zemi. Emča si pak uvědomila, že neví, co to je. A když neví, co to je, chce to ukázat na telefonu jako obrázek nebo video.\r\n"Tati, ukaž mi co je to vláda!"\r\nZakoulel jsem očima, ale uvědomělá Amálka mne podržela. \r\n"Ne, nic ti neukáže, tatínek řídí!"\r\nPřísahám, že už nic dětem říkat nebudu, Fakt!'),
(168, '2017-05-05 16:58:28', 'Tak ne Emča, ale dost mne teď zaskočila Amálka. Sedí u stolu a já připravuji jídlo. A najednou se ozve od Amálky věta:\r\n"Já jsem kráva..."\r\nOtočím se více jak nechápavě s otazníkem v očích a jediným slůvkem:\r\n"Co?!" \r\n"Tatínku, já jsem kráva," hrdě dál hlásí dcera a na mé přiblížení reaguje názornou ukázkou, ze které mi spadl kámen ze srdce.\r\nHrála si totiž s ponožkou a zajetím mezi prsty na noze si udělala názornou ukázku sudokopytníka. Jak jsou ty děti vynalézavé. Škola hrou.'),
(169, '2017-05-10 21:38:40', 'Jak jsem s dvojčaty cestoval. \r\nNevím, zda jízda v hromadné dopravě s dětmi je za trest, za odměnu nebo za jízdenku do Bohnic. Na začátku všeho se pyšníte čistými dětmi. Jenže ty si posléze kleknou k jednomu jedinému mravencovi na zastávce autobusu, jehož rychlost byla větší, než holek hlasitá oznamovací věta, že: "Tatínkůůů, hele, vidíme Ferdu Mravence!" \r\nNevím, proč se v mých očích po rozptýlení prachu z jejich kalhot objevila jako fata morgána pračka. \r\nZjednal jsem si pořádek už jen proto, že by do deseti minut, za kdy jel autobus, zmizelo v okruhu dvaceti metrů kolem zastávky všechno kvítí, potažmo i kosatce nedalekého úřadu města.\r\nPo nástupu do autobusu jsem se sice trochu cítil jako Mojžíš, ale asi jenom proto, že vlna hlav nejprve klesala za dvojčaty a hned zase uhýbala přede mnou, protože funící otec doháněl své ratolesti, aby se mohly posadit. Zamířily mršky rovnou dozadu, já to mám rád v předu, ale asi jsem tak dlouho nejel autobusem, že se mi mdlo a špatně nedělalo. \r\nVyskočili jsme u metra. Dlouhá chvíle tří minut, než přijede souprava vypadala asi stejně, jako když jedou sportovní fandové na utkání. Holky jsem sice držel za ruce, aby se mi hromadně nevrhly do kolejiště, protože je ta propadlina neustále přitahovala a tak u mě skákaly, že se málem pár jedinců přidalo i se skandováním: "Kdo neskáče, není Čech...!"\r\nV metru jsme si sedli čelem ke všem spolusedícím i stojícím. Příště vymyslím strategičtější místo, potažmo si ukradnu neviditelnou čepici Rumburaka. Nevím, co na Emče paní naproti tak zaujalo, ale neustále se uculovala, že jsem se musel dívat, jestli ta moje dcera nedělá nějaká posunky. Možná vysílala tajnou morseovku nebo Navaho kód, ale nic jsem nezaregistroval. Cuklo to. Tak jsem holky víc držel rukou na sedačkách, aby nepřistály na podlaze. V tom jsem nahmatal velmi tvrdý kulatý předmět v Emčině kapse u kalhot. \r\n"Co to je?" chtěl jsem šeptat, ale nějak to nešlo. Paní se začala uculovat více.\r\n"To jsem si jen chtěla vzít do vláčku jako píšťalku..." nevinně hlásila dcera a já vytahoval jeden kostkový váleček za druhým. Paní odvrátila hlavu a zakryla si rukou pusu. Mě zbylo už jen se poprat o druhou kapsu s posledními díly kostek lega. \r\nPřestoupili jsme do dalšího metra na jinou trasu. V polovině cesty přistoupila mladší slečna s černými kalhoty. Ty si zapamatujte. Ale pohleďme zpět na už nudící se dvojčata. Emča se začala po mně válet, Amálka zkoumala všechny strany a možná i všechny lidi. A šili s nimi všechny čerti a nástup byl rychlý - BUM! \r\n"Co to děláte! Uklidněte se! nejste tu sami!" klidním obě a otáčím se na slečnu. "Promiňte..." plaše ze ne vypadne. Bílá tečka od bot dvojčat moc na jejím koleni naštěstí není vidět. \r\nHolky daly pokoj. Na chvíli. Metro ani nestačilo projet jednu stanici. BUM!!\r\n"Tak ale! A omluv se slečně!" šlehnul jsem vstřelenou pravačku Emči nazpět a úplně zmateně jsem zrealizoval nejblbější nápad. Slečně jsem s omluvou na rtech trochu druhé bílé koleno černých džínů opucoval. Slečna měla sluchátka v uších a asi jí místo písničky šel desátý díl sebeovládání, protože se jen usmála, jakože to nevadí. \r\nPět, čtyři, tři, dvě stanice.... jedna...pryč. V metru jsem fakt musel vypadat jak dinosaurus. Krátká cesta posledním autobusem na místo určení už nikoho ani nás neohrozila. Ano, zlaté auto. Svět ještě není moc připraven přijmout naše dvě tornáda. Ale jednou, jednou překopeme i Václavák.'),
(170, '2017-05-12 08:57:21', 'Asi je něco špatně, když v koupelně sleduji oba kartáčky, můj i Jáji a za boha si nemůžu vzpomenout, který je ten můj...'),
(171, '2017-05-15 09:30:48', 'I u nás se slavil den matek. Tedy, bylo to s předstihem jednoho týdne, ale včera si to pak ještě jednou dvojčata zopakovala a Jája obtěžkána jako vánoční stromeček přijala s nadšením gratulace nejmladších. Já ovšem slavím taky, mám taky svůj den. Slavím ho, kdykoli to jen jde. Jmenuje se Den Zmatek. Chlapi, ano, to je NÁŠ den ;-)'),
(172, '2017-05-19 09:54:04', 'Začíná být jarní léto a tak vytahuji jarně letní svršky. Obměna je jistá i u spacího vybavení a tak teplé hřejivé pyžamo s nohavicemi a rukávy delšími než máte nohy a ruce odhazuji v dáli (no dobře, tak do koše na prádlo) a vybírám ze skříně jedno s krátkým rukávem se Simpsonovic rodinkou. Vítězí černobílý Houmer. Akorát, že ke mě přistoupí Amálka a něžným hláskem glosuje:\r\n"Jé, tatínku, ty máš Houmla!"\r\n"Ano, to je Houmr..." jdu jí příkladem ke správné výslovnosti písmene R.\r\n"Ano, HoumLR," dál pokračuje svoji zavedenou nit Amálka a dodává. "Ten má ale kulaté bžicho! Tatínku, ty takové nemáš, ty máš jenom menší..."\r\nJasně. Jsem jak Bud Spencer, hlavně, že nejsem Houmer.'),
(173, '2017-05-23 22:28:48', 'Při zimních večerech jsem tu psal, jak se holky baví tím, že kouzlí. Čáry máry fuk a mám břicho dvakrát větší, čáry máry fuk a konečně mohu vydechnout a vrátit břicho na normální štíhlejší pozici. Dlužno říct, že tím zaměstnávaly i Jáju a víte, jak to je, když ze sebe dobrovolně žena dělá tlouštíka. \r\nJenže, to jsme netušili, že se nám tato kratochvíle jednou vrátí i s úroky. Respektive vrátí mé osobě. \r\nDnes si tak sedíme celá rodinka i s nejmladší fenkou v čekárně u zvěrolékaře. Nejsme sami. Sedí naproti nám jakási náctiletá pohledem nezúčastněná slečna, a dvě dámy. Obě mají v přepravním boxu kočky, ale ta druhá dáma měla tu smůlu, že přišla později a tím pádem stanul zájem Amálky o kočku dámy první. Zde přichází pravidlo, že co nechcete, aby vědělo okolí, neříkejte dětem. Ještě, že nemáme trezor s číselnou kombinací. To by určitě Amálka v družném rozhovoru sdělila jako věc číslo jedna. Ale vraťme se k rozhovoru Amálky s dámou. Přejdu střípky seznamovacích vět a přejdu k bodu o kouzlení.\r\n"....ty jsi ale šikovná holčička, a co umíš ještě?" \r\nTato povzbuzovací věta dostala Amálku do druhé dimenze.\r\n"Já umím kouzlit..... trochu"\r\n"Kouzlit?" Chápavě předstírá zájem dáma a dodává. "A ukážeš mi něco?"\r\n"Já moc neumím, to spíš tatínek..." přiznává dcera moji taktiku zmizení malých hraček, protože oblafnout dítě je lehká věc, to ví každý. \r\n"Ale umím tatínkovi přičarovat velký břicho!" vzpomene si najednou Amálka a skoro povyroste.\r\n"Břicho?" podívá se mým směrem paní a Jája vedle mě slzí smíchy. \r\n"Udělám takhlen fuk a takhlen fuk a tatínek má velký břicho. Tatínku, pojď sem..." \r\nTo už cukají koutky i náctileté nezúčastněné slečně. Jája, ta se směje a paní na mne soucitně kouká, protože vypadám na velmi týraného pokusného králíka. Za chvíli přichází doktor a já s radostí dáme tlumočím, že už je na řadě. A ze mne se brzo stane asi chameleon. Splynout s okolím a nebýt viděn. To bude priorita od zítřka.  '),
(174, '2017-05-29 10:51:12', 'Ráno, raníčko Amálka vstala, šaty si ani neuvázala a z jejího pokoje slyšet je zvuk, který direktivně příkaz zazní ve velký hluk:\r\n"Panenky, vstávat!"\r\nTo je tak, když v dobré víře koupíte holčičkám postýlky pro panenky. Emča si do své malé postýlky narvala veškeré plyšáctvo, co našla. Ale zase pak není nad spokojené výrazy. Zase jednou dítě zvítězilo nad hmotou rodičovskou.'),
(175, '2017-05-30 22:23:11', 'Dnes nám perlila Amálka. Ano, naše tichá dáma, o které se zde dočtete jen v náznacích a když už je něco potencionálního na obzoru, dokáže ze všeho mistrně vybruslit. \r\nDošly štětičky naší oblíbené červené štětky na nádobí v kuchyni a tak po vzoru dobrých hospodyň jsem jí vyhodil a nahradil novou, modrou. První to po pár hodinách zaregistrovala právě Amálka, když Jája zpracovávala kuřecí v kuchyni (jen tak mimochodem, výbornou domácí šunku jsem udělal). \r\n"Jé, hele! Ta štětka je modrá! Ona je kouzelná!" hlásá hláskem dítěte uchváceného stoprocentním zázrakem.\r\n"Vidíš, ani jsem si nevšimla..." pokračovala v kuchyňské etudě Jája dál. Ale Amálka pokračovala.\r\n"Jak se to jmenuje? Jak to mění barvy?"\r\n"Chameleon," odpovídá jí automaticky Jája dál. A hlásek Amálky se znovu mění v nadšenost samu.\r\n"Jé! My budeme mít KAMLEONA!!"\r\nTeprve nyní si Jája uvědomuje, že se Amálka dále ptala na to maso, co se zpracovávalo. Takže ano, jíme doma (Jája maso tedy nejí, ale my joooo) CHAMELEONY, ale jednou tu změnu na kuřecí si můžeme dovolit.'),
(176, '2017-06-01 12:42:57', '"...děti pro radost a radost pro děti... po práci legraci..." aspoň malý úryvek budovatelské odysey z Císařova pekaře a Pekařova císaře, neb to mám dnes stejné. Po práci legraci ve formě moderování dětského dne v Aréna Sparta Podvinný mlýn a premiérově s sebou beru i dvojčata. Prý tam zazpívají do mikrofonu (kterého se vůbec nebojí, že by geny?) nějakou písničku. Tak uvidím. Třeba mne i překřičí a třeba je jednou uvidím já na nějaké obrazovce číst zprávy. Teď mi akorát tak čtou myšlenky, protože dělají všechno, na co pomyslím, že dělat nemají. Tak už jen popřeji krásný - mezinárodní - DEN DĚTÍ!!!!'),
(177, '2017-06-01 22:26:53', 'Dnešnímu dni Emča říkala DEN OTEVŘENÝCH DĚTÍ.'),
(178, '2017-06-02 10:05:39', 'Dneska ráno bylo jako každé jiné. Počkejte, vlastně nebylo. Jediné správné bylo:\r\n"Dobré ráno, tatínku..."\r\nPak už to byl jen slovní fotbal mezi dvojčaty. Naštěstí jen slušně, ale s výhružkami. Suma sumárum zakončeno všechno bitkou. Dlouho jsem nechápal, co se vlastně děje a naprosto dezorientován jsem si myslel, že se jedná o výměnu jejich kartáčků. Ne. Prosím, ony se popraly o to, který jejich kartáček bude blízko kartáčku maminky nebo tatínka! Neříká se tomu žabomyší války?'),
(179, '2017-06-05 14:20:17', 'Holky viděly pořádný biják. Neptejte se mne jak, kdy a hlavně proč, protože sám bych se bál taky, kdybych sledoval Jurský park. Jenže! Amálka má v dětské knížce dinosaury a tak, když zahlídly v TV ukázku, asi to chtěly vidět. Emča si to prý vychutnávala (trochu se víc ničeho nebojí jako moje žena, která se i na horor kouká jak na romantický film o dvou medvídcích0). Resumé Amálky bylo, že ještě před filmem by chtěla možná i živého dinosaura, což naštěstí nejde a tak už byla smířená s plyšovým. Plyšový dinosaurus byl prý odmítnut již v druhé polovině filmu. Ale dokoukaly ho a prý ho známkují 4 hvězdičkami z 5. Druhý den už Amálka chodila zase s knížkou, kde jsem jí musel předčítat jména dinosaurů, které asi tvořil úchylný jazykozpytec.'),
(180, '2017-06-07 11:45:38', 'Děti mají zcela jiné hodnoty, než dospěláci. To bez pochyb. Děti vnímají vzdálenost jinak (po ujití 368 metrů: "Tatínkůůů, mě už bolí nožičkyyyy!"), vnímají velikosti jinak ("To je ale VELKÝ míč!" bere do ruky tenisák) a také čas je pro ně relativní. Jako včera Emča. Když něco chce, myslí tím HNED, potažmo už to mělo být tak PŘED PĚTI MINUTAMI. \r\n"Mamíííí, jak dlouho to bude trvat (než něco dostane)..."\r\n"Chvilku, Emí..."\r\n"Chvilku? To je DLOUHO!!" znechuceně odpovídá dcera. \r\n\r\nP.S. K "luskovat" a "Kapsárkovi" přibyla další názvoslovná hříčka: U slova "BĚHULA" se Jája opravdu dusila smíchy. Chudák běluha, takhle jí měnit jméno, takové milé mořské zvířátko od kytovců :D'),
(181, '2017-06-10 18:16:27', 'Psala mi Jája. \r\n"Amálce jsem zakázala koloběžku i odrážedlo, dokud se nenaučí jezdit na kole jako Emča." (Amálce se zkrátka nechce a dělá scény). "A dělala naschvály a vztekala se. Přestala až pod pohrůžkou, že se nebude dnes dívat na Jurský park II. Jen jsem nechápala na co u jízdy na kole myslela, jelikož dotaz: MÁME VYČIŠTĚNÉ ZUBY? mě docela dostal..."');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(182, '2017-06-12 10:01:21', 'V té rychlosti života jsem si nestačil ani všimnout, ale když se zastavíte a pozorujete mravenčí hemžení naší rodiny, uvědomíte si, že všechno tu roste: \r\nRostou dvojčata. Je jim čtyři a půl, ale vypadají na šest. Každý se mě ptá, kdy už půjdou do školy, jedna babička jim dala mapu, aby jí holky ukázaly cestu. Babička je ještě na cestě k Severnímu moři. \r\nRoste nám zahrada. Pýcha Jáji. Až nám to tu zaroste celé, můžeme si nasadit nějaké ty dinosaury. Možná si nasadíme i přesličku. \r\nRoste nám nejmladší fenka Fergie. Už je větší než naše "bábrdle" Lea. Lea "roste" z Fergie. Fergie okusuje Leu, dvojčata i Jáju. Rostou z ní všichni. Mě nekouše. Asi proto, že jsem chlap. \r\nRoste nám stavení. Tedy aspoň části. Škoda, že se domky nestaví z Lega. Asi bychom měli už hrad. \r\nRostou mi vousy. To se líbí dvojčatům i Jáje. Konečně vypadám jak hlava rodiny. \r\nZ čeho rostete vy nebo vaše okolí?'),
(183, '2017-06-14 10:59:46', '"Kééééž slunce svítíííí, kéééž slunce svííítí náááám..." už delší dobu si myslím, že tu doma hrajeme muzikál Vlasy, tak jsem jen chtěl navodit atmosféru. \r\nJako jediný chlap v naší domácnosti nikdy nepochopím ty miliony vlasů (nebo zvířecích chlupů), které naleznete téměř všude. Lehnete si na pohovku a první, co vás na polštáři obejme, je několik vlasů, které tam jistojistě zapomněla jedna z dcer, když se dvojčata rvala a chytala se za vlasy. Taktéž je tento nešvar soustředěn v koupelně, v ložnici a i na chodbě. Dole k tomu přibývají ještě chlupy z fenek a kočky, takže když zametám, vypadá to u nás jako v kadeřnictví. K dokonalosti nám tu chybí ještě fousatý kaktus. Další lapálie s vlasy mne potkává, když chci dvojčatům udělat culíky, což začínají odmítat, že jim prý maminka udělá oblíbený cop, který ale já neumím. Neumím, protože ty triliony malých nepoddajných kroutících se šňůrek, které si dělají ve vašich rukách stejně co chtějí a nikdy (jako NIKDY!) nedokážete udržet v ruce všechny a vždycky (jako VŽDYCKY!) nějaký ten pramen vlasů uteče i přes ultimátum, že to jednou stejně všechno ostříhám dohola. Večer už zbývá jen Jáje přilehnout vlasy, kdy místo políbení na dobrou noc zaúpí ve tmě, že "tam mám vlasy." Zlatej Arnold a jeho účes na ježka.'),
(184, '2017-06-14 23:03:03', 'Blíží se doba dovolených, prázdnin, volna a mě tak nějak přepadla melancholická nálada. Takže teď to nebude o dvojčatech, ale spíše o mně a vzpomínkách a trochu i malé slze na krajíčku. Vzpomínáte si, jak jsme, jako malí caparti i větší ostřílení sígři jezdili na letní pionýrské tábory od zaměstnavatelů svých rodičů (kteří jim na to i přispívali)? Já si pamatuji na jeden tábor. Kromě absolvování jednoho turnusu v Orlických horách jsem jezdil docela pravidelně na (a to pozor, název si pamatuji doteď, a aby ne, když jsme ho předepisovali rodičům na koresponďáky) Pionýrský tábor ČKD ZV ROH Julia Fučíka do Dírné u Soběslavi. A prošel jsem vlastně všemi oddíly. Jak nejmenší od Zámečku až po nejstarší u Sluneční brány (která tam ještě cca v před rokem 2010 stála) a což byl také vlastně oficiální znak tábora (na tričkách třeba :)) \r\nCo bylo doménou, tak velký zpěvník - kdy se zpívalo u táboráku (bylo to i s kresbami). Pamatuji si jednu písničku - vždy jako budíček a dokonce ji jednou do ampliónů pustili v originále. Vedoucí pro mě v tu dobu byli bozi (údajně staří skauti), kteří si uměli hrát s dětmi. Celotáborová hra na (celkově 3x 21 dní, která opravdu končila posledním dnem. Osobně mám opravdu na tento tábor moc krásné vzpomínky a vyprávět by asi mohl dlouhé hodiny... je škoda, že to naše děti už takto nezažijí, a nejen toto. Tak aspoň, ať jsme my ti, kteří jim ty nejhezčí vzpomínky připraví.'),
(185, '2017-06-19 11:22:20', 'Už nám doma nestačí ani dva záchody. Na jednom trůní Amálka už docela dlouho, druhý jsem solidárně přenechal Emče se slovy:\r\n" Ale dělej, nejsi tu sama..."\r\nUsměje se:\r\n"Máme tu dva záchody přece..."'),
(186, '2017-06-19 11:23:33', 'Několik málo rad pro budoucí rodiče (hlavně pro muže, protože ti to ještě geneticky zakódované nemají a proto musí tvrdě trénovat) dvojčátek a vícerčátek (ČÁST III.):\r\nStále vás zpovídají? V práci, na procházce, tetičky, co přijedou z druhého konce republiky? Zkusíme jim odpovědět:\r\n1) Na vaší milované už je to zkrátka vidět a nepomůže jí ani převlek na maškarní á la Bud Spencer. Na procházce vás zastaví už pátý známý a s očima jako outloň se vyptává, zda čekáte přírůstek. Odpovíte: a) Ne, jen se ženou nacvičujeme přenos našeho malého skrovného bytečku (a pohladíte její bříško) b) V divadle mne požádali, zda bych jim nevyrobil horu Říp pro hru "Čech a Lech, kdo si zde leh" c) Rozcucháte si vlasy, začnete uskakovat a na útěku se ženou křičíte, že už tu skrýš na drogy stejně všichni odhalili.\r\n2) Potká vás starší paní (ty mršky se skrývají všude, těm se nevyhnete) a navazuje kontakt s vašimi dvojčaty, které už máte v kočárku, se slovy: "Jé, to je ale Boží nadělení!" Odpovíte:\r\na) Boží to je, nadělil nám to Ježíšek, heč! b) Paní, máme doma ještě Klapzubovu jedenáctku, sedm trpaslíků, sedm krkavců, a sedm statečných, tak ten páreček se tam už ztratí c) tyhle jsou na prodej, další máme doma, můžeme se dohodnout (a mrknete šibalsky na ní).\r\n3) Potkáte chytrolína každý rok na stejném místě: a) "Nebojte, první rok je vždycky nejtěžší..." Trochu se vám uleví, prohodíte pár slov, vyzvíte nejdůležitější, odcházíte. \r\nb) "Nebojte, až jim budou dva, všechno se zlomí..." Vy jen lomíte rukama prohrábnete zbytek vlasů. Ostatní vám stresem vypadaly. c) "Po třetím roce už to bude normální..." Normální ale nejste ani vy za ty tři roky. Zadrháváte, zapomínáte si věci, začíná vám být okolí ukradené. d) "Teď ve čtyřech už budou skoro samostatný, teď už se to zlomí, nebojte..." Vy chcete lámat dotyčného, trochu bojí vašich krvavých očí. e) Nikoho už jste v tento čas nepotkali.\r\n4) Tetička ze sto kilometrů vzdálené Lhoty přijela před porodem:\r\n"A zvládnete to?" a) Ne, mám už připravenou smrtící injekci a stříknu si ji po prvním zabrečením dvojčat b) Nezvládneme! Ty jediná jsi byla skvělá matka a tetička a odchovala našeho jediného bratrance! (a vrháte se jí do náruče se slzou na tváři) c) Chvíli mlčíte a pak jí nabídnete kafe z Koloniálu.\r\nTetička ze sto kilometrů vzdálené Lhoty přijela po porodu: "Ahoj, já jsem tetička, kolik ti je už let?\r\nVy: a) už jim budou tři b) Ukažte děti kolik je vám let c) dvojčata samy prozrazují svůj věk, berou klíčky od auta a odjíždějí do práce. \r\nP.S. Jak vždy s oblibou říkám: Když to zvládnu já (tak už každý ;-))'),
(187, '2017-06-20 07:59:58', 'Jdeme na tanečky a něco dáváme s dvojčaty do auta. Emča si své dveře zavře, Amálka je nechává otevřené a odchází. Jája na ni volá:\r\n"Amálko! A co dveře? To máte doma černochy?"\r\nAmálka se zamyslí a chvíli to vypadá, že neví, co odpovědět. Já si jen povzdechnu.\r\n"Černoch je tatínek."\r\nAmálka jen tak mimochodem hned na to odpoví: \r\n"ANO! TATÍNKA ČERNOCHA!" \r\nMá v tom jasno.'),
(188, '2017-06-22 22:05:27', 'Amálka je něžné stvoření oproti Emče. Má ráda mořské panny, Barbie na všechny způsoby, Annu z Ledového království (Elzu má Emča, protože je taky blond) a ještě má ráda zvířátka. Amálka má ráda jak všechna živá zvířátka, tak i ta mnoho milionů let již nežijící (což je dobře, protože bychom už měli jinak na zahradě aspoň nějakého pra-pra ještěra s tak divným jménem, že bych si každý den na něm lámal jazyk). A tak, když jsem zahlédl další - nové - pokračování JURSKÉHO PARKU (ten starý, jen tak mimochodem, Amálka zhltla po dvě soboty v TV), nabývám dojmu, že i tento díl jí přiroste k srdci. Posuďte sami, ještěrka jako ještěrka, ne?'),
(189, '2017-06-25 20:02:04', 'Od rána slyším od plotu hrající si naše holky se sousedovic klukem (jeden ze dvou, kteří jsou v dohledu našeho radaru).\r\n"Jsi tam, miláčku?"\r\n"Jsem, miláčku..." \r\n"To je dobře, miláčku!"\r\nDnes máme přemiláčkováno.'),
(190, '2017-06-26 14:49:56', 'Po dlouhé době se holky dívají na Ledové království. Elza zrovna zpívá a Emča se na mě otočí:\r\n"A tati, čistí si Elza zuby...?\r\nCo jako na tohle máte odpovědět.'),
(191, '2017-06-27 16:10:12', 'Jája přijela domů a Amálka ji skáče kolem krku, že se bojí. Tak se šla podívat, na co Emča kouká na TV. A já už jsem slyším Jáji hlas:\r\n"Emí, nemůžeš se dívat na něco jiného, než na pořad o ALERGICKÝCH REAKCÍCH?"'),
(192, '2017-06-29 09:52:00', 'Zjistil jsem, že naše děti perlí ještě více, když jim nejsem nablízku. Včera jsme byli na jedné odpolední akci a ujala se jich hned od začátku i teta Míla. Později jsem se od mí dozvěděl jejich první slova. \r\nEmča: "... Já jsem Emča, nemám ráda tetu Bimbulu (byly zrovna mraky a bouřka) a nejím nezdravé věci..."\r\nAmálka: (dlouhá přednáška o dinosaurech) a velký zájem o možnost chodit do školy jen odpoledne.'),
(193, '2017-07-08 21:06:59', 'Tento příspěvek bude s prosbou o radu: Emča se zvědavě uz několik večerů ptá na to, jak se rodí děti a také hlavně JAK VZNIKAJÍ. Dovedu to mistrně zakamuflovat, je to dobrá pohádka na dobrou noc a zkrátím to tu: dívce se dostane od chlapce semínka do bříška, kde má vajíčko a z toho je pak miminko. JENŽE: To Emče nestačí a chodí za námi, jak se tam to semínko dostane. Co byste řekli vy??'),
(194, '2017-07-08 21:07:20', 'Dobrou noc přejí DVOJČATA a JÁJA. P.S. Zmocnily jsme se tatínkova telefonu :)))'),
(195, '2017-07-08 21:09:33', 'Jít dnes nakupovat, když máte od rána dvojčata naladěná na brutálně hašteřivou vlnu, nebyl asi nejlepší nápad. Ale stalo se. Procházíme obchody a nevím, co mne to napadlo, že jsem se podíval do obchodu s výbornými pánskými obleky a doplňky. Já to ale fakt potřeboval. Tu vestu. Do práce. A zrovna slevy. Připadal jsem si jak Američan ve výprodeji wallmartu. A tak si tam zkouším kalhoty (jasně, slevy) a naše dvojčata jsou se mnou v kabince, která by mohla být klidně můj malý pokojíček, protože je obložený tmavým dřevem a je tam i pohodlná kožená židle. A všude dokola zrcadla (ty bych ale ve svém pokoji nechtěl). A jak se ty malé holky nakýblovaly za mnou do té kabinky, zazní v tu chvíli věta, která dostává celý krámek, protože se dvojčata vzhlíží v zrcadlech a jelikož je každé z dvojčat vidět v odrazech několikrát:\r\n"Ty jo, je nás tady hodně, bude PÁRTY!!!" začala Emča tleskat a i s Amálkou tančit a zpívat.'),
(196, '2017-07-08 21:09:51', 'To, že bydlíme nad skorozačátkem přistávací zóny letiště, mi nevadí. Aspoň sem tam uvidím nějaký ten vzdušný mikrobus. Ale dnes nám nad hlavou proletěl proklatě blízko zemi jeden z nich, ze jsem málem zahlédl pilota, jak odpojí svoje dvanácté kafe.\r\n"Holky, rychle se podívejte na to letadlo!"\r\nAmálka se zaujetím vyslovuje přání:\r\n"Jeee, tatínku, takové letadlo chci...."\r\nOk, jdu šetřit. Třeba nějaký boeing bude na bazaru.'),
(197, '2017-07-12 23:17:05', 'Blíží se teď bouřka a jsem s dvojčaty na zahradě.\r\n"Holky, domů, bude buřina!"\r\n"Ještě chvíli," hlásí Emča s velkou lopatou. "Dělám past na čerty a musí být hotová.."\r\n"Já ještě dělám bláto," doplňuje Amálka. "Čerti na něj šlápnou a ušpiní si nohy." \r\nZa pět minut začalo pršet.'),
(198, '2017-07-19 00:11:36', 'V myšlenkách jsem s vámi, milí dovolenkáři. Já jím bohužel nejsem. Jsme s Jájou s dvojčaty opravdu 24 hodin denně a jen jednou za sto let přichází dobrá paní z Bílé hůry, která si je vezme na víkend, kdy mám stejně hraní nebo jinou práci, takže nebudu od 8:00 do 20:00 rozvalený na lehátku a nebudu popíjet oblíbené pití možná s alkoholním přívlastkem. A tak se po prázdninách a dovolených potkáme v pavilónu C v druhém oddělení II. poschodí psychiatrické léčebny. Já budu mít tiky z dvojčat. U vás hrozí zhroucení z přeplněných kaváren a bazénů, potažmo, že jste dovolenou strávili v kolonách ke svému oblíbenému letovisku. Ať žije slunce.'),
(199, '2017-07-19 00:13:10', 'Mám dvě minuty na napsání tohoto statusu: Když u mne nejsou dvojčata, vetřou se na procházku k mým dvou nohám naše dvě fenky. Doma nám zatím vraždí myši naše dvě kočky. Tedy kočka a malý kocourek (jo, moment, o tom jsem se ještě nezmínil, to je novum, je také z útulku a je hlavně pro naše dvojčata, protože k nim kocka nejde a ony kočky rády). Tak, dvě minuty jsou za mnou a mám poslední dvě procenta baterie u telefonu. Tak krásné pondělí. Zítra bude druhý den v týdnu :)'),
(200, '2017-07-21 16:18:13', 'Pojďme starému taťkovi dvojčat udělat radost, i když nemá narozeniny (i když, když se ráno vstane z postele, je už důvod oslavovat, ne, že ne). Pokud se Vám stránka líbí a ještě jí nemáte mezi svými oblíbenými lajky, šup, klikněte mu ;-) A když už jste v tom, co takhle jedno sdílení celé stránky Dvojčat na útěku, aby se o tomto počinu jednoho (dalšího) superhrdiny kočírující celou domácnost dozvědělo další osazenstvo FB ;-) A když už, tak napište i nějakou tu zprávičku třeba do soukromých zpráv (povzbudit, to vždy potěší :D). Krásné slunné lenošení!!! P.S. Pokud jsem Vám ještě nepoděkoval - tak poděkuju :)'),
(201, '2017-07-21 16:18:30', 'No nene, fakt nám dvojčata odjela na tento slunný a horký prázdninový víkend k tetě (teto, diiiiky :)). Holky si za mého dozoru balí svršky, když v tom přiběhne Emča.\r\n"Tati, tati, ještě si musím zabalit tu čepici a šálu..."\r\nDívám se na ni dost nechápavě a pátrám v paměti, zda jsme na něco nezapomněli.\r\n"No pro jistotu. Kdyby začalo sněžit..." řekla zcela vážně.'),
(202, '2017-07-24 12:00:39', 'Moje žena Jája je taková dobrá duše, milovnice všeho živého a hlavně opuštěného. Kdyby u nás žili smutní klokani bez domova nebo by se objevil Yetti, že se ztratil a nemá kde spát, určitě by ho vzala také domů. A tak jsme se po poradě vydali do útulku pro opuštěné kotě. Jednu kočku z útulku už máme a protože dvojčata byla smutná, že k nim moc nechodí, chtěly také mazla pro sebe (fakticky k nim chodí - je to ZÁÁÁZRAK). V útulku je více než sto koček, o které se ZCELA SAMA stará paní Edita a milionově je všechny miluje, mazlí a piplá je, aby se nazpět pak kočky dostaly k dobrým lidem. Ty kočky by si to zasloužily. Je to útulek Tlapky Mochov. \r\nA tak mne napadá (protože na rovinu, i my doma rádi každý měsíc na tyto kočičky přispějeme, protože je to fakt rasovina se o tolik koček starat, co někteří lidé jen tak nechají ladem skladem), že pokud by tu byl jen jediný člověk, co by rád tomuto útulku přispěl buď konzervou nebo i padesátkou, stovkou, dvoustovkou, vlastnoručně Vám pak nakreslím diplom, který Vám tuto srdcovku bude připomínat. \r\nP.S. No, a já si jedu pro svého kocoura, který mne bude inspirovat ve psaní. Taky se tak jmenuje: Fejeton :D\r\nP.P.S. Dole fotka našeho (konečně další chlap v rodině) mláďátka - BEDŘICH'),
(203, '2017-07-25 15:07:52', 'Jedeme autem a aby řeč nestála, tak už v raném věku začínám dvojčata zpovídat:\r\n"Amálko, čím bys chtěla být, až budeš velká...?" začnu v očekávání, že třeba modelka nebo nějakou podobnou, rodinu živící činnost.\r\n"Já bych chtěla být MOŘSKÁ PANNA..."\r\nNu, dobrá, jdu už shánět akvárko.'),
(204, '2017-08-02 11:57:19', 'Znáte to. Takový ten zlobivý víkend, dvojčata neposlouchají, peklo se neustále otvírá, hlasivky slábnou. Rozdávám holkám pár trestných minut a musí zpytovat svědomí u sebe v pokojíku. Po pár minutách slyším hlasy:\r\n"Emčo, pojď, už nebudeme zlobit," nabádá Amálka ségru ke zpětné družbě s rodiči. "Když ja totiž zapomínám být hodná..."'),
(205, '2017-08-04 10:22:03', 'Pššššt, pojďte blíž k obrazovce, abych moc nekřičel. Budu hodně šeptat. Dnes jsme SAMI s Jájou doma. Dvojčata jsou PRYČ u tety (Buď teta Jíťa nebo teta Martina nám dopřávají sem tam druhé Vánoce ;-)) Je tu klid, ticho, uklizeno, au, kostka. Tak, teď je uklizeno.'),
(206, '2017-08-10 11:55:59', 'Výročí naší svatby a nezbytná návštěva lázeňského města, kde jsme si řekli "ano". Zkrátka trochu nostalgické romantiky musí rozčeřit prázdninové vody této stránky. Při výletu parníkem jsem dvojčatům musel stejně vysvětlovat, proč si nemohou hladit kachny na řece, proč nejsou vidět ryby, nebo proč v těchto vodách nenajdou žraloky a delfíny...'),
(207, '2017-08-10 11:56:13', 'Kdo nestihl navštívit Park Mirakulum, tak ať si ho prohlédne již jen na fotografiích, protože tam právě s naší demoliční miničetou odjíždíme.\r\n"Ne, Emi, tu velikou klouzačku si domů odvézt nemůžeme..."'),
(208, '2017-08-10 11:56:24', 'Stal jsem se nejtišším členem domácnosti hned vedle velmi tichých dveří, které jsou stejně stále otevřené. Z mých hlasivek se stal tichý kráter a vychází z nich jen slabé volání o pomoc. Takže vám sem budu jen psát :D To ještě zvládnu. Horší je, že dvojčata ještě neumí číst a tak nemohu komunikovat pomocí papírků...'),
(209, '2017-08-11 13:58:36', 'Trochu mám podezření, že Velká Dobrodružství, respektive akční Lucie á la Deník fejsbukové matky zase operuje někde v mém zenitu bydliště, protože takové ukázkové deštivo už jsem dlouho neviděl. A tak si tu pouštím nostalgickou píseň  "Mží ti do vlasů" a dvojčata už podruhé shlédla "Hledá se Dory." A tak jsem ke všemu ještě vytřel a aby té vody nebylo málo, našel jsem v rohu u veliké květeny rozlitou konvičku vody od koček, co se tam neustále perou. Raději si pustíme další nostalgii typu "Slunce, seno, jahody." A počkám, až ze mě bude DĚDEČEK. Prý to bude již dnes, v pátek :)'),
(210, '2017-08-15 23:36:11', 'V posteli jsem si lehnul na mořskou pannu. V chlebníku mi nešly otevřít dvířka a tak jsem vyndával fialového poníka, tyranosaura a malé autíčko. Na chodbě spí kocour v lehátku pro panenky. V koupelně je vana v obklíčení zvířátek ze safari a v kuchyni jsem vyndával z myčky dětské nádobí. KDE JE TEDY TEN MŮJ PROSTOR??'),
(211, '2017-08-15 23:36:32', 'Dnes ještě poslední: jdeme s dvojčaty na dětské hřiště a holky jedou na kole. Tedy Emča jede, Amálka se spíš veze, tedy já ji vezu. Ona jen dělá, že šlape do pedálů. Už jsem z ni trochu pocuchaný v nervové soustavě, když tu praví:\r\n"Tatínku, já teď moc neumím, ale až vyrostu, koupím si velké kolo..."\r\n"Hm," svitla mi naděje, která pak hned zhasla.\r\n"...ale já na tom kole nepojedu, já půjdu vedle něho pěšky..."'),
(212, '2017-08-21 12:55:28', 'Připadám si jak Charon, akorát převádím čůrající z krámu na záchod. V nákupním středisku. Nejdříve chce jedna. Pak bohužel druhá. Ještě, že těch dětí nemáme víc. Dobrých 300 metrů chvátáme, aby za námi nebyla mokrá čára. Nevím, jak by se na mě ta ochranka u WC dívala po pátém dítěti...'),
(213, '2017-08-21 12:55:46', 'Rozbiju se na schodech, když chci vyjít nahoru. Za mnou jde Emča a na moje slušné klení nezištně chlácholí.\r\n"Tatínku a nebolelo to? Ani nebrečíš. Jsi silný!"'),
(214, '2017-08-24 00:37:11', '"Jen Já a Ty, to je bláhové..." pobrukoval jsem si dnes, když jsem měl rande s Jájou jako milenci bez texasek, za to natěšeni na odpolední kino, které slibovalo jednu z nynějších třešniček pozdního filmového léta. Ano, již snad i foto napoví. Zašli jsme na Svěráka, který nás sevřel již v knižní podobě a jeho syn se chystal sevřít podruhé, okázale na stříbrném plátně. PO STRNIŠTI BOS. Nebojte, nebudu psát žádné recenze. To nechám na vás. Za mne jsou to postřehy a matné vzpomínky na klukovské žití mezi dospěláky i jinými kluky. Tak stejné, jako naše vzpomínky na šestý rok našeho života. A i když je to jiné než Obecná škola nebo Vratné láhve, má to své kouzlo a ční to nad jinými českými filmy tohoto roku. A je to dobře.\r\nJako malý jsem si představoval, jaké to bude, až budu velký. Nyní si představuji, co jsem dělal a říkal jako malý. Jaký svět jsem viděl dětskýma očima. Zatraceně moc závidím panu Svěrákovi, že si ty dětské oči nechal až doposud. A jak řekla nejednou Jája: "Kdo tu bude psát a točit takovéto filmy, když jednou pán Svěráci (respektive pan Zdeněk) nebude...?"\r\nTak se chopím pera a začnu sbírat vzpomínky já. Jája o to ještě neví :D , ale třeba jí to potěší a některé z vás také. P.S. Běžte do kina a klidně si kupte i to dvousedadlo pro milence, jako jsme měli my. Je opravdu pohodlné'),
(215, '2017-08-25 12:14:30', 'Rodiče rádi čtou takové ty narážky na třídění dětí a recyklují si je podle toho, jak kdo napíše jak se chovají na pískovišti nebo v krámě. Ale co přímo rodiče? A protože podle blogerského desatera si mají všichni blogeři pomáhat, i já vytáhnu do boje s rodičovskou všedností a na přání si rozčleníme stav chování rodičů na českých pískovištích: \r\nVetřelec - je to z 90% tatínek, který přišel s dítětem na poledne a tím pádem pozdě. Všechna stanoviště svišťů jsou již obsazena, kupodivu tam nikoho nezná, protože si s jejich dítětem chodí hrát maminka nebo babička, ale žena je nemocná, takže i dítě je oblečeno a učesáno jinak. Tento tatínek zůstává stát ještě zmaten gentlemanstvím v tramvaji a jediný oční kontakt je na jeho dítě, protože se stydí v této společnosti za oba. \r\nMatador - maminka nebo rodiče, kteří nemají svůj vlastní dvorek nebo balkon a každý den ve stejnou dobu vyráží zpestřit dětem hrací čtyř hodinku. O nic se nestarají, vše na hřišti je. Mají svoje svačiny i pití, protože se dalších 240 minut nikam nepohrnou, leda by chtělo jejich dítě čůrat, ale za plotem je dovoleno všechno. \r\nPovídal - tento rodič nejen pozdraví, ale aby se vetřel do přízně aspoň dalších třech rodičů, rozvine další větu o útoku mimozemšťanů na pískovišti. Pokud se někdo zasměje, má napůl vyhráno. Dotyčný Smíšek prohrál svou samotu a už se Povídala nezbaví, leda by rychle odešel na jiné hřiště, kde se může rychle stát Vetřelcem. \r\nKočárek gang - je typ několika rodičů, kteří operují koordinovaně a vše mají vyladěno k dokonalosti, i svolávání se na cestu na pískoviště. Ti zaujmou dlouhodobě výhodné postavení u pískoviště a než jejich děti postaví první sypkou bábovičku, stačí probrat vše od písmene A do N. \r\nPoučovatel zmatkař - ten nenechá své dítě ničeho si hrát do konce. Neustále mu radí, poučuje, napomíná i jiné děti, ale běda, pokud se mu tam hrajících si prcků sejde více. Neví, kam šlápnout a zmaten se rozhlíží po všech typech rodičů, kteří ho úspěšně ignorují, protože tohle mají s dětmi doma a na pískoviště si šli odpočinout. \r\nBiorodič - přišel bos. Ve vytahané košili a všechny prcky vyhazuje ze svého šátkového dopravníku přímo do pískoviště s nařízením, že musí ochutnat matičku zemi. Vytáhne podomácku vypěstované jablko a posadí se do trávy, i když neví, co v ní je. Z meditace ho neprobudí ani ticho, kdy už všichni odešli. Jen jeho děti stále zírají na písek, protože v něm vidí miliony barev. \r\nA konečně tu máme posledního rodiče - Landsman: Nastrčí svoje dítě doprostřed a sám se schovává za prvním stromkem nebo trsem trávy, mapuje terén a ostatní prcky a porovnává, zda ten jeho človíček nějak nevybočuje ze standardu. Odchází tak brzy, aby stačil do uzávěrky napsat článek.'),
(216, '2017-08-31 12:20:43', 'Tak se vracím na prkna, co znamenají svět. A se mnou i naše holky. Vypisuji kurz 1:0,1 zda rozloží nebo nerozloží představení. Po včerejším výstupu, kdy zjistily, že budou se mnou na divadle si myslím, že chudák rejža...'),
(217, '2017-09-01 12:56:52', 'Jsme právě na veterině. Nechápu doktora, že nechce Emče nic píchnout na uklidnění, Amálka si potykala se sestřičkou a vypráví ji zážitky z prázdnin. Je to takový normální den.'),
(218, '2017-09-04 09:29:06', 'Šli jsme na procházku. Sluníčko vylezlo z mraků a doufám, že ne naposledy nám zašimralo na nose, až Amálka trochu pšíkla. Znáte to. Takový krásný příjemný pondělní den. Chvíli jsme sledovali dálnici mravenců, jak si nesou listí a drobky rohlíků do škvír v chodníku a mne oslizla první letící pavučina babího léta. Pak jsme je potkali. Ty davy, co se někam řítily. \r\n"Tatínku, kam ty děti pospíchají?" rozzářily se oči Emče, že je tam možná výprodej hraček.\r\n"Dnes už jdou děti zase do školy...." nevím proč, ale měl jsem úsměv na rtu. Asi jsem si sadisticky představoval, jak už chvátají do lavic i naše dvojčata. TAK HEZKÝ PRVNÍ ŠKOLNÍ DEN!'),
(219, '2017-09-07 17:01:52', 'Prodám jednu mořskou pannu. Vhodná i jako vánoční kapr nebo dobrá do privátního jezírka na vlastním pozemku. Hodně povídá, ještě více zpívá. Už od rána mi tu jedna skáče na souši a nechce se převléci...'),
(220, '2017-09-12 00:01:27', 'No dobře. Vydala se knížka Dvojčata na útěku. Emča a Amálka si do těch svých výtisků prý chce kreslit. Až se naučí číst, budou hořce litovat.'),
(221, '2017-09-12 15:23:35', 'Přijel strejda Honza, aby si nechal podepsat knížku. Vybalil si ji dokonce z obalu. Beru tužku a volám na dvojčata, která jsou nahoře.\r\n"Holky, pojďte dolů, strejda si chce od vás nechat podepsat knížku!"\r\n"MY SE BOJÍMEEEE!" sborově odpovídají.\r\n"Holky, pojďte se mi podepsat, prosím..." snaží se být Honza hrozně hodný v hlase.\r\n"MYYYYY NECHCEMEEEE!"\r\nHonza se láme na židli a já... já to sem hned prostě píšu.'),
(222, '2017-09-14 22:30:59', 'Aspoň že vím, co se holkám zdá. Právě se z pokojíku Emči ozvalo:\r\n"Běž Rexi! Utíkej!" pak se zachichotala a dodala. "Ty jo, on nás zachránil..."\r\nSlibuju, že už jim ten Jurský park nebudu pouštět.'),
(223, '2017-09-16 20:11:40', 'Fejeton je jeden z našich kocourů. Loví myši. Dvojčata loví naše kocoury a vše ostatní živé v okruhu kilometru od našeho domu. Někteří brouci už dělají předem, že jsou mrtví, aby je holky nesebraly. Dnes si naše dítka hrála venku na dvorku. Jáje už bylo divné, co to tam schovávají, ale Emča jako špión zcela selhala a už svým chování nekalost věci prozradila. Když Jája došla na místo činu, zhrozila se. V kelímku živořila malá myš. \r\n"Kdes ji vzala?!" rázně se Jája zeptala.\r\n"FEJETON MI JI DAL..." odpověděla Emča. \r\nZcela odzbrojená moje žena s dvojčaty následně dává volnost nebohému Jerrymu.'),
(224, '2017-09-19 11:40:43', 'Mě jen tak něco nerozhází, ale u následné akce Emči si připadám jak špatně rozsypaný koš na Hlavním nádraží. . Je to sice prý velké tajemství, ale protože to vypráví všem na potkání, je to spíš veřejné informování. A už mě, i se samopalem v ruce, donutila napsat monstrózní dopis, který mi diktovala asi pět minut a při tom pochodovala po pokoji jako pan Svátek, diktující pracovník odbytu ve filmu Marečku, podejte mi pero, ve kterém se ke všemu vyznala. Ano, je zamilovaná. Rozplývá se nad mladým pracantem, který pomáhá stavět náš velkolepý zahradní domek, všude prohlašuje, že si ho vezme, až bude velká a budou spolu navěky. \r\nNaposledy se mi tady svalila ve vývrtce na gauč s rukou na čele s větou:\r\n"Já se picnu, on je TAK KRÁÁÁÁSNÝÝÝ!" \r\nMaminko, na jaké filmy že to koukáte, když nejsem doma? '),
(225, '2017-09-19 23:51:22', 'Sedím si u stolu a nadepisuji obálky s knížkami, abych je mohl poslat a neustále mne vyrušuje kocour, který si s něčím hraje pod pohovkou. Ale já se nedám! Nenechám se vyrušit. Stejně to chvilku trvalo a najednou na mne vykoukne cosi, co připomíná - OBAL OD ČOKOLÁDY! Vyvalím oči, že by se za mě nemuselo styděl ani stádo outloňů. COŽE? Začíná ve mě rašit zárodek Sherlocka Holmese a vše do sebe zapadá! \r\n- Tak proto už dva dny Emča leze pod pohovku, jako že tam hledá panenku - a já myslel, že tam honí kocoura.\r\n- Tak proto z vrchní skříně kuchyňské linky zmizelo pár tabulek čokolád - a já myslel, že se vyhodily, nebo se z nich něco upeklo.\r\n- Tak proto!!! Pro to všechno!\r\nP.S. Kolik let navíc je 15 minut nepřetržitého smíchu??'),
(226, '2017-09-24 22:32:29', 'Při dnešní návštěvě tety Jíťi se strejdou Fandou se zase (jako vždy) dvojčata odvázala. \r\n"Ty jsi ale ještěrka..." pobaveně říká Amálce teta a Amálka hned posouvá nová oslovení na ségru Emču.\r\n"A Ema je OPICE KULATÁ..."'),
(227, '2017-10-02 11:50:34', 'Někdy být humorný nejde, protože třeba právě přijde nějaká ta nostalgická nálada. \r\nTuhle jsme byli s dvojčaty na cvičení, kde se aspoň tři čtvrtě hodiny trápí s nimi někdo jiný a tak má rodič čas na toho druhého a i to kafe chutná tak nějak líp a hlavně se pije pomaleji. Ale posuďte sami, že z obrázku je cítit to (obrázek je na FB blogu Dvojčata na útěku), co tu celý čas vlastně píšu. To, že ty moje holky jsou stále na útěku, neustále krok přede mnou a pořád se v tom zdokonalují. Emča si vzala oba báglíky, protože Amálka nesla za ruku Jáju a tak jsem okem bedlivým sledoval své energické dítě, jak šoupe nožičkama s plnýma rukama a ani se neohlídne. Víc už ani netřeba psát...'),
(228, '2017-10-02 11:50:56', 'Dítě ve čtyřech a půl letech:\r\n1) je hovorné\r\n2) má velkou představivost\r\n3) je vybíravé v jídle\r\n4) je náruživé v kreslení\r\n5) je znalé více jak 1500 slov\r\n6) je těžké přibližně 18 kg\r\n7) má večerní rituály\r\nnaše dvojčata ve čtyřech a půl letech:\r\n1) jsou upovídaná jak Palacký a naslibují i to, co neexistuje\r\n2) mají takovou představivost, že by se ty postavy nevešly ani do Kálovství pohádek nebo do Pohádkové fantazie v Nekonečném příběhu\r\n3) sní i mámu, tátu a vozku se žebřiňákem a kravkou\r\n4) mají všude rozházené papíry jako páni inženýři při rýsování a bojím se i usnout, abych neměl na své kůži vytetované sluníčko\r\n5) chodí se sborníkem cizích slov, protože naprosto odmítám vysvětlovat, co je to PERCEPCE (té totiž mají hodně celý den)\r\n6) když na mne hupnou, podlomí se celý můj člověk, zapraskají nejslabší kosti v těle a na daném místě se mi udělá velká modřina, jako by mne kopla kovářova kobyla\r\n7) rituálně celý den zlobí a já je rituálně neustále zaříkávám, i když mám dojem, že mi tem woo-doo šaman dal jiný papírek, neboť to vůbec nefunguje. Rituální večery se skládají z nahánění do koupelny, pak vyhánění z naší postele do jejich postele a nakonec jim rituálně slibuji nejhorší zážitky dalšího dne, pokud rituálně do pěti vteřin neusnou.'),
(229, '2017-10-02 11:51:21', 'Nebudeme trhat řetěz a přijmeme celorepublikovou výzvu sbírání hub do tuctu košíků. Vyrazili jsme na několika kilometrovou jízdu hledat les v České republice. Kus Řáholce jsme po pár hodinách hledání mezi džunglí překladových hal konečně našli a mohli jsme začít hledat pochoutky do maminčiny bramboračky. Trochu mě znervózněla Amálka, která se po vystoupení z auta dožadovala odpovědi, proč zrovna jdeme do lesa, když žampiony nadívané se pěstují výhradně ve zřícenině hradu. Vše ale bylo odpuštěno po první houbě, nad kterou Jája tančila oslavný tanec irských stepařů. Vzít dvojčata na hledání hub se nakonec ukázalo jako trumf, protože jako malé lépe nahlédnou pod listy ostružin, ale o to hůř se jim je dařilo překračovat. Konečná bilance je následující: Líbila se mi houba na obrázku, ale jediné, co mi bylo dovoleno, že jsem si ji mohl vyfotit, jinak v košíku uvázlo asi 20 jedlých hub a 4 golfové míčky. P.S. Jájina bramboračka z 20 hub zavřela pusu i dvojčatům. Tak vám všem taky přeji dobrou chuť.'),
(230, '2017-10-04 22:49:18', 'Ráno, než šla Jája do práce, zazněl výkřik z koupelny. Po vzoru vojenského poplachu jsem během tří vteřin stál na místě činu a kolem dokola obmotával policejní páskou kriminální zločin. \r\n"Zjisti pak od nich, kam mi daly tužku na oči. Nemůžu si namalovat oči..." zněl rozkaz jasně. Z chlapského myšlení mi vyplynula otázka, jak může žena vidět, když si NENAMALUJE oči? Při pohledu na Jáju jsem však viděl jedny totálně pronikavě upřené na mně, takže tím padla varianta, že bych jí fixou nějaké krásné, velké, nakreslil. \r\nOdpoledne vyslýchám ve zvukotěsné kabině každé dvojče zvlášť, aby se na mne nedomluvily. Jsou to kriminálnice a padouši a já musím být ostražitý každou vteřinou. Stačilo však pohrozit chůvou McPhee (ta s tou velkou bradavicí na obličeji a jedním vylezlým zubem ze rtů) a už pomalu začaly zpívat. \r\n"Holky, kam jste daly tu maminky tužku na malování očí? Byla v koupelně..." vysvětluji útržky identifikace předmětu a okolí, ale nevím proč, nejprve mi vyskakuje později správně označená řasenka. \r\n"Tužka! Černá! Maminky!" tápu taky, jak tuto věc, kterou jsem snad nikdy nepoužil, vykreslit někomu, kdo ji ještě zcela nikdy nepoužil také. \r\n"Já to nebyla! To byla Amálka!" vzpomíná na čin Emča a mě svitne naděje.\r\n"Asi jsem to byla já..." uculuje se Amálka a přemýšlí, kam jí asi mohla dát. Za chvíli mi přinese černou tužku. Tu od pastelek. \r\n"Ne, no tak, holky! Tahle byla v koupelně u zrcadla!" pomáhám si jim vzpomenout a začíná se mi vařit každá nervová cévka v těle. Procházíme možná místa výskytu tužky. Nic. A místo úklidu každou hračku ještě pěkně pomazlí, abych měl vztek ještě větší. Takhle se nikam nehneme. A čas utíká. \r\n"Tak AMÁLKO!!!! KDE - JE - TA - TUŽKA!!??" začínám hrát zlého policajta. \r\n"Tužka? Jaká?" podívá se na mě nevinně Amálka a u nás už raději zvoní pánové v bílých pláštích a svěrací kazajkou, kteří se ptají po mém jméně.'),
(231, '2017-10-12 09:52:16', 'Emča mi ráno strčila až k uchu dětský ovladač, který nejen říká česky číslice, ale hraje příšerně otravnou melodii. A dvojčata, po vzoru DJů z Papay, tu melodii neuvěřitelně dlouho pouští neustále dokola, takže si ji v hlavě pak pouštíte jako kdysi Family Frost. A Emča činí prohlášení, zatímco ta melodie mučí moje ucho:\r\n"Tohle ti, tatínku, bude hrát BRZO KAŽDÉ RÁNO do ucha!"\r\nFakt mě mají rády ty naše děti.'),
(232, '2017-10-16 13:12:34', 'Nejsem marný otec. Své děti hlídám, aby se jim nic na hřištích nestalo. A právě na jednom jsme. Vedle jedna postarší paní točí pomalu na hřišti svého vnuka a říká: \r\n"Toč se opatrně, aby se ti nic nestalo. Aby pak neřekli, že je babička nezodpovědná..."\r\nPřijde ke mě Emča a šeptem se ptá:\r\nTati, a proč má ta babička v ruce sklenku vína?"'),
(233, '2017-10-26 21:57:50', 'Ráno vstanete. Emča už prudí dobrou půlhodinu, že chce maminku do svého pokoje. Jasně, tatínek zas nemá nárok. Vzpurnost dítěte vygraduje, když jsme už oba dole a oblečené (po deseti minutách) a obuté (po dalších deseti minutách vyhrožování) dítě má očividně problém s ústní hygienou, která končí vzbuzením doposud chrnící Amalky. Ok, máme tu dva tajfuny, které cokoli udělat odmítají a naše vyhrožování (které by určitě dostalo kdejakého zločince) se u téhle havěti míjí účinkem. Ale což, máme celý den před sebou a tak jedeme támhle a zase jinam, zkrátka takove cestování, které by je mělo unavit. Divný, že nakonec v koutku pro děti v jednom obchodním centru naši svišti sviští světelnou rychlostí a já s Jájou pomalu usínáme na lavičce s kafem v ruce. Myslím, že pohled na nás vyvolal soucit nejméně třech matek vedle sedících.'),
(234, '2017-10-30 10:54:28', 'Venku je aprílový duben s červnem na Kamčatce, což je tak trochu evropský listopad. Když chtějí holky na dětské hřiště, nepotřebují ani kolotoč, protože je vír veprostřed pískoviště dokáže roztočit stejně rychle jako centrifuga a to nemluvím o skrytých loužích, kam by se schoval i vodník Česílko. Ale dvojčatům rozhodně nevadí. Amálka za mnou přijde s takovým leskem v oku (na tom druhým má okluzor na zlepšení zraku, aby nemusel nosit cvikr, až bude starší) a hrdě hlásí, že si udělala s hračkami domácí piknik. Nu což, pozvánky jsou rozdané a ještě se čeká na poslední dinosaury, aby mohla začít veliká párty. Prý mám dodat už jenom piškoty a kafe s brčkem.'),
(235, '2017-11-02 22:21:25', 'Je fajn, že i moje žena Jája přispívá do rodinné spokojenosti svou troškou humoru. Dnes si drandíme nazpět do domoviny z divadelní zkoušky, kde i naše holky hrají, takže je tatík (tedy já) spokojený, že trochu těch hereckých genů předal dál. Samozřejmě už je tma tmoucí a projíždíme lesem, kde je rovinka cirka na pět kilometrů a v tom se Jája ozve.\r\n"Hlavně jeď opatrně, abys nesrazil třeba nějakou - OVCI." \r\nBože, proč se nejde brutálně smát za volantem? Nuže, děkuji své ženě, že odteď vím, že v noci bača žene své ovečky (celé stádo) lesem před zlým vlkem a proto je radno jezdit opatrně těmito úseky a dbát zvýšené opatrnosti. I když - mohl aby tak končit i kdejaká pohádka.'),
(237, '2017-11-07 14:06:01', 'Týden tatínka dvojčat: \r\nDvojčata dosáhla čtyřleté mety tak rychle, že kdyby se tou rychlostí cestovalo, můžu jezdit pro banány do New Yorku. Mluví, myslí, vymýšlejí. \r\nPondělí: \r\nJe sedm. Jakási rozcuchaná hlava vykoukla k nám do ložnice. Pak druhá. Hurá, vstáváme. V kuchyni vyndávám z chlebníku růžového poníka. Směju se tomu. Je to tak od dětí milé. Při jídle trochu drobí. Nevadí, tak to pod nimi vyluxuji a vytřu. Ty naše dvojčata se tak krásně při hře smějí. Mám rád dětské hlásky. Oběd prý není podle jejich gusta, ale po půl hodině přesvědčování tu studenou krmi snědly. Přisuzuji to spíš konečnému dostavení hladu. Doposud po každém upozornění chtějí maminku. Chápu jejich odloučení, taky už si svou ženu přeji doma. Večer se jim nechce tak rychle spát, jak jsem si zprvu představoval. Nekonečno otázek s nekonečnem chtění na záchod. Poprvé jsem použil vyhrožování, ale ti malí teroristé to se smíchem přešly. V manželské posteli přemýšlíme, co by je navedlo na tu správnou cestu andílků v domácnosti. \r\nÚterý:\r\nDocela jsem se dobře vyspal. Je sedm a už se moc těším, co budeme s našimi dvojčaty dělat. Vykoukne jedna hlava do ložnice, druhá hlava i s trupem za velikého křiku přilítne na můj pupek. Trochu to bolí. V bezvědomí jsem byl jen pět minut, dobrý. Dvojčata zatím nic nerozbila ani neroztrhala. Obě sedí na mě. Setřesu je naháním je do koupelny. Vida. První ranní hra na honěnou. V kuchyni vyndávám z chlebníku růžového koníka až po čtyřech minutách. Zasekl se tam, mezek. Trochu mne to rozhodilo, ale hned, jak přijdou děti na jídlo, jsem hned klidný. Dvojčata kreslí a už jsem třikrát řešil malé přestupky v tahanici o tužky. Doufám, že se co nejdříve uklidní. Beru to s rezervou a nechám si je to vyříkat mezi sebou. Pak už jen řeším kousanec u jedné a škrábanec u druhé. Ale hezky kreslí. Při obědě jim zase půlka spadla na zem! Takhle se přeci jídlem neplýtvá. Ale zametu to. Už jsem je několikrát upozornil, že zlobení do naší rodiny nepatří. Chtějí maminku. Já chci klid. Odpoledne jsme na ně oba, ale stále si připadáme v oslabení. Jsou opravdu jen dvě? Večer jsem čtyřikrát navštívil pokojíčky dcer, ale už nemám sílu jim neustále vysvětlovat, že se má jít spát. Výhrůžka čertem nebyl dobrý nápad. V noci jsem k nim vstával asi pětkrát. Z toho hodinu u jedné z nich spal, protože se bála. \r\nStředa:\r\nJe sedm. Zjistil jsem to, protože na mě přistála jedna z dcer, druhá krouží kolem postele a něčemu se směje. Hned je posílám do koupelny a hrozně se mi chce spát. Nemůžu. V kuchyni doluju růžového koníka z chlebníku. Sakra. Jsou tam dva. Druhý je fialový. Trvá mi to asi deset minut. Jdeme ven, ale oblíkání a obouvání se nesetkalo s dobrou náladou dvojčat. Moje nálada s trpělivostí si už balí kufry. Dvojčata chtějí maminku, já chci, aby se oblíkly, jinak nám z dvouhodinové procházky zbyde cirka jen čtvrt hodiny. Nikdo nechce ustoupit ze svých požadavků. Začíná vyhrožování čertem už v poledne. S obědem si na mne nepřijdou. Je takové jídlo, které jim chutná a měly by ho sníst hned a nic nevyhazovat z talíře na sebe nebo podlahu. Bože! Je tam zase nastláno! Nutím je si to po sobě uklidit. Chtějí maminku. Ptám se, jestli spíš nechtějí čerta. Odpoledne jedeme spolu všichni nakoupit. Dvojčecí slib poslouchat a být hodný se vytratil hned po výstupu z auta. Obchody jsou totiž jedna velká prolézačka a honit se mezi regály je ta pravá adrenalinová zábava. Jako by tušily, že se nám příčí zvednout hlas mezi lidmi. Skupinka Japonců si po půlhodině zvědavě fotí rituál rodičovské výchovy minulého století s finálním naplácáním na zadek za mohutného křiku malých teroristů. Doma se situace vyostřuje jak v námořní bitvě. Zvednul jsem několikrát hlas. Za to mi moje hlasivky nepoděkují. Mám podezření, že dvojčata v obchodě sebrala špunty do uší. Musím koupit amplion. Večer vytíráme se ženou potopu v koupelně a já už jsem přešel na modlení, aby obě naše děti usnuly rychle. Po šestém pokusu se buď napít nebo vyčůrat přemýšlím o rozbití záchodu i všech umyvadel, aby se na něco konečně mohl vymluvit. Strašit čertem je nebudu, chci se vyspat. Ok, čert přichází za dvě minuty. Emča ho chce i ukázat. V noci jsem byl jen jednou vzhůru. Měl jsem strašidelné sny. \r\nČtvrtek: \r\nRáno. Ještě to tu spí. V klidu si dojdu na WC. Omyl. Jsem přepaden i tam. Počítám, kolik mi tenhle den odumře nervů. Z chlebníku se už toho odporně růžového koně ani nepokouším vyndat, jinak bych musel chlebník rozbít. Chci tu ženu. Aspoň na půl hodiny. Ta havěť tu jen ječí a piští, smích je jak skřípání nehty o tabuli. Oběd bych zrušil. Vůbec si ho nezaslouží. Stejně půlku studeného jídla zas vyhází na zem, ale už mám donucovací prostředky. Chtějí maminku. Když maminka přijde, pro změnu chtějí tatínka. Já zrovna nechci je. Aspoň to studené kafe v pěti minutách klidu si můžu vypít. Poslední hodiny do spaní zaznamenávám všude, kde jsme jen pištění, vřískání a sliby, že už budou hodné. Ano, hodné jsou, když spí. \r\nPátek:\r\nJe krátce pošesté a já má pocit, že přibývajícími dny jim energie spíše roste. Einstein by měl radost. Já radost nemám. Jediné, co mám, jsou červené oči a dost pochroumané nervy. Růžový poník, fialový poník, mořská panna a ovladač od televize, které jsou v chlebníku, letí rovnou do popelnice, protože tohle už teda fakt neotevřu. Kreslení je super, ale jediná velká tečka jedné z umělkyň na padesáti čistých papírech je i na můj vkus hodně. Oběd sem psát nebudu, musel bych se vypípat. Dochází mi argumenty, vzpomínám si na protiteroristickou příručku. Je taky k ničemu. Večer vyndávám z pračky další koně. Sakra, kde je zase vzaly? Pohádka je jen o hrnečku, co vařil. V posteli usínáme se ženou po první reklamě. Přes víkend zkrátka tu sílu zase musíme nabrat.'),
(238, '2017-11-14 16:54:04', 'Teď to nebude žádná legrace. To je naprosto vážná a seriózní věc. \r\nPOJĎME ZMĚNIT HISTORII! \r\nFandové a Fandovky nebo Fandovčata. Nebo zkrátka jen ti, kdo máte rádi můj decentní humor, nebo jste si jen oblíbili tyto stránky či osobně moje dvojčata znáte. Máte znovu možnost hlasovat pro DVOJČATA NA ÚTĚKU v Blogeru roku 2017.\r\nZde je odkaz a pak už jen stačí Váš hlas:\r\nhttp://www.czechblogawards.cz/finale/dvojcata-na-uteku\r\nDokonce vyhrát můžete i vy, protože se hlasy losují a je možnost přivýdělku 5.000,- před Vánoci ;-) \r\nP.S. A moc děkuji, že tento blog vaše hlasy poslaly ze semifinále až do finále.\r\nP.P.S. Můžu vyhrát holicí strojek (takový ten lepší, který si nezničím na moje železné vousy), tak budu vděčný za každý hlas'),
(239, '2017-11-15 09:09:58', 'V návalu pozitivní euforie slíbíte dítěti něco, co za den zapomenete, ale váš potomek to drží v sobě klidně deset let. I já jsem se unáhlil a vyřkl v tomto ročním období letní seanci ve stanu na zahradě.\r\n"Jo! tak to se moc těším!" tleskala Emča a Amálka už plánovala, kolik dinosaurů se do stanu s námi vejde. \r\n"Ale musí být velké teplo o prázdninách.... " dávám si podmínku života mezi brouky a hvězdami. Chvíli tím žily, ale pak se šlo spát, protože se večer spát zkrátka chodí.\r\nJenže, bylo k půlnoci, se z Emčinýho pokoje ozve šeptající hlásek, který mne probudí:\r\n"Tati, tati, tatínku...." zní jak vábení z lesa hlásek dcery.\r\n"Emi, co je?" vstávám v domnění, že se jí zase honí zlé sny. Ale Emča pokračuje.\r\n"A jak se používá TEN STAN?"\r\n"Ty nespíš?" zůstáván zmražen před vchodem do pokoje.\r\n"Ne," stále šeptá. \r\nOpravdu nespala a racionálně přemýšlela o použití stanu a všeho, co jsem říkal o stanování. Je na čase oprášit staré časopisy Junák :D'),
(241, '2017-11-19 09:10:10', 'Musím všem příznivcům tohoto blogu PODĚKOVAT. Velice si vážím faktu, že i když mi není dávno dvacet, a někdy se s technikou peru velice dlouho, ocení to nemálo příznivců, kteří nejen část života s dvojčaty prožívají se mnou a dokáží i mile nabídnout zpětnou vazbu. Je to jak pro ty, kteří ještě děti nemají, ale i pro nostalgicky vzpomínající, aby si přiblížili, jaké to třeba před deseti, dvaceti léty bylo. Tento blog je pravdivým (a někdy i humorným) okýnkem do našeho života s dvojčaty. Ale chci jeho prostřednictvím také nabídnout odlehčení nebo i radu ostatním, a hlavně té mužské části, že nejste jediní a nejste osamoceni. Je nás víc, kteří se denně pereme o kousek úsměvu našich ratolestí. Je nás víc, kteří zajímavé situace zažíváme dennodenně a někdy z nich jsme na větvi, nebo si neví rady, nebo se smějeme na celé kolo.Včerejší večer všech nominovaných blogerů, instagramáků, youtuberů a dalších byla taková větší oslava digitálního světa a sociálních sítí. Nevadí, že jsem se nedostal až na nejvyšší příčku, ale postupně se tam propracuji, to slibuji! Jája s dvojčaty se také dívala, a Amálka prý brečela, když jsem nevyhrál (spíš to přisuzuji tomu, že holky chtěly, abych řekl jejich jména, kdybych vylezl k tomu mikrofonu :D ) Přiznám se potupně, že jsem tam, až na pár výjimek, nikoho neznal. Celý večer popisovat asi nemá cenu. Jen pár postřehů mohu přidat. Třeba jak bylo vidět všude to nadšení pro sociální sítě a diváci až hystericky vřískali, když se ozvalo jméno jejich internetového idola. A taky, že se všichni tak respektovali, chválili a podporovali.Doufám, že i nadále mi zachováte přízeň a třeba tyto stránky i pošlete dále do světa. Že mi napíšete, nebo jen "lajknete" něco, co se vám ode mne líbilo. Ještě jednou děkuji, že jste mne svými hlasy dostali až do finále. Je ještě co zlepšovat a nabízet. Jste všichni fajn a super.Závěr patří Jáje a našim dvojčatům, o kterých to všechno je: Děkuji i vám, že bláznivého tátu pouštíte na sociální sítě, aby zákeřně napráskal nevšední zážitky celé rodiny. Jáje velkou pusu a Amálce a Emče taky. MÁM VÁS, HOLKY, MOC RÁD!!');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(242, '2017-11-23 21:23:50', 'Chtěl jsem vás něčím překvapit. Trochu překvapit. Takové malé poděkování všem fanouškům. Není to žádná studiovka (ale třeba jednou mi to holky nazpívají o dost líp pro mě :D ) a fota jsou z našeho archívu. Ale řekl jsem si, že se to k sobě hodí. Zpívá se tam o tom (hoooodně volně přeloženo), že i když jste na dně, tak přijde někdo, kdo vás pozvedne do výšin. Tak jako moje rodina, jako vy. Jako každý, kdo si to jednou v životě zaslouží ;-) Sice ještě nejsou Vánoce, ale už se mi dostavuje nostalgická nálada, ale nebojte, jsem jak Chuck Norris. Ten nejtvrdší táta na světě :D \r\nTAKŽE, TADY TO MÁTE - a ano, zpívám to já (moc mne nekamenujte, bylo to na jednu "dobrou"):\r\nhttps://youtu.be/SM_Zb0AF6jI'),
(243, '2017-11-27 11:39:59', 'Emča je něco jako radar. Klidně můžu půjčit. Nezklame. Vše zaregistruje, vyhodnotí, zanalyzuje a následně si to bude aspoň tři týdny pamatovat. Má několik zajímavých módů, ale bohužel si je sama přepíná, jak se jí zachce. Nejméně oblíbený je:\r\nFOTBALOVÝ - "pocem, kam jdeš" - tento mód je používán nejčastěji a hned od rána. Není nic lepšího, než mít za paty dítko, které chce po vás zdůvodnit každý váš krok.\r\nPROČ MÓD - ano, i k nám se už dostavila nejpoužívanější věta zvídavého nezbedy "A proč je tohle?" Pročování bych přiřadil k boji ve vysoké trávě. Nevíte, kdy a odkud na vás otázka přiletí a špatně se eliminuje. \r\nDESTRUKCE - už jste někdy přišli o milovaný hrníček? Byly vám počmárány drahé záclony nebo nerozbitné dveře se staly navždy zničenými? Zadřela se vám v koberci modelína nebo trháte rozzlobenou Amálku z Emči, protože jí zase zničila nakreslený obrázek? Můžu klidně pokračovat. Už si vedu tajný svazek.\r\nZPÍVAJÍCÍ MÓD - je to roztomilé, ale ty neustále se opakující tři tóny zpívané ve výškách v uzavřeném prostoru auta už jsem úspěšně zaregistroval jako nový výstražný tón. Já jsem si to osobně nastavil jako zvonění na budík. \r\nSamozřejmě má daleko pestřejší výběr i těch milejších módů.\r\nU Amálky jsem našel zatím jen KRESLÍCÍ MÓD, který trvá od rána do večera. Zřídkakdy se u ní objeví PROČ - PROČ MÓD.'),
(244, '2017-11-29 13:26:58', 'Zajímá vás, JAK ČŮRAJÍ PRINCEZNY? Napsal jsem tematicky pohádkovou úvahu, která se týká samozřejmě i našich dvojčat a dokonce jsem si dovolil i osobní kresbu přidat v novém - prosincovém - čísle Pravý domácí časopis. Tak šup, utíkejte do nejbližší trafiky pro POHÁDKOVÉ ČÍSLO Pravého domácí časopisu. Stojí za to!'),
(245, '2017-12-01 09:57:38', 'Mám rád dobré a chytré dárky. Takový zrovna držím v ruce milý kalendář z dílny Babičkářství.cz - dárky pro babičky a dědečky. Takový, třeba i vánoční dárek, jen tak nenajdete. On to není totiž jen tak obyčejný kalendář. Dáváte s ním i kus sebe, tedy vašich dětí. Ale popořádku. Nejprve pro obdarované: Na každý týden najdete nějakou pranostiku nebo zajímavost. To sice mají i jiné kalendáře, ale tady se jde dále. Děti mají totiž 12 listů na to, aby nakreslily tematické obrázky. Třeba na zimu lyžování, na léto koupání. K dispozici máte i samolepky, takže můžete nalepit dorty na určité dny jako narozeniny, nebo ještě různými motivy doplnit dětské obrázky. Tento kalendář se opravdu povedl a pokud byste o něj měli i vy zájem, tak se koukněte sem: https://www.babickarstvi.cz/dalsi-originalni-darky-pro-seniory/577-nejmilejsi-kalendar-pro-babicku-a-dedu-8594185199960.html?search_query=kalendar&results=6\r\nJá, být třeba Pohlreichem, bych této svíčkové, pardon výbornému kalendáři dal sto procent hvězd. Tak a dvojčata jdou kreslit. Snad mi na zimu nenakreslí kluka v trenkách a na léto mi tam Amálka nenakreslí dinosaura :D  '),
(246, '2017-12-04 11:43:59', 'Doma je slyšet šílený řev. Oponuji, že takhle možná řvou mrtvoly (to je divný, proč zombie řvou), ale ne kostlivci. Na to šla Emča vyděsit kocoura pod sedačku, aby se nakonec honily po celém domě s Amálkou. Ano, připravovali jsme se na mikulášaký karneval. Mršky až do příchodu čerta rejdily. Pak se schovávaly za mě a Jáju. Pět minut naprosté nirvány pro dospělé :) P.S. Na konci si Emča nezapomněla do mikrofonu zazpívat hit roku Jdu cestou necestou z Princezny ze mlejna. P.P.S. A jak to tak bývá, bezva namaskovala moje žena Jája ;) kdo by chtěl od ní zmalovat, může se přihlásit'),
(247, '2017-12-04 12:51:09', 'Od včera mne nějak bolí záda. Dobře, dobře, nemůžu se skoro hnout, z auta vystupuji jako po operaci kyčelních kloubů. Je to ta bolest, kdy se lámete v půli na jednu stranu, ale z dálky to vypadá, že jdete v podroušeném stavu v pravé poledne domů. Doma jsem si na to dal hřejivou náplast jakési neznámé výroby, protože nám došly ty komfortní (ty mi vypotřebovala Jája!). Ale každý obklad se musí sejmout z bolavého místa, neboť zahřívání postižené oblasti už tak nefunguje. Jenže tato náplast III. kategorie byla odstraňování velmi skeptická. Zavřel jsem oči a trhl. Neuvěříte, kolik chlupů má chlap na zádech na boku! Vlastně už žádné nemá!! Zaúpění bylo jen malou třešničkou na bolestivé zneškodnění přisáté nepotřebné věci. Nakonec přišla dvojčata. Chtěla s otázkou "co se stalo" ukázat postižené místo. \r\n"Páni! Tam nejsou úplně žádný chlupy! obdivovaly postižené místo. Amálka se mě jala kontrolovat i na rukou, zda aspoň tam mi chlupy zůstaly. Depilace hadr.'),
(248, '2017-12-19 12:48:37', 'Tuhle k nám dvojčata přišla s totálním nadšením, že připravila divadlo. Sice nám tu divadlo hrají každý den, ale tohle bylo přímo to Národní. Z narozenin měly holky ještě čísla 5, která byla také zakomponována do děje. Ema vytáhne jedno z čísel a mává jím před Amálkou: \r\n"Co je to za písmeno?"\r\n"To je číslo..." opravuje ji z "hlediště" starší brácha Lukáš. Amálka se zamyslí a nevinně se zeptá:\r\n"To je šest nebo osm?" kouká na tu pětku a v publiku to zašumí smíchem....'),
(249, '2017-12-29 19:10:19', 'Dnes se rozhodlo zajet si na malý výlet. Dvojčata byla nalákána do sychravého dne s příslibem cukrárny (proboha proč, to nevím, když je toho doma tuny). Vyjedeme s tím, že se stavím i na poště, jenže nejsem rozhodnut, zda u nás, nebo až na místě. Bohužel jsem si to rozmyslel na cestě. Přeci jen u nás to bude rychlejší a tak zajíždím na parkoviště místního pohostinství, abych náš koráb obrátil. A najednou se zezadu ozve Emča:\r\n"Proč jedeš tudy, když nemáš rád pivo?"\r\nAsi začnu zakrývat svým dcerám oči černou páskou, aby nevěděly, kam vždy jedeme, nebo smíchy nebudu moct řídit.'),
(250, '2017-12-31 15:14:30', 'Je tu ten poslední den v roce. Bilancovat mi nepřísluší a tak jen na pobavení jeden text, který jsem napsal pro jistý časopis: „Tatííííí…“ Ozve se mohutný řev z místnůstky, kam i císař pán musel chodit pěšky. Teprve nyní jsem si vzpomněl, že tam jedna z dcer zaplula, no, je to dobrých deset minut. Otevírám nervózně dveře a už se na mě culí nejenom moje dítě, ale i několik panenek princezen. \r\n„Co ty tady dělají?“ \r\n„Čůraly se mnou,“ odpovídá hned dcerka a dodává, že ona při tom dělala krokodýla. To je krycí název pro vykonání té vetší potřeby. \r\n„Ale princezny přeci nečůrají na záchodě…“ vypustil jsem rozmrzele z úst větu, která už nešla vzít zpátky. Přilítlo druhé dvojče. Je to jako krev ve vodě pro žraloka. Pokud se řekne pár zajímavých slov, okamžitě jsou u vás a už se jich nezbavíte. \r\n„Tatí, a jak tedy čůrají princezny?“ \r\nVypustil jsem ústy z plic všechen vzduch a doufal jsem, že zmizím nenávratně jako právě vyfouklý balónek. Nestalo se tak, naopak se na mne obě dvojčata nahrnula v domnění, že jim tuto závažnou otázku zcela racionálně a ke spokojenosti obou zodpovím. Tohle by nezachránil ani Andersen nebo Němcová. \r\nKaždá princezna čůrá. Čůrá i Superman. Aspoň myslím. Ale princezna jistojistě. Jenže nemůže chodit na obyčejný záchod. To dá rozum. Taková Sněhurka v lese se sedmi trpaslíky přeci nemůže chodit na dřevěnou kadibudku za stavením. Trochu jsem se škodolibě usmál, když jsem si v duchu představil, jak asi musí vypadat vykonání potřeby Elzy v jejím Ledovém paláci na Severní skále. Taky mi nešlo do hlavy, jak to dělaly všechny princezny, které byly zavřeny ve věži hradu. Nadechl jsem se a mohutně vydechl znovu. \r\n„Jak čůrají princezny?“ \r\nKdyž se dětem rozšíří oči, tak pozor! To jsou totiž kontrolky, které problikávají, protože si vše zapisují do své paměti. Takže musím najít ta správná slova. \r\n„Princezny čůrají po princeznovsku,“ projevil jsem talent mluvit jako politik. Emča mne zatahala za rukáv s důležitou otázkou, kterou mi musela pošeptat do ucha. \r\n„Tati, a kakaj taky, že jo?“ \r\n„Taky. Jako vy. Protože jste taky princezny,“ pohladil jsem jí po vlasech a nadmula se pýchou z jejího titulu. Celý den pak procházely kolem obě oděné v princeznovských dlouhých šatech. A tak vím, že princezny čůrají jako malé holčičky. Stoupnou si na stupínek, sednou na princeznovský záchůdek, podrží si šaty dopředu, aby si je nepočůraly, a hlavně si tam pozvou celé příbuzenstvo princezen, protože čůrat princezna nikdy nechce sama. Tak čůrají princezny. Zkuste mi to vyvrátit. \r\nA tak vám všem přejeme, jako početná rodina (i fenky a kočky) ten NOVÝ ROK 2018 co nejpříjemnější a nejpohodovější. Dvojčata totiž nebudou zaručeně jen princezny, ale také nám vyvedou něco (jako rádcové X a Y ze Šíleně smutné princezny), co zas budu moci s úsměvem napsat sem na blog. Zadoufám, že mi tu zůstanete věrni a i příští rok vytvoříme ještě větší dvojčecí "rodinu" než tento rok ;-) Emča, Amálka, Jája a já vás moc zdravíme!'),
(251, '2018-01-06 11:21:57', 'Děti se chválit musí. Pak si zvyšují sebevědomí a odtáhnou to daleko. Třeba jako Amálka.\r\n"Tati, podívej, jak to umím..."\r\n"Krásný, Amálko, jsi šikovná holčička," chválím, seč můžu. \r\n"Já vím. Umím všechno. Budu moct do CIRKUSU!"\r\nNo príma.'),
(252, '2018-01-10 14:25:45', 'Emča dychtivě:\r\n"Tati, tati! Pojď, budeme si hrát na schovávanou, ano?"\r\n"Tak jo," usměju se, protože vím, že při schovce nikdo nebude křičet a pískat. Jsme rád, protože mě už druhý den bolí hlava. Asi stárnu.\r\n"Tati, tati, tak teď budeš počítat a pak nás budeš hledat, jo?" pokračuje dál s instrukcemi Emča a než odejde dodá: "Počítej pomalu, já se schovám pod gauč, tak ne, abys mě našel hned..."\r\nMůžu já něco s nimi hrát?'),
(253, '2018-01-16 18:49:36', 'Barvy. Když je něco barevné, je to i hezké. To mi dá asi každý za pravdu. A když se o barvách baví děti, zaujme vás to někdy možná více, než nějaké prázdné debaty dospěláků. Jeli jsme dnes s dvojčaty nakoupit. Emča je holka zvídavá (Amálka taky, to se nebojte) a tak mi povídá:\r\n"Tatínku, je láska fialová, že jo?" \r\nTak, jasně, vím o co se jedná. Jsem táta a musím doma sledovat radovánky ratolestí. A zrovna se holky dívaly na jeden z příběhů Barbie, která byla ve světě víl. Královna víl dostala nevědomky nápoj lásky a zamilovala se do Kena a unesla ho (to je hustý, co?) A jak byla omámená a tím pádem zamilovaná, měla oči FIALOVÉ.\r\nOtázka o fialové lásce mě nutila to trochu rozvést a Amálka se ráda zapojila. \r\n"Fialová? Holky, láska není jenom barva, ale řada jiných věcí..." ale abych jim ještě víc zamotal hlavu, pokračoval jsem po vzoru dospělácké konverzace. "Zase na druhou stranu se nadá chytit. Je to váš pocit, vaše cítění. Je to to samé, jako když hledáš každý večer svého králíčka, Amálko. A brečíš, když ho nenajdeš. Máš ho ráda. A nechceš ho ztratit. To je taky láska. Máš ráda i nás, rodiče..."\r\nHolky mi skočily do řeči. Respektive nejprve Amálka: "Tatínku, nene, láska je růžová, protože jsou srdíčka růžová."\r\nDo toho se zase obula Emča: "Tak to ne! Srdíčka jsou červená! Takže je červená!"\r\n"A zlatá, protože se třpytí..." rozdmýchávaly stále dychtivěji holky debatu (houbeles, už nyní vědí, že je to taky o prstýnkách a řetízcích. Už to mají ty ženské v sobě zkrátka zakódované).\r\n"Ale černá ne! Ta je smutná." ohradila se najednou Amálka. Chvilku se ještě s Emčou hádala o barvách, až se shodly, že přeci jen bude nejlepší označit lásku jako růžovou, červenou a fialovou. \r\nJak to máte vy? Jakou barvu byste vybrali pro lásku?'),
(254, '2018-01-18 13:21:27', 'Teda jako dneska si připadám jak žena v šestinedělí krát sedm, k tomu do závorky připočítáme osminásobný tlak v papiňáku a výbuch Vesuvu s následným zavalením Pompejí. Nakonec to všechno zmuchláme a přilípneme k TNT, které vyhodí do vzduchu polovinu Himálají. Jo, tohle jsou moje nervy. Vyhlašuji 50% - ne, 70% slevu na víkend s našimi dvojčaty!'),
(255, '2018-01-22 07:37:53', 'Už dva měsíce (na doporučení) testuji instagram. Sem tam se oba virtuální světy, jak FB tak INSTA, prolnou, ale jinak tam uvidíte a přečtete si i něco jiného, než zde. Aspoň mě to donutí víc fotit :D Takže se můžete podívat sem: www.instagram.com/dvojcata_na_uteku a třeba se můžete stát i mými "followery" Teď už stačí jen udělat ještě nějakou vlastní show v televizi. A můžou jí rovnou moderovat naše dvojčata ;-) '),
(256, '2018-01-26 11:15:28', 'Co já jim budu vysvětlovat, až budou velké? To nevím. Ale co jim vysvětluji teď, na to stále připraven nejsem. Emča s Amálkou ze od Vánoc zamilovaly do Anděla páně. Jako do pokračování této hezké pohádky. A učaroval jim kdo jiný, než čert Uriáš. Tuhle se ptaly, jestli má pod tím pláštěm čertovský ocas. No co, představivost nezná mezí, takže ho tam schovaný určitě má (nějak, někde). Pak další týden začaly řešit, že je málo chlupatý.  Ale dnes si vzala Emča DVD do ruky, ukázala na Uriáše a říká:\r\n"Tati, a má čert anděla páně PINDÍKA?"'),
(257, '2018-02-15 10:49:44', 'Ráno jsem nechal Jáje vzkaz. Stejně tento svátek slavíme doma každý den a ne jen dnes. Ja měl od ženy připravený sladký dárek. Jenže ten mi stejně snědl hádejte kdo? Ale tu třiceti centimetrovou bonboniéru si ubránit hodlám. Všem taky pusu na čelo a mějte se rádi!'),
(258, '2018-03-08 08:51:52', 'Přišel jsem do obýváku a jen tak, z legrace, jsem šel na všechny čtyři a jako mohutný bernardýn se svalil na záda v domnění, že se mi žena vrhne kolem krku a začne mě ňuchat stejně jako naše kočky. Jája na mě koukla z kanape, kde seděla i s dvojčaty. Holky se dívaly na telku a mě pozorovaly jen po očku. Jáje sice vystřelovaly koutky, jak zadržovala smích, ale stejně se neměla k tomu se zvednout a svého starého psa potěšit. Zato Emča se nasupila. Vjelo to do ní jako blesk a dokonce bych přísahal, že se jí kouřilo z uší a z očí mě laserem propichovala skrz na skrz. "Co je?" udivilo mě její chování. Kdyby byla chlap ve středních letech, přísahal bych, že se tak určitě projevuje proto, že jeho žena nabourala milované auto. "NIC!" řekla drsně Emča a oči měla temné jako komiksový hrdina při pomstě na předposlední straně příběhu. "Tohle tatínkové nedělají!" Založila si ruce přes prsa a přešlapovala nervózně na místě. "Tohle nedělají! TATÍNKOVÉ SEDÍ NA GAUČI, LUXUJÍ, DĚLAJÍ DĚTI A MAJÍ JE RÁDI!!!" Horlivost projevu mě sice zarazila, ale Jája se začala dusit smíchem podruhé. Myšlenkové pochody našich dcer bych někdy opravdu chtěl mít.'),
(259, '2018-03-13 17:57:12', 'Dvojčata nebyla dlouho nemocná. To je sice dobře, ale hádejte, kdy si to vybrala? Ano, teď. Před týdnem Amálka, nyní Emča. A tak musím být u nich. Když byla nemocná Amálka, tak si Emča nevěděla rady se svou energií, ale hromosvod jsem byl naštěstí já nebo Jája a tak bylo nebezpečí zažehnáno. Teď tu Emí leží, Amálka je hrozně hodná a hraje si sama. Ale zase je po celém obýváku rozeseto na tolik hraček, že je využit každičký centimetr čtvereční a já tu tancuju jak baletka, nebo latinskoamerický tanečník. Emča se probudí s horečkou a její nálada se střídá od úsměvu k pláči stejně rychle jako výměna pneumatik ve formuli 1. K tomu mi, hledíc do dálky, říká, ať ten pán s dárečky neodchází. Když ji pohladím a řeknu, že jsem u ní, že se nemá čeho bát, tak mne obejme a řekne, že jsem super. Pak se zase rozbrečí a neví, jestli se má napít nebo vyčůrat. Řeším to věcně, pije na WC. Pak už zase říkám pohádku a nakonec zazpívám dlouhou písničku (jo, pamatuju si taky něco, nehraju pořád z not :D) a přehopsám ve stylu hip hopu do kuchyně, kde na mě čeká nádobí. A tak se tak nějak konejším, že tam někde venku jsou také maminky, které to mají zcela stejné jako já.'),
(260, '2018-03-14 22:45:46', 'Pamatujete si ještě, jak si holky hrály na to, že mluví anglicky? Teď si tu ukazují obrázek koně a Emča se Amálky ptá, jak se kůň řekne anglicky. Amálka pohotově: "EL ULEŤ."'),
(261, '2018-03-22 09:21:42', 'Je krátce před půl sedmou hodinou ranní. Otevřu oko. Nade mnou stojí jedna z dcer a prohlíží si mě jako Lenina v Mauzoleu. "Co je?" zašeptal jsem. Chvilka váhání s odpovědí mě začala znovu uspávat. "Tati," trhnul jsem sebou. "Můžu k vám?" Otočil jsem se na ženu, která měla obličej zabořený hluboko v polštáři jako když vás někdo vyfotí před dopadem do vody. "No to asi ne..." poprvé hned po probuzení zesílil na pár vteřin můj tep. "Tati," začala dcera hlavní otázku dne. "Co budeme dnes celý den dělat?" Tenhle kolorit si neodpustí ani na Štědrý den, což už zavání systematickou provokací. "Začni tím, že si půjdeš vyčistit zuby, umýt obličej a převlečeš se." Jako super je mít děti, které poslouchají a vše si zařídí samy. Jenže tyhle naše dvě to nejsou. Nevím, jak se stalo, že místo toho, aby můj potomek odešel splnit ranní rituály, zamrzl na jednom bodě a jen na mě neustále koukal. Mrknul jsem. Dobře, asi na vteřinu se mi zavřely víčka. Po otevření tam dcera stále stála. Začal jsem přemýšlet, zda moje vyjádření bylo přesné nebo ta chichotající se vlasatá věc potřebuje přehrát nový software. Jenže pozor, nebyla sama. Už tam byly obě. Mauzoleum asi znovu otevřelo. Mít svůj soukromý živý budík je naprosto príma. Tak a teď už si jen srovnat myšlenky, jestli si vzít malý nebo velký hrnek na kafe. Tak krásné dobré ráno.'),
(262, '2018-03-29 23:18:39', 'Nedávno na sociálních sítích i v televizích a tisku proběhla - a znovu i rozdělila společnost - kauza maminky, která byla v šestinedělí a jejího pětinedělní miminka hospitalizovaného na JIRP v Ústí nad Labem. Jako táta malých dvojčat jsem vše sledoval od začátku už jen proto, že díky informacím, dobrých pro děti i rodiče, jsem v různých skupinách a v jedné to bylo vlastně téměř online prezentováno. Myslím, že už bylo sepsáno hodně článků a odvysíláno mnoho reportáží a vše je na internetu dohledatelné, tak jen pro případ, že by to někoho minulo přikládám do závorek jeden odkaz (https://prima.iprima.cz/…/matka-chtela-zustat-s-ditetem-v-n…)\r\nJá, za sebe, bych se rád postavil na stranu maminky a dítěte. Jako táta nevím, co se v ženském těle přesně děje jak psychicky tak fyzicky, ale po něčem tak nádherném, jako je porod a přivedení na svět dalšího člověka, kterého pak vychováváte a celkově se o něj staráte, by mělo být přeci z přírody logické, že se maminka o své dítě bojí a chce mu být nablízku. Nehledě, že opravdu nic, z mého názoru, nenahradí mateřské mléko (názor doktora byl opačný, prý umělé mléko je nejlepší), které je pro novorozence fakt dost důležité. \r\nV dnešní době právních kliček, kdy se víc někdo dívá na to, jak jen to napsat, aby druhého "odrbal" než pomohl a zákony se dělají jen proto, aby se mohly hledat kličky, jak je obejít, mi přijde hodně nesmyslný popírat jak rodinnou soudružnost, tak mateřství jako takové. Je smutné, že se dějí věci, které v důsledku končí otázkou: "Víte, kolik by to stálo?" Škoda, že se vytratilo důležitější "Vážím si lidského života." \r\nJe škoda, že lékař, nebo jiný zdravotnický personál, nehledal cestu k tomu, jak přiblížit maminku ke svému nemocnému dítěti, kterého chtěla dále kojit a spíše jí házel "klacky pod nohy." Komu by taky bylo příjemné, že na něj zavolali policii, i když nic neprovedl. Podle chronologie záznamů chtěla maminka jakkoli být u dítěte a protože jí nebylo doktorem umožněno vůbec nic a zavolal na ni veřejné složky, začala telefonovat o pomoc (existuje něco jako pomoc maminkám v nouzi - třeba právě hospitalizace s dítětem a podobně). Dál už to víte, slyšeli jste nebo četli. \r\nRozhodl jsem se sem napsat už jen díky tomu, že nerozumím faktu, že je odebíráno právo dítěte mít u sebe svého zákonného zástupce (což jsou rodiče). Vyhazováním nebo "nabízením" spaní jako bezdomovkyně na podlaze (kde ji pak mají pravomoci vyhodit) ,se mi zdá mírně řečeno nešťastné. Maminka - jako i iniciativa pomoci maminkám v nouzi - má moji plnou podporu! Doufám, že se nejen její miminko brzy uzdraví, ale že i ona se domůže svých práv (které jsou zakořeněny i v právní legislativě ČR) a samozřejmě přeji i ostatním miminkům nejen na pokoji JIRP v Ústí, ale i kdekoli jinde v nemocnicích, aby byly co nejdříve zdrávy au svých rodičů. Buďme na sebe milí, usměvaví a hlavně podporujme rodinu a děti. Je to to nejcennější a do budoucna jak pro všechny, tak i pro stát nejdůležitější. \r\nTáta od Dvojčat na útěku'),
(263, '2018-03-29 23:19:23', 'Dnes naše "Homolkovic" rodinka byla účastna křtu výletnické knížky (která je hlavně pro děti) Výlety s tajenkou. Autorka Lucka Nachtigallová alias Deník fejsbukové matky (jo, jasně Luco, ty mi budeš říkat, že mám hrozný příjmení '),
(264, '2018-04-17 22:15:08', 'Kdo do toho půjde se mnou? (Výzva?) \r\nTuhle o mojí postavě, respektive o mém pozadí dvojčata utrousila, že není takové malé jako maminky (rozuměj: "Tati, máš zadek jako balvan" - já tomu říkám "Štýrskej valach") a tak jsem přemýšlel. Vždyť taky proto, abych nedělal svým dcerám ostudu, jsem cvičil a zdravě jedl, když byly miminka, aby se pak za mě nemusely (i Jája) stydět. A pak přijde sprcha pro mě nevtipných komentářů. Co pak budu dělat v létě? Chodit v tričku po pláži, jak jsem to dělal, když jsem měl svých 112,5 Kg? Teď se dlouho držím na průměrných 97 Kg, ale rád bych měl aspoň 92 Kg a vrátil si pár svých svalů na místa, kam patří. Přeci jen mi bude hezkých kulatých - ehm - a člověk by i pro sebe měl zkrátka něco udělat. Protože jsem chlap, mám slabou vůli (znáte to, něco si řeknete a pak odložíte na "potom"). Když však půjdu s kůži na trh, bud mít motivaci a hnací motor, abych pak nebyl za malého (velkého) trotlíka. \r\nA teď k tomu hlavnímu: Do začátku léta (1. 7. 2018) bych chtěl mít zmiňovaných 92 Kg a pár bicáků navíc :D Chce se někdo se mnou připravit na plážové pózy? ;-) Stačí, když se teď vyfotíte (a foto zatím nezveřejníte) a začneme trochu víc cvičit a méně a zdravěji jíst. Já tu vždy napíšu po týdnu, co jsem tak dělal a 1. 7. 2018 tu zveřejním výsledek. Jako Jája na fotce vypadat nebudu, ale třeba se trochu přiblížím osobnímu lepšímu pocitu, že jsem pro svoje tělo (a všechny moje holky) něco udělal :D\r\nEDIT: Můžete mi vymyslet trest za případné selhání a odhození cvičení na další roky ;-) A když to dokážu? Napíšu novou knížku a všichni, kdo do toho půjdou se mnou a zveřejní výsledek, ji pak dostanou i s podpisem'),
(265, '2018-05-03 09:06:29', 'Nejsem v tom sám! O tohle se podělit musím. To si totiž začnete dělat věci automaticky a už o nich ani nepřemýšlíte, že? Tak tu nyní vytahuji umyté talíře z myčky a sám se divím, že je na nich špína. Hele, ona se neleskne ani ta sklenička, na které jsou nánosy čehosi. Už trochu nervózně vytahuji i příbory, které vesměs zůstaly tak, jak se tam daly. Hm, i můj oblíbený hrnek se neumyl. Trochu jsem znejistěl, jestli se to nádobí dalo vůbec umýt, ale svítící nula na displeji jasně ukazuje, že tento úkon proveden byl. JENŽE: Došly nám tablety do myčky, které jsou v rozpustitelném obalu a jen se dají do myčky a o vše je postaráno. Máme i druhé tablety. ALE TY SE ZKRÁTKA MUSÍ VYNDAT Z OBALU, což Jája neučinila a do přihrádky na tabletu to dala i s tím nerozpustitelným obalem. Takže celou přípraven na mytí jsem našel nepoškozený na dně myčky. Jupí, nejsem v tom sám! Hele, mám fakt dobrý den :D'),
(266, '2018-05-09 13:42:10', 'Jen krátká zpráva pro ty, co se (doufám) se mnou snaží být fit a cítit se líp letos v létě v plavkách. Týden III. Jak jsem si řekl, tak i udělal. Váha jde pomalu dolů (asi by nebylo dobré nějaký ten rapidní úbytek - už jen třeba kvůli energii, kterou na dvojčata potřebuji). Pak se půjde na cvičení s vlastní váhou + nějaké ty malé činky;-) Tak vy ostatní vydržte, pokud třeba jen k večeru už nejíte a jen si dáte vodu :D Chápu, je doba grilování, ale mě určitě nedostanou :D'),
(267, '2018-05-09 13:42:33', 'Zjistil jsem, že naše děti nejvíce perlí v autě. Asi proto, že si nic nepamatuju a stěží to dokážu zaznamenat. Na mě si ale nepřijdou. " Tati, víš, kde budu chtít mít dům, až budu velká?" hlásí hrdě Emča a hned dodává. "V zoologické zahradě. A bude ten dům velkej!" V hlavě mi mihne nějaká ta myšlenka o opičím pavilonu. Amálka to ozdobuje stejným přáním s tím, že tam musí být na dvoře velká žirafa. Ok, takhle se nenásilně šmírují sousedi. A Emči monolog pokračuje. Jenže - to druhý, to si fakt nepamatuju.'),
(268, '2018-05-14 09:27:37', 'Stal jsem si tátou na plný úvazek, když našim dvojčatům bylo osm měsíců. Od té doby mě měly za zadkem každý den od pondělí do neděle a tu dovolenou, kterou mají rodičové, aby se o své ratolesti starali, jsem věnoval jejich výchově, růstu a socializaci. Byly chvilky, kdy bych vyskočil z kůže. No spíš skočil ze 4. patra na dlaždičky, abych už měl klid, ale vždy jsem tak nějak věřil tomu, že to bude lepší a lepší a samozřejmě, že je, to se nebojte. \r\nKdyž jsem se stal tátou dvojčat, byly to mé první děti (a asi i poslední) a vůbec jsem netušil, jak se o ta malá stvoření starat. Jája, moje žena, mi byla a je dobrou rádkyní a vše, co jsem musel kolem miminek a pak už i starších dětí dělat, jsem se učil za pochodu. Po přestěhování do domečku jsem dlouho nemohl najít zápisníky holek, kam se psala všechna poprvé a i další veselé vzpomínky. Tak jsem začal psát takový deník. Blog. Ale především vzpomínky pro naše dvojčata, aby si jednou mohla přečíst, co v mládí prováděla a podívat na fotografie, jak vypadala. No, docela dobrý na to, že mě se uchovala jen jedna fotografie ze školky, ne? \r\nPak se trochu blog rozšířil i do jiných stran, než k našim známým a kamarádům a, i za pomoci jedné mé výborné blogersko-spiovatelské kamarádky, se rozšířil řad fanoušků. Vím, nejsem vtipný (omluva za to, jsem suchar, no), nemám ani kupu famózních příběhů, kterými bych vás ohromil (stejně hned všechno zapomenu), hrozně nerad (a špatně) fotím, takže ani ty fotky nestojí za nic, ale dělám to tak nějak srdcem. Rád a hlavně ve svém volném čase. Nevím ani, jestli se v mých skoro čtyřicátinách mohu považovat za blogera, který dokáže dát světu něco, co ho zajímá, nějaké to poselství, které si vezmete a třeba i sami budete praktikovat dál. \r\nCo jsem tím chtěl říct? Vlastně nic a všechno. Jak už mi tu jednou někdo psal - tohle moc nikoho nezajímá. Ano, jsem ten nejhorší bloger :D \r\nAle třeba se najde někdo, komu bude inspirací, že i táta (nejen mamka) dovede svoje (dvě!) dcery zdárně ke všem milníkům od plenek, po první kroky, první slova, první udržení se na kole až po první (to nevím co. To je ještě daleko). Třeba nějaký váhavý tatínek díky téhle stránce nebude mít strach být se svými dětmi na rodičovské a zdárně se o ně bude starat...'),
(269, '2018-05-14 22:15:50', 'Dvojčata se zájmem sledují práci bagru a dumají. Emča: "Já, až budu velká, koupím si bagr. Ne, budu mít traktor." Amálka: "Já chci mít ten bagr. To je super! A všude s ním chci jezdit..." Jo? Tak to ja si kupuju obrněný transportér.'),
(270, '2018-05-28 08:22:09', 'Je tu pondělí a protože 1. 6. je v pátek, mám(e) před sebou ještě 34 dní té mojí malinkaté výzvy, kdy by měl trochu člověk se sebou něco udělat, aby jeho břicho nevypadalo jako, jak já s oblibou říkám, hora Říp a tuky kolem netekly, jak rozvodněná Berounka. Jen bych rád věděl, kdo to se mnou ještě vydržel a dále postupuje v před světlým zítřkům povalování se na pláži? Zkuste mi napsat, jak jste na tom. PROTOŽE - to vám musím říct, je to všechno opravdu jen o jídle. Bože, jak jsem byl rozjedený (ok, rozežraný :D). Úprava jídelníčku a vlastně jen úbytek nepotřebných kalorií slaví úspěchy a již dnes mohu říct, že mám pod 94 Kg. Jako fakt. A dokonce sem tam na mě vykoukne i nějaký ten sval. Už jsme za půlkou - 42 dní od začátku výzvy všem tatínkům, maminkám, strýcům a tetám. 1. 7. si řekneme celkový výsledek i s fotkami (i když se nerad fotím, ale něco jsem nafotil, nebojte :)). doufám, že těch fotek se tu sejde pak víc. Držte si (i mě) pěsti! ;-) Táta od dvojčat'),
(271, '2018-05-29 10:16:41', 'Mé čtyřsté osmdesáté páté setí trávy na zahradě. Stará tráva šla do zelených lovišť sousedního pole. Aspoň bude mít půda jednou ekologické hnojení. Navození pouhých čtyřiceti tří koleček přesívané hlíny na úpravu povrchu se zdálo být dlouhé jako čekání na Vinnetoua v soutězce hadů. Ne, nebylo to fakt za jeden den. Zafoukal vítr a setřel jsem si z trička centimetr prachu. Kdybych si měl nyní přát jedinou věc, nebyl by to světový mír. Postačila by mi zatravněná plocha naší zahrady. Do zahradnictví pro semena trávy a pytle trávníkového substrátu jezdím skoro jak pravidelná linka lanovky na Petříně. Dvojčata mají zákaz zákazů. Teď na zahradě nic nesmí. Jen se jít vykoupat do bazénu. Ale zahrada - ta je jim zapovězená. Ta je na pár týdnů ❌E - E ❌'),
(272, '2018-06-04 14:29:35', 'To si takhle v únoru jedete i s dvojčaty do okolí Krče. Máte totiž za úkol nechat opravit kuchyňský robot. Děti v autě jsou nervózní, vy jste nervózní, že tam musíte jet s dětmi a tak se stane, že vás na 30 Km úseku (ke proboha v Praze je 30 Km/h?) vyfotí radar a magistrát se na vás teď hojí, že jste jel rychleji a chce po vás pokutu 600 Kč. Jsem kriminálník!!! Pro dobrotu na žebrotu'),
(273, '2018-06-04 16:15:16', 'Protože je pondělí - další report "Výzvy pro hezčí rodiče svých dětí" :D Otázka první: Kdo to se mnou vydržel až doteď? Otázka druhá: Cítíte nějaký úbytek tuku a nárůst svaloviny? \r\nZa mě mohu říci, že se mi břicho pomalu ztrácí. Opravdu jen fakt, že už večer nejím, je dostačující. Jinak vše v normálu, dokonce už i nějaké svaly by se mohly mikroskopicky najít ;-)\r\nDržte se! Táta od dvojčat'),
(274, '2018-06-11 10:36:08', 'Dneska v noci tu byla rošáda. Taková noční Malá dáma. Nejprve Emča vzbudila Jáju, protože ji svědila ruka od toho, jak hladila kaktusy (já ji to 153x říkal, ať to nedělá - ale zkušenosti jsou, jak vidno, nepřenosné). Pak nás vzbudila Amálka, která udělala z velblouda komára, protože si začala stěžovat, že ji Emča hodila do pokoje mrtvého komára a ona tam nechce být. Načež se ozvala Emča, že jen žaluje a jak si to takhle může pamatovat. Emča následně znovu usnula. Já neusnul a slitoval se nad naříkáním Amálky, že v pokoji s komárem nebude, že chce spát u maminky. Dobře. Zmáčknul jsem se mezi plyšáky. Amálka se rozvalila vedle Jáji na naší posteli a taky usnula. Pokud jste sem dočetli a pochopili, co se v noci dělo, může mi to pak někdo vysvětlit? Já si zatím rovnám bolavá záda.'),
(275, '2018-06-13 11:35:17', 'Výzva "Pro hezčí rodiče svých dětí" pokračuje. V pondělí jsem hrál. Akce to byla veliká (ne, neprobudil jsem se až dneska, ale zkrátka nebylo tolik času) a víte co, nezobnul jsem si ani tataráku, který se tam na mě smál a jediné, co jsem popíjel, byla neperlivá voda. I tak jsem se bavil :D Jenže, když končíte ve tři ráno a musíte jet ještě z Brna zpět do domoviny, nenajdu lepší slovo než je "vopruz." Pokud tu je někdo, komu letos budu ještě hrát třeba na svatbě, tak fakticky mi raději nenoste ani obložené talíře - MUSÍM se ubránit pokušení :D :D \r\nLehká sumarizace: Jím to, co potřebuji a večer po 17:00 už nejím (pokud nehraju, to si dám pak třeba jen salát). Cvičím s vlastní váhou aspoň obden. Jde to. A cítím se lépe. 1.7. budou i fotky. Sportu a zdravému tělu ZRDAR! Táta od dvojčat #prohezcirodicesvychdeti #vyzva #tataoddvojcat #dvojcatanauteku'),
(276, '2018-06-18 12:49:13', 'K té ženské logice: Jedeme autem a Emča uvidí reklamu na půjčování divadelních kostýmů. \r\n"TATI! OTOČ TO, CHCI SE PODÍVAT! TAM BYLA ELZA!!"\r\nJako všechno, ale nejsem tatínek Batman s pancéřovaným autem, kterému vždy ostatní uhnou. To fakt nedám...'),
(277, '2018-06-21 13:06:15', 'To je den. Dvojčata se od rána mydlí, tedy přímo mlátí. Je to jako v nějakým akčním filmu. Probudím se a ony nade mnou stojí a kopem Bruce Leeho jedna sejeme druhou, načež ji ta druhá podkopne nohy jako při kung fu a druhým kopem ji rozplácne o zeď. Pak se mlátí i při čištění zubů, při převlíkání, na toaletě, dole u jídla... Mě bolí celý den hrozně hlava a jsem jak mátoha a tak si přeji, aby se ve dveřích objevil aspoň Van Damme nebo Chuck Norris a dal si s nimi kafíčko nebo lekci baletu, aby je to všechno přešlo. Jdu si udělat deváté kafe na vyrovnání tlaku a asi sebou švihnu do postele na desetisekundové zavření očí. Dnes nemám den...'),
(278, '2018-06-25 08:42:02', 'Předposlední týden "Výzvy pro hezčí rodiče svých dětí" jsem takticky vynechal, protože nebylo co psát. Rutina, rutina, rutina. Tento poslední týden už mám na kontě necelé dvě kila k 90 Kg (cíl byl celkově 92 Kg). Cvičení bohužel jen tak ob den. Ten druhý se furt něco dělá :D Tak uvidíme, jak nám to za týden všechno dopadlo - co vy? \r\nTáta od dvojčat\r\n#prohezcirodicesvychdeti #vyzva #tataoddvojcat #dvojcatanauteku'),
(279, '2018-07-02 10:33:49', '1. 7. bylo ve znamení ukončení výzvy "Výzvy pro hezčí rodiče svých dětí."\r\nNo, tak přesně nevím, jak moc jsem zkrásněl :D ale musím říci, že jsem se snažil, seč to šlo. Necelé dva a půl měsíce, kdy na začátku jsem upravoval styl jídla, abych pak večer neměl hlad (no hustý teda), abych v druhé půli přibral cvičení s vlastními kily (teda začátek fakt bolel). Narovinu, trochu mi to kazilo hraní na svatbách (sakra, každý mě tam zval na jídlo, abych jim prý do ranních hodin vydržel, ale držel jsem se, jak to jen šlo). Zítra sem nahraji fotky, jak to vypadalo na začátku, kdy mi váha ukázala 97,6 Kg a jak to vypadá nyní, kdy mám kolem 92 Kg. Hlavně - cítím se líp. O to šlo. Kdo to vydržel se mnou až do teď, může mi poslat taky fotky a já je uveřejním, abyste všichni viděli, že jsem v tom nebyl sám a třeba opravu s taky někomu aspoň tu váhu podařilo srazit. Jedno vím už nyní: rád bych v tom pokračoval, aby jsem si ještě snížil tuk a kila a pokusil se o nějaký ten nárůst svalů. doteď jsem to ani nedokumentoval, ale spojil jsem se nyní se svým kamarádem a bývalým kolegou z kanoistiky, který se o pohyb a fungování lidského těla při cvičení hodně zajímá a dokáže ze mě vyždímat určitě maximum a další cvičení a přeměnu s radostí zaznamenám ;-) \r\nDětem a zdravému tělu ZDAR!\r\nTáta od dvojčat\r\n#prohezcirodicesvychdeti #vyzva #tataoddvojcat #dvojcatanauteku'),
(280, '2018-07-19 13:22:06', 'I v knížce Dvojčata na útěku jsem psal, že ač otec na rodičovské, vždy to "vyšlo" tak, že jsem nebyl přítomen prvních zoubků, prvních krůčků a měl to až "potom". Děti už nám odrostly natolik, že se Emče viklá přední dolní řezák. Právě jsme přijeli domů a vyndávám z auta věci a co myslíte, Jája mne asi doma zcela ignoruje, protože jsem nebyl přítomen vyndání prvního zubu. Asi jsem rodičovský smolař. Doufám, že aspoň svatbu dcer budu moci absolvovat :D'),
(281, '2018-08-22 10:33:29', 'UŽ JE TO TADY!!!!\r\n"Přestaň to dělat!"\r\n"A proč?!" (Emča)\r\n"PROTOŽE JSEM TO ŘEK!!!!"'),
(282, '2018-09-03 21:28:34', 'Pocity z dnešního dne? Jak já se těšil. A pak mi, když jsem dvojčata poprvé nechal ve školce, vypovědělo službu auto. Normálně zdechla baterka. Žádný varování předem. Škytlo to a - nestartovalo. Docela pech na to, že jsem měl být ve své práci už kolem půl osmé. Jenže to, když máte ty pravé kamarády, kteří vám pomohou, i když jsou po noční, to nezaplatí ani sebezlatější kreditka. Doteď jsem to znal jen z vyprávění a pohádek, ale ono to tak funguje. Soused Roman pomohl a jak dopoledne jako "taxi" tak odpoledne jako startovač mého auta obstál na výbornou. Takže resumé celého dnešního dne. Holky maximálně spokojené ve školce, já maximálně spokojený, že mám ty pravé kamarády. No nechtějte to na první školní den.'),
(283, '2018-09-12 07:13:56', 'Včera jsem měl tři otázky. Dnes přibyla čtvrtá: 1) proč děti energicky zlobí, i když jsou nemocné? 2) to fakt ti pracující nevydrží ani do 21. hodiny? 3) taky teď po prázdninách potkáváte svůj protějšek jen v zatáčkách? 4) proč mi už zase kleklo PC!?'),
(284, '2018-09-25 09:04:58', 'Ty jo, jako, nejsem geniální bloger s dosahem deset i padesát tisíc, ale teď normálka chci, aby mě celý svět politoval, jak to mám s těmi dvojčaty těžký! Když jenom holky vstávaly a pak se s nimi něco dělalo, bylo to super. Teď? Vstávat to nechce, zevl na posteli aspoň půl hodiny. Když jim něco řeknu, jen začnou křičet ono známé nenenenene, ale totální (víte co) při tomu udělají (sakra, jak v PS)! Je dopoledne a já mám snad tlak 300 na 100. Hele, možná jsem někdy v mládí zlobil a rozbil sklenici s okurkami, ale tohle si fakt teda jako určitě nezasloužím! Všechny děti: OKAMŽITĚ PŘESTAŇTE ZLOBIT!'),
(285, '2018-10-08 14:05:14', 'Tak já nevím. Dneska přijdeme do školky pozdě (jasně, že kvůli dvojčatům) a Amálka se mě nevinně zeptá, když už si v botníku před třídou nazouvá bačkůrky: "Tati a dneska jsem byla rychlá, že jo?" Co jí na to pak mám říct...'),
(286, '2018-10-26 09:55:30', 'Tuhle mne honila mlsná a hlad, a tak jsem si zašel do místního pekařství. Mají tam docela super voňavou pochutinu - něco jako loupák, ale uděláno jako houska (fakt nevím, jak se to jmenuje). Byly tam poslední dvě. Frontu jsem si vystál a ony tam stále na mne čekaly, což jsem byl rád. Za mnou, při objednávce, již stála maminka s malým klučinou. Chudák, když zjistil, že jsem mu vykoupil mňamku, rozbrečel se. Maminka mu sice říkala, že to nevadí, že koupí něco jiného, ale byl neodbytný. I zželelo se srdce mé na nebohou hromadou neštěstí, protože to zkrátka byla jeho osobní tragédie a řekl jsem prodavačce, zda mi to vymění za normální houska a ty svoje dobré sladké jsem mu nechal. Jeho maminka byla asi taky v šoku, ale chlapeček hned přestal plakat. Jen doufám, že si pak ty housky vychutnal beze zbytku nadrobení do kočárku '),
(287, '2018-11-01 18:14:07', 'Už nějakou dobu jezdím s nejmladší kočkou na veterinu, protože ta mrška ne a ne být zdravá. Na vteřině je vždy veselo. Trochu i potlacháme o životě. Zkrátka milý pan doktor i paní doktorka, kteří se o ty naše mňoukací "činčily" starají rádi. Dneska jsem tam s Penny byl znova. Hele, jsem nějaký unavený nebo co, a ono je to na mně i znát. Tedy aspoň paní doktorka mi to říkala.\r\n"Víte, vy vypadáte dneska jako...," nemohla najít to správné slovo a tak za rozdala do slovanských označení, která se možná vyskytovala tak na sklonku předminulého století.\r\n"Jak bych to nazvala... Jak se dříve říkalo: vypadáte jako NEMRCOUCH."\r\nVýrazy mne zajímají a tak se se hned chopil strejdy Google a vyjela mi odpověď na toto označení vskutku zajímavé. Ukazuji telefon s úsměvem, že TOHLE ROZHODNĚ NEJSEM:\r\n"Muž, který by strašně rád souložil, ale nemá s kým, dost často je to přitom člověk, o kterého ženy nejeví pražádný zájem."\r\nAspoň jsem prý změnil kyselý ksichtik za úsměv '),
(288, '2018-11-28 12:02:01', 'Emča začala hrát šachy. Černým říká "černoši" a pěšákům "paneny." Chce za každou cenu vyhodit královnu a koně plánuje po vyhrané bitvě pást na louce. Super, přihlásím ji do kroužku šachistů. Bude jistě nejhlučnější hráč. Po každém vyhození figurky soupeře křičí: GOOOOL :D'),
(289, '2018-12-01 14:56:35', 'Padá snížek bílý, kdo nepřezul, ten šílí. Děti šílí taky, sněhu už je mraky. Až zapadne celý dům, s ním na dvorku pes i kočka, v Praze šílí, neví co s tím, je tu první kalamitní vločka. '),
(290, '2018-12-04 09:31:14', 'Teď před Vánoci je práce hudebníka daleko frekventovanější. Často už máte hraní nasmlouváno rok dopředu. O to víc pak mrzí následující situace: Dvojčata mají ve školce v inkriminovaný čas Besídku. Učí se básničky a Emča mi povídá, že tam bude překvapení a že budou něco říkat a mají si vybrat jednoho z rodičů.... \r\n"A já si vezmu tebe..."\r\n"No jo," začal jsem rozpačitě. "Ale já tam bohužel nebudu, musím být v práci, mrzí mě to, vezmeš si maminku, jo?"\r\nČistě logicky, když máme dvojčata, se zeptala, koho si vezme Amálka? Štve mě to. Je to jediná vánoční Besídka ve školce. Dokonce jsem začal přemýšlet o tom, že bych to na někoho přehrál to hraní, což je zase nefér vůči klientovi, protože to, co si objednal, moc lidí kolem neumí nebo nedělá. \r\nŘíkal jsem vždycky, že nechci být jako táta (sorry, tati, ale zkrátka jako muzikant jsi byl taky furt v luftu, co naděláš, to už bylo) a začínám být stejný? Na druhou stranu, díky té práci můžou být dětské oči rozzářeny u stromečku, protože bylo i na ty speciální moc moc chtěné dárky. Věřte, že se to ve mě mele. Vánoce jsou pro mne docela zásadní srdeční záležitost a každým rokem, když už jsem ten "dospělý a zodpovědný rodič" si je krok po kroku dovytvářím k svému obrazu dokonalosti. Tak tu přemýšlím a dělím se s vámi i o ty starosti...'),
(291, '2018-12-16 21:33:46', 'Hele ale jako fakt. Holky se doléčují z nemocí, takže ani do školky nechodí. Vykrýváme hlídání, jak jen to je možné. Do toho práce obou, vánoční shon a neklid (ale změní se na klid, to vím :D) A já pak ani už nestíhám nic psát. Přišli jsme o besídku i o dárečky od Ježíška ve školce. Svět se ale nehroutí. Zapalte si třetí svíčku na adventním věnci a jen tak se zamyslete, co vy i okolí právě potřebuje. Třeba to totiž bude jen váš úsměv ;-) Krásnou noc všem.'),
(292, '2019-01-16 07:56:02', 'Víte, že jsme s holkama taky ještě na instagramu? Jsou tam z větší části fotky, které zde na FB nenaleznete :D Taky se účet jmenuje Dvojčata na útěku a za mě musím říct, že tam neustále oběvuji Ameriku... hele, co to všechno dokáže :D :D :D (ještě, že holky neříkají: "Tati, ty jsi PC negramot..." :D)'),
(293, '2019-01-21 21:46:36', 'Já se z toho po***. Čtrnáct dní stačilo, aby jeden člověk ve třídě u holek ve školce zakašlal a hepčíknul a Emča je zase zpátky u začínající rýmy, kašle, možná i bolení v krku a já nevím, co dál. Jasně, jsem ve stresu. Bojím se toho jak čert kříže. Musí se pak hned všechno upravit podle toho, zda zůstane doma nebo jak to bude dál, protože babiček nemaje, musíme si vypomoci sami. To si pak říkám, jestli je nutný, aby se děti dávaly do školky (nebo i školy) i v případě nudlí u nosu a kašle, že jim plíce chrčí jak stoletému kouřákovi? Pak se nakazí dalí a další... Kde máte ty hranice vy, pokud vám děti jakkoli onemocní? '),
(294, '2019-02-11 06:08:11', 'Dvojčata jsou u tety. Co víc si přát. Možná tak spánek, když ráno přijedete z hraní. Cože, ona po vás žena něco chce? Jo, když už jsou doma všechny kočky, tak je chytnout a dát jim za krk cosi proti blechám? Hmmm, ranní romantiku jsem si představoval jinak. Ok. Jedná kočka, druhá... KDE je třetí. Jájiny agresivní šelma, toto zcela labilní, jednu paničku uznavající stvoření, uteklo nahoru. Není problém. Jdu ji chytit. Tak a je i třetí kočka. Uf.\r\n"Dáš si kafe...?" Jája načíná pohodovou atmosféru. Rád přikývnu. Pak to začne. Nejmladší kočka se rozhodla zbavit visejícího exkrementu jako opilý silničáři, když malují prerušovanou čáru na vozovku. Musím to uklidit. Jdu se uklidnit nahoru, aspoň ustelu. Už spát nepůjdu.\r\n"Co to tam tak pořád smrdí... Jájo, tys tu něco stříkala?" "Ne, proč..."\r\nTeď už chápu, proč se poslední kočka Terezka (tohle jméno se po dnešku na ni nehodí, vymyslel jsem za tu půlhodinu úklidu daleko jiných, "hezčích") nechala tak v pohodě chytit. Našel jsem jednu louži pod postelí. Pak druhou a samozřejmě, jako nemůžou být rybníky páně Voka po jednom kousků, tak i zde bylo nalezeno poslední Bodamské jezero.\r\nKočky všech zemí! Nepřejte si mě!');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(295, '2019-03-18 10:25:17', 'Nesnáším, co nám určuje dnešní žití. Honíme se za penězi (o kterých si stále myslím, že jjsou nejhorší vynález lidstva) nebo jsme unavení, když přijdeme z práce. Nemocný člověk raději nějak vstane z postele a neříká, že by se měl uzdravit. Letí totiž hned do práce, protože to je to, co právě potřebuje k tomu, aby byl on i jeho rodina spokojená, najedená, účty zaplacené.\r\nNaproti tomu jsou tu děti. Bez starostí dospělých. Největší tragédie je, když se jim rozbije hračka nebo si odřou koleno. My v tu chvíli musíme stát při nich. Pohladit, pofoukat, spravit hračky, popovídat si.\r\nNěkdy to však nejde. Když si dáte oba horní odstavce dohromady, už to nejde skloubit. Nemůžete být na více místech. To pak člověk ztrácí nervy. Samozřejmě, dítě neví, že to stojí na vás. Musíte zaplatit elektriku, aby si mohlo dítě večer číst, nebo dívat na televizi. Aby mělo stále ohřátou vodu na koupání a podobně. Nám už zase uniká svět dětí. Spadla z nás ta deka, ten bunkr fantazie, které si naše děti berou kamkoli. Už na nás svítí jenom modré nebe a zářivé slunce nebo měsíc. Děti ale vedle měsíce vidí letět třeba slona. Zvedli jsme my někdy teď hlavu nahoru a řekli větu, kterou jsem si přál ríkat jako teenager svojí holce? \r\n"Podívej se, padá hvězda! přej si něco!"\r\nKdyž se nad tím vším zamyslíte, přijde mi na škodu, nezkusit vytvářet podmínky pro sebe i pro naše děti takové, aby ani jeden nestrádal. Chápu, nedá se to hned udělat a stojí to úsilí. Nekdy to ani nikam nevede. Třeba včera jsem se připletl k tomu, jak by to mělo asi fungovat: Dvojčata si hrála venku s kamarády a už byl čas na večeři. Jdu je zavolat. Žadoní, že prý ještě chvilku (5 minut je pro ně 5 hodin :D). Když najednou křik. Emča má sedřenou nohu. Nerozčiluji se. Nechám ji sice doskákat až ke dveřím, ale pak ji beru do náruče a říkám: "Vidíš, Emi? Víš, proč se ti to stalo?"\r\n"Ano, tati. Kdybych tě poslechla, nemuselo se mi to stát..."\r\nJen přikývnu a nohu jsme v koupelně ošetřili. \r\nJasně, netuším, zda si z toho vzala ponaučení, že by bylo lépe nic nenatahovat a udělat to, oč se jí žádá.\r\nKaždopádně křik na děti vám akorát vezme hlasivky i iluze potomků, že vše se dá jen vykřičet. Někdy i seřezat. Ano, my jsme utahaní, nervózní, podráždění. Přemýšlíme o všem možném a to důležitější blízko nás nám uniká. Chápu, že za to nemůžeme sami. Vždyť i ten šéf, který je na vás jak pes, má doma děti. I po něm se vozí vyšší instance, ale určitě také mají děti.\r\nVíc hlav víc ví. Napsal jsem jen krátké zamyšlení. Určutě i vy máte nějaké zkušenosti s výchovou a soužitím s potomky. Zkusme proto být, jak na sebe v práci tak i doma, hodní, milí. Třeba se nám svět změní a plolne do dětského. Já osobně se o to pokouším. '),
(296, '2019-03-20 20:24:28', 'Večer se dozvídáme zajímavé zprávy. \r\nAmálka: "Mami, a víš, že mě jeden chlapeček ve školce miluje? Ale já ho nemiluju..."\r\n"To je krásný, Amálko. Někdo tě miluje, to je hezký ne?" rozplývá se moje žena.\r\n"Ano, ale já ho nemiluju! Ale budu si muset zvyknout, abych ho taky milovala..."\r\nTatínek se do toho vloží.\r\n"Počkej, Amálko, ale ty si zvyknout nemusíš, když nechceš!"\r\n"NO, NA BOTY, KDYŽ MĚ TLAČÍ, SI TAKÉ MUSÍM ZVYKNOUT PŘECE..." kotruje Amálka. '),
(297, '2019-05-19 22:21:46', 'Ahoj všem!\r\nTak jsem nějak nemohl vybrat úvodní foto. Nuže nebyl jsem troškař a i holky mi řekly, že by to tam daly všechno. Úvodku máme hotovou a teď k věci: už ne jenom maminy, ale i tatínkové blogeři mají svůj koutek slávy. Už zítra, tj. 20.5. začíná hlasování na https://www.mamablogroku.cz/tatablog/ a i já jsem byl nominovaný '),
(300, '2019-05-23 08:29:41', 'Soutěž na téma "vyhraj #tatablog2019 stále pokračuje! '),
(301, '2019-05-25 08:12:45', 'Dvojčata jsou stále se mnou na sportovním kurzu se školou a musím říct že to zvládají bravurně. Holky si včera odběhly minibiatlon (běh a střelba na cíl) a večer zakončily s ostatními táborákem (na fotce s kamarádkou Nelčou) a NOČNÍ BOJOVKOU. Emca se v lese vůbec nebála, a protože jsme šli podle světýlek, přirovnala to k Jeníčkovi a Mařence '),
(302, '2019-06-01 13:16:34', 'Dneska už od rána na Den dětí hraju svatbu '),
(303, '2019-06-11 12:22:17', 'Zvou mne na vyhlášení výsledků. Super. Jak to ve světě blogu a influencerů bývá, když tam nebudu, moje smůla a prezentace na bodu nula (tak jasně, tady na insta si tu tisícovku sledovatelů můžu nakreslit leda rukou na screen obrazovky), ale posuďte sami, co bych byl za otce, když 18.6., kdy se vyhlášení koná, mají naše dvojčata: od 16:00 závěrečný tanec od úžasné lektorky @gradlover (jenže ten musíme vynechat) PROTOŽE v 16:30 je rozlučka skolky s vystoupenim (a už takhle se holky s nimi nefotily, protože jsme byli pryč...) a do toho vyhlášení v 17:30 @mamablogroku jako #tatablogroku2019 Vím, co má být - být s dětmi. Užít si toho jejich štěstí a radosti s nimi. Od toho tu jsme. Jsme tu pro ně. Blog mám, abych dal radost a někdy i ponaučení, zkušenost nebo řešení vám ostatním. Vím, že blogeři jsou jako auta - nenaliješ benzín, nejedeš a pojede jiné auto. Ale k čemu mi je 100k followerů, když večer, jak půjdu spát, mě osobně v mé duši nebude nic zapsáno, protože jsem ten den a tu radost s dětmi neprožil..? Vím ale i to, co se musí, pokud tu radost chci předávat dál - jít na vyhlášení. A teď fakt jdu najít nějakou hodnou stařenku, protože TEĎ, BABI, RAĎ (to "babo" mi tam k tomu moc nesedí '),
(304, '2019-07-07 21:34:35', 'Na prázdniny je dobré mít nějakou knihu stále po ruce. Třeba tehdy, když chcete odstranit dotěrný hmyz. Nebo byste rádi lehké (jen 160 stran) čtení k vodě, do vlaku, v kanceláři... Tak zde, pokud ještě někdo nemá ve sbírce, má kniha Dvojčata na útěku. Je to počátek všeho, než začal tento blog a dovolil jsem si to psát po večerech (přes den jsem se na rodičovské věnoval holkám). Je v tom spousty legrace a celé je to od začátku do konce pravda '),
(305, '2019-07-08 19:16:50', 'Seznamte se, jsem první člověk, co usnul za vteřinu za volantem na semaforech , když jsme jeli dnes z výletu v Praze. No co, ta červená trvala hrozně dlouho '),
(306, '2019-08-20 08:27:47', 'Dětem nyní zakryté uši.\r\nJája vařila. Dívám se do hrnců a říkám, co to bude?\r\n"No, tak co myslíš?" ptá se mě žena.\r\n"Vajíčka... Tady je bobkový list a nové koření..." přemýšlím. "Rajská? Koprovka!"\r\n"Ne, no tak... KU..." chce nápovědět Jája.\r\nChvíli ticha.\r\n"KUrva, já nevím..." rezignoval jsem.'),
(307, '2019-11-02 22:24:28', 'Viděli jste někdy komediální seriál Raymonda má každý rád? Teď se na to s Jájou a dvojčaty díváme. Myslím, že bych si měl taky natočit nějaký KOMEDIÁLNÍ SERIÁL. Taky jsme vtipný. Tedy aspoň si to myslím. No tady na blogu to není moc vidět (tady jsem nejúspěšnější blogger ve ztrácení sledovatelů :D) \r\nCo vy? Sledujete nějaký SITKOM? Máte oblíbený? Třeba si ho pak pustíme na doporučení... '),
(308, '2019-11-10 21:27:10', 'Týden tatínka dvojčat: \r\nDvojčata dosáhla čtyřleté mety tak rychle, že kdyby se tou rychlostí cestovalo, můžu jezdit pro banány do New Yorku. Mluví, myslí, vymýšlejí. \r\nPondělí: \r\nJe sedm. Jakási rozcuchaná hlava vykoukla k nám do ložnice. Pak druhá. Hurá, vstáváme. V kuchyni vyndávám z chlebníku růžového poníka. Směju se tomu. Je to tak od dětí milé. Při jídle trochu drobí. Nevadí, tak to pod nimi vyluxuji a vytřu. Ty naše dvojčata se tak krásně při hře smějí. Mám rád dětské hlásky. Oběd prý není podle jejich gusta, ale po půl hodině přesvědčování tu studenou krmi snědly. Přisuzuji to spíš konečnému dostavení hladu. Doposud po každém upozornění chtějí maminku. Chápu jejich odloučení, taky už si svou ženu přeji doma. Večer se jim nechce tak rychle spát, jak jsem si zprvu představoval. Nekonečno otázek s nekonečnem chtění na záchod. Poprvé jsem použil vyhrožování, ale ti malí teroristé to se smíchem přešly. V manželské posteli přemýšlíme, co by je navedlo na tu správnou cestu andílků v domácnosti. \r\nÚterý:\r\nDocela jsem se dobře vyspal. Je sedm a už se moc těším, co budeme s našimi dvojčaty dělat. Vykoukne jedna hlava do ložnice, druhá hlava i s trupem za velikého křiku přilítne na můj pupek. Trochu to bolí. V bezvědomí jsem byl jen pět minut, dobrý. Dvojčata zatím nic nerozbila ani neroztrhala. Obě sedí na mě. Setřesu je a naháním do koupelny. Vida. První ranní hra na honěnou. V kuchyni vyndávám z chlebníku růžového koníka až po čtyřech minutách. Zasekl se tam, mezek. Trochu mne to rozhodilo, ale hned, jak přijdou děti na jídlo, jsem hned klidný. Dvojčata kreslí a už jsem třikrát řešil malé přestupky v tahanici o tužky. Doufám, že se co nejdříve uklidní. Beru to s rezervou a nechám si je to vyříkat mezi sebou. Pak už jen řeším kousanec u jedné a škrábanec u druhé. Ale hezky kreslí. Při obědě jim zase půlka spadla na zem! Takhle se přeci jídlem neplýtvá. Ale zametu to. Už jsem je několikrát upozornil, že zlobení do naší rodiny nepatří. Chtějí maminku. Já chci klid. Odpoledne jsme na ně oba, ale stále si připadáme v oslabení. Jsou opravdu jen dvě? Večer jsem čtyřikrát navštívil pokojíčky dcer, ale už nemám sílu jim neustále vysvětlovat, že se má jít spát. Výhrůžka čertem nebyl dobrý nápad. V noci jsem k nim vstával asi pětkrát. Z toho hodinu u jedné z nich spal, protože se bála. \r\nStředa:\r\nJe sedm. Zjistil jsem to, protože na mě přistála jedna z dcer, druhá krouží kolem postele a něčemu se směje. Hned je posílám do koupelny a hrozně se mi chce spát. Nemůžu. V kuchyni doluju růžového koníka z chlebníku. Sakra. Jsou tam dva. Druhý je fialový. Trvá mi to asi deset minut. Jdeme ven, ale oblíkání a obouvání se nesetkalo s dobrou náladou dvojčat. Moje nálada s trpělivostí si už balí kufry. Dvojčata chtějí maminku, já chci, aby se oblíkly, jinak nám z dvouhodinové procházky zbyde cirka jen čtvrt hodiny. Nikdo nechce ustoupit ze svých požadavků. Začíná vyhrožování čertem už v poledne. S obědem si na mne nepřijdou. Je takové jídlo, které jim chutná a měly by ho sníst hned a nic nevyhazovat z talíře na sebe nebo podlahu. Bože! Je tam zase nastláno! Nutím je si to po sobě uklidit. Chtějí maminku. Ptám se, jestli spíš nechtějí čerta. Odpoledne jedeme spolu všichni nakoupit. Dvojčecí slib poslouchat a být hodný se vytratil hned po výstupu z auta. Obchody jsou totiž jedna velká prolézačka a honit se mezi regály je ta pravá adrenalinová zábava. Jako by tušily, že se nám příčí zvednout hlas mezi lidmi. Skupinka Japonců si po půlhodině zvědavě fotí rituál rodičovské výchovy minulého století s finálním naplácáním na zadek za mohutného křiku malých teroristů. Doma se situace vyostřuje jak v námořní bitvě. Zvednul jsem několikrát hlas. Za to mi moje hlasivky nepoděkují. Mám podezření, že dvojčata v obchodě sebrala špunty do uší. Musím koupit amplion. Večer vytíráme se ženou potopu v koupelně a já už jsem přešel na modlení, aby obě naše děti usnuly rychle. Po šestém pokusu se buď napít nebo vyčůrat přemýšlím o rozbití záchodu i všech umyvadel, aby se na něco konečně mohl vymluvit. Strašit čertem je nebudu, chci se vyspat. Ok, čert přichází za dvě minuty. Emča ho chce i ukázat. V noci jsem byl jen jednou vzhůru. Měl jsem strašidelné sny. \r\nČtvrtek: \r\nRáno. Ještě to tu spí. V klidu si dojdu na WC. Omyl. Jsem přepaden i tam. Počítám, kolik mi tenhle den odumře nervů. Z chlebníku se už toho odporně růžového koně ani nepokouším vyndat, jinak bych musel chlebník rozbít. Chci tu ženu. Aspoň na půl hodiny. Ta havěť tu jen ječí a piští, smích je jak skřípání nehty o tabuli. Oběd bych zrušil. Vůbec si ho nezaslouží. Stejně půlku studeného jídla zas vyhází na zem, ale už mám donucovací prostředky. Chtějí maminku. Když maminka přijde, pro změnu chtějí tatínka. Já zrovna nechci je. Aspoň to studené kafe v pěti minutách klidu si můžu vypít. Poslední hodiny do spaní zaznamenávám všude, kde jsme jen pištění, vřískání a sliby, že už budou hodné. Ano, hodné jsou, když spí. \r\nPátek:\r\nJe krátce po šesté a já mám pocit, že s přibývajícími dny jim energie spíše roste. Einstein by měl radost. Já radost nemám. Jediné, co mám, jsou červené oči a dost pochroumané nervy. Růžový poník, fialový poník, mořská panna a ovladač od televize, které jsou v chlebníku, letí rovnou do popelnice, protože tohle už teda fakt neotevřu. Kreslení je super, ale jediná velká tečka jedné z umělkyň na padesáti čistých papírech je i na můj vkus hodně. Oběd sem psát nebudu, musel bych se vypípat. Dochází mi argumenty, vzpomínám si na protiteroristickou příručku. Je taky k ničemu. Večer vyndávám z pračky další koně. Sakra, kde je zase vzaly? Pohádka je jen o hrnečku, co vařil. V posteli usínáme se ženou po první reklamě. Přes víkend zkrátka tu sílu zase musíme nabrat.'),
(309, '2019-11-20 20:51:49', 'Volám Jáje. Zvedne to Emča a říká úlisným hlasem:\r\n"Ahoj, miláčkuuu..."\r\n"Nazdar Emí, nech toho a dej mi mamku..." říkám.\r\n"Dobře, tak jinak," odpoví dcera a dodává, "jsem jako tvoje žena- Co je zase?" \r\n"Jenže tohle odpovídá maminka vám, kde jí voláte po padesáté..." odpálkuju rychlou odpovědí a už se trochu začínám smát. "Dej mi mamku!"\r\nV telefonu to zaškrábe a znovu totálně úlisným hlasem zazní věta: "Není tadyyyy, odešla s pooošťááákem..."\r\nA tak si tu žijeme. Ani vlastní ženě se už člověk nedovolá.'),
(310, '2019-12-02 08:38:02', 'Více také najdete na FACEBOOKU a INSTAGRAMU pod názvem DVOJČATA NA ÚTĚKU :)'),
(311, '2019-12-05 22:50:35', 'Čert s Mikulášem. \r\nChtěl jsem tu napsat nějaké moudro na to, zda strašit děti nebo ne. Pak jsem si uvědomil, že my žijeme v permanentním stresu a strašení, abychom nepřišli pozdě do práce, jinak nám strhnou prémie, aby se stihlo to či ono. Aby maminka nepřipálila oběd. Aby tatínek dobře zatloukl hřebíky... A vůbec k tomu nepotřebujeme ani Mikuláše a máme to celý rok. \r\nTakže NO STRESS :D \r\nU nás to bylo jako rychlá prohlídka hradu. Zvonek, bububu, kde jsou dítka, kuk, tady jsou hříšky. Pojď sem a řekni básničku. Tak, a jsi vykoupeno. Zas na rok zůstaneš rodičům na krku. Šup panáka, šup ven. Za rok haleluja! Ve jménu otce, mamky a dítek nehodných, amen.\r\nVeselého Mikuláše. Čerty, ty potkáte na silnicích. Snad nás v noci budou hlídat.'),
(312, '2019-12-11 22:49:57', 'Krátký status:\r\nJako správný bloger a influNĚCO na vás taky zapůsobím. \r\nZa chvíli budou Vánoce (no jako fakt, už jen pár dní :D) a tak půjdu příkladem a nebudu FB nebo Instagram zahlcovat každodenními posty, co zrovna děláme a proč to děláme. Přeci jen budu s Jájou třeba ještě kupovat dárky, zajdeme do kina s dětmi nebo na vánoční trhy :) Užijeme si to. Užívejte také. O tom to je. \r\nP.S. Neodpustím si - za 12 dní tu jsou Váááánoce - jupí!'),
(313, '2019-12-17 12:38:12', 'Sice to nevypadá na Vánoce se sněhem, ale i tak, až mne UVIDÍTE, ŽE TANCUJU NA CHODNÍKU BREAK DANCE, přejděte na druhou stranu. Zcela určitě mám pod nohama náledí...'),
(314, '2020-03-13 11:16:26', 'Vydržel jsem s dvojčaty na rodičáku přes čtyři roky. Teď si myslím, že s nimi ten měsíc asi nedám. Raději krotit třídu deváťáků.'),
(315, '2020-03-15 17:53:56', 'Neděle. \r\nU nás dobrý. Dvojčata se ještě nezabila mezi sebou a ani my, kupodivu, nejsme jakkoli rozložený. S Jájou sedíme sem tam na internetu kvůli hlášení od vlády a já při tom dělám stránky pro mé žáky II. stupně ZŠ, aby si mohli zopakovat nebo dál učit zeměpis (chichi, nedám jim pokoj) a při tom ještě vymýšlím, jak se všichni zabavíme (klidně beru další možnosti a doporučení i od vás). \r\nJeště jsem si, jako učitel, ani nenalil víno (jak tu někde na FB bylo zmíněno) :D :D\r\nP.S. A co vy? Doufám, že u vás je to všechno v pohodě.'),
(316, '2020-03-20 19:21:06', 'Zjištění týdne: Nezmizela mi ni jedna láhev vína, ni jedna láhev rumu. Jako fakt!'),
(317, '2020-04-02 11:51:42', 'Jasně, blogger má volno a jeho jedinou náplní je vymýšlet, co za fotky nebo příběhy postnout na zeď facebooku nebo jeho stránek. OK, zase jsem jiný :/ zajímavý, že na to buď nemám čas, náladu nebo jsme totálně obyčejná rodina jako každá druhá na Zemi. Takže vlastně asi žádný blogger nejsem. Hustý zjištění.\r\nVlastně je to jako skoro v každé rodině v tomhle stavu - s dětmi se od rána učím jak v televizi s vysíláním pro školy, tak pak, co máme v učebním plánu na tento týden. Pak si zasednu vyřídit svou práci pro moje žáky, napíšu pár mailů, zkouším se dokopat i k mému sebeučení (spíš trýzňosebeučení), nakonec si jak mladý tak starý pustíme nějaký film z Netflixu (jasně, už na něj došlo, protože TV jinak vysílá samý Esmeraldy nebo miliony pořadů o vaření) a pak už jen večer a spát.\r\nP.S. Sem tam si dopřeju, kdo znáte, i Lucifera - a fakt je to dobrý!\r\nP.P.S. Držte se.\r\nP.P.S. A klidu.\r\nP.P.P.S. Že všechny zdravím!'),
(318, '2020-04-12 11:15:18', 'Někdy mají "svůj den" dvojčata už od rána. Neustálé hádky o všechno, možná i o lepší světlo ve svých pokojících. Pokračování následuje i u ranní snídaně. Dohady nekončí, otec začíná být na svým soustem lahodného chleba se sýrem nevrlý. Rozčísne atmosféru milionů slov svých potomků:\r\n"Tak už dost! Teď jíme a bude tu ticho! Jsem váš IMPERÁTOR!"\r\nVteřina ticha znehodnotí Emčina otázka:\r\n"Co je to OPERÁTOR?"\r\nJája se dusí svým soustem...'),
(319, '2020-04-22 10:16:31', 'Dvojčata se zcela vymkla kontrole. Ráno si připadám jak v pavilonu opic. Dopoledne mi to přijde stejné, jako při vyučování tělocviku 30 adolescentů v tělocvičně, která má brutální akustiku. Po poledni to vypadá jako nálet bombardovacích letadel, jen nevybuchují bomby, ale moje a Jájiny nervy. Večer... jsme zjistili, že se připlížily k jedné do pokojíku a tam nerušeně až do těžké noci vesele společně, ale kupodivu potichu, aby nás nerušily, dováděly...'),
(320, '2020-04-26 18:32:45', 'Včera nám shodou miliónů náhod utekly z domu obě fenky. Když jsem je honil, sousedi se mne ptali, zda honí tu motorku, co kolem projela. \r\n"Ne, to byl cyklista...." ufuněný odpovídám.\r\nTeď mi to dochází... doufám, že vám taky.'),
(321, '2020-05-10 08:50:49', 'V českých slovech je někdy krásný ZMATEK, když třeba dnes přeje ten, kdo vyšel Z MATEK, ke dni MATEK. Vše nejlepší, maminky!'),
(322, '2020-06-23 13:26:44', 'Čteme. \r\n"Ráno ZAKOKRKAL kohout." \r\nJá se pokrkám smíchy. Ještě, že to neslyší paní učitelka.'),
(323, '2020-07-20 11:00:34', 'Sledujte naše příběhy na FB - Dvojčata na útěku. Jsme také na Instagramu - Dvojčata na útěku, kde jsou i jiné fotopříběhy :)'),
(324, '2020-07-22 10:07:48', 'Dětské hry. Můžete hrát člověče, nezlob se, dostihy a sázky nebo moderně na telefonu pexeso, rychlostně pohotovostní hry typu "chyť tu rybu dřív než protivník" a tak všelijak podobně. Holky mají ve svých telefonech nainstalovanou asi už třítisícousemdesátoupátou hru pro děti, avšak využívají jen asi tři, k tomu je to drží tak půl hodiny a pak jdou raději ven na koloběžku. Tuhle jsme hráli zrovna nějakou hru jako dětskou olympiádu, kde máte několik kol a snažíte se třeba předběhnout protivníka, a to všechno díky zvířátkům, které si vybereš. Já si vybral hezkou stračenu. Když jsem s ní vyhrál už asi třetí hru, Amálka na mne uznale koukne a řekne:\r\n"Teda tati, ty jsi ale dobrá KRÁVA!"'),
(325, '2020-10-15 10:13:04', 'PROČ děti, když jdou do školy, nechtějí vstávat a když je distanční výuka, tak mi tu lítají už od půl sedmé? Tvl, co je to za senzor a v jakém sektoru ho najdu?'),
(326, '2020-11-01 19:07:35', 'Překvapení č. 2\r\nTímto dnem se z nás stali praví vesničané. Krásná víska s přibližně tisíci obyvateli nedaleko Labe a snad milionem koní kolem dokola '),
(327, '2020-11-18 18:43:39', 'Začínáme v matematice PŘÍMKU. Holky mají za úkol namalovat přímku "k" a na ni bod N. \r\nAmálka narýsuje. \r\nPtám se: "Amálko a jak se ta přímka jmenuje.... ?"\r\nAmálka: K.... KŘIVÁ?'),
(328, '2020-11-23 09:10:21', 'Krááásné pondělí!\r\nCo si víc přát, než když vás v pět vzbudí veškerá havěť (dvojčata ne, ta ještě v tu dobu tvrdě spí) v domě. Zvracející kočka? Není problém, utřu a čekám na devítku, až otevře veterinář. Prdící kočka, která si vybrala nejbližší záchod, aby nám udělal dobrý odér v ložnici? Není problém. Jen čekám, sakra, už na ty zbylé dveře do pokojů, abych se konečně mohl na noc zavřít. Fenky, které projedou misky koček a pak se mi div málem nenakvartýrují do postele místo Jáji, která právě odjela do práce? Není problém, táhnu je jak pytel uhlí ven, protože odmítají použít svoje nožičky. \r\nJo, den začíná dobře.'),
(329, '2020-11-29 12:22:32', 'Krásný první adventní týden. \r\nPrávě jsem zjistil, že jak pořád makáme na baráčku, aby se tu dalo důstojně bydlet, tak jsme nekoupili ani svíčky na adventní věnec. Takže za chvíli jdu na tu kupu pytlů a krabic hledat staré adventní svíčky, které jsem si prozíravě nechal '),
(330, '2020-11-29 22:02:04', 'Zítra je poslední listopadový den a protože už hoří první adventní svíčka, začíná mi melancholicky nostalgicko romantická nálada. Neříkám, že všichni, ale mnoho tváří se změní a jejich oči se víc třpytí. Je to možná vánoční výzdobou nebo prvním svařákem s přáteli. Stejně si však myslím, že někteří zkrátka podlehnou kouzlu Vánoc a změní se na opravdu dobrého člověka. Přál bych si, aby Vánoce byly celý rok. Aby postupující nálada, která graduje na Štědrý večer, mezi námi byla celých 365 a čtvrt dne.  Mám rád Vánoce. Ne pro spousty dárků a neustálého shonu, ale pro zajímavou, zlatě oděnou náladu. Pro tu atmosféru. Pro ty vzpomínky. Pro pohádky, které se mohou stát skutečností. \r\nKrásný adventní čas a nejen ten.'),
(331, '2020-11-30 13:44:12', 'Zpátky ve škole. Jupí, tak jdeme učit. 8. třída a zeměpis. Máme Hospodářství ČR. Tak trochu úvodu. Dostáváme se až na 18. potažmo 19. století a průmyslovou revoluci. \r\nNostalgicky vzpomínám na film Marečku, podejte mi pero a jako správný učitel se dětí ptám:\r\n"Tak, děti, a jak tedy říkáme v průmyslové revoluci 19. století?"\r\n- nikdo neví, tak napovídám s přímou ukázkou kmitu ruky jako parní lokomotivy (š-š-š-š-š-š-š-š-š-š-š) -\r\nJeden žák se přihlásí:\r\n"Já vím! Století ŠIKANY!?" \r\nAha, no tak o tom nemám ani PÁRU...'),
(332, '2020-12-03 22:32:44', 'Jako naše Amálka by z fleku mohla tvořit kód Enigma II. Jedeme autem domů ze školy a že si chce zahrát hru. Pravidla jsou jasná. Budeme hádat zvíře. Tak začíná:\r\n"Má to balkón..."\r\n"Počkej, Amálko, ale ŽÁDNÉ zvíře nemá balkon."\r\n"Má tati, hádej! Má to balkon a ruce skrčený a i nohy silný jako Tyrannosaurus Rex."\r\n"Hele, to je divný... nevím."\r\n"Má ještě uši jako zajíc!" pokračuje zcela vážně dcera svoji naprosto pro mě nelogickou hádanku.\r\nTak jako co? Hledám odpovědi, ale brzdí mě tam pořád ten balkon. BALKON? \r\n"Já nevím..." řekl jsem až po pár kilometrech, kdy se holka na zadním sedadle už docela chichotala. \r\nA tak se ptám vás. Je to ZCELA LOGICKÁ hádanka (někde v levelu IQ 140 + 50 tisíc rádců): CO JE TO ZA ZVÍŘE?  \r\n>> Má svůj balkon, ruce a nohy jako T- Rex a uši zaječí? Kdo to uhádne a koho to rozbrečí?<<\r\nŘešení nabídnu v dalším postu.'),
(333, '2020-12-11 19:14:41', 'Milý Ježíšku,\r\njako každý rok Ti píšu, tak nevynechám ani tento. Vím, že ty dopisy jen přelítneš. Přeci jen je jich hodně. A tak stručně, věcně a vážně jen pár vět. \r\nJakožto dospělý, jsem celý rok psychicky nevyrovnaný, ale je to tím, že se buď nevyspím, nebo se řeší ty dospělácké problémy, co děti nezajímá, protože děti žijí v přítomnosti, ale my musíme myslet na budoucnost a hrabat se v minulosti. Takže jestli jsem někdy zlobil, určitě jsem to nemyslel zle. Přál jsem si hodně věcí, ale chápu, že jako malý nejsi schopen uzvednout tak těžké nebo velké věci a tak se můj seznam zúžil jen na pár malých přání: Zdraví - no jasně, nejsi doktor a jak se říká, příroda léčí, doktor uzdravuje. Takže vlastně jen aspoň další rok ponech v přírodě vše, co je pro nás všechny prospěšné. Lásku - někde je jí hodně, někde není žádná. Hele, to bys měl trochu vyvážit, ale ty to jednou dáš, to Ti věřím. Štěstí - každý má štěstí v něčem jiném, ale není hmotné. Vlastně má každý to své štěstí před sebou. Ale někomu bys mohl pomoci ho probudit, pokud mu spí. \r\nTřeba mi ještě k tomu něco přibalíš. Znám Tě, jsi to šprýmař jeden. Takže s lehkou nadsázkou nadělíš i něco navíc. Předem dík, ale hlavně díky, že jsi nás i letos nevynechal a nenahradil tě třeba ten děda, co jen užírá sušenky a srká mléko. Zase se na Tebe těším, ty kluku malej, i když já už jsem dávno vyrostl  ;-)'),
(334, '2020-12-15 20:04:28', 'Ještě dva dny nás dělí od týdenního půstu teplé vody a topení. To je tak, když si na zimu musíte vyměnit kotel, který ale musí spustit revizák, který má čas až za týden. Ovšem, když mu náhodou kominík zavolá, že zda by mu neoplatil službičku a nedojel sem dřív (protože aspoň ten kominík to řešil), znamená to, že dorazí ve smluvený termín o týden později. \r\nNo co. Přímotopy jedou, já si neodpustím denní dávku sprostonárodního žargonu na téma teplo či zima, dvojčata se umyjí v kyblíku teplé vody a my taky a jsme všichni spokojeni. Jak na chalupě. Akorát, že tu bydlíte nastálo :D :D :D \r\nŠkoda, že není sníh. Mohli jsme skákat v plavkách do závějí.'),
(335, '2021-01-24 21:28:21', 'Jak jsme si objednávali bazén.\r\nDvojčata milují vodu. I sníh. Mlhu nesnáším já, protože není nic vidět. Ale ať je voda v jakémkoli skupenství, informace, že dvojčata milují vodu, je na místě. Takže co uděláte, když vaše dítko má rádo vodu, potažmo koupání a vy nemáte bazén, abyste mu dopřáli trochu toho cákání v horkých letní vedrech? Jdete si jej objednat. Právě mají slevy. Super. Jedeme s Jájou do obchodu, kde kde nám nejznámější zahrádkář prodá, co jen budeme chtít (o tom až dodatečně).\r\nVejdeme do obchodu a mimo čtyřek prodavačů tam není ani noha. Je to jako v tom americkým detektivním seriálu, když na benzínku přijede zamilovaný pár a kluk rozesmátý tankuje, zatímco rozvášněná holka jde koupit nějakou tu ledovou Colu pro svýho týpka, aby ho schladila. A všichni se na tý pumpě na ně dívají... Tak takhle to vypadalo i s námi. Akorát my chtěli bazén. Ochotný prodavač ve středních letech, který trochu vypadal spí jako poslední zapomenutý ajťák než jako vedoucí sekce motorových pil, ale přežvykoval pod rouškou jako zdatný hokejista v první třetině zápasu, takže jsme mu věřil, že to dá, se nás ujal. Ochotně, jako vilný prodejce multi level marketingu, nám pomohl vybrat všechny nezbytné součásti na bazén (ale stejně jsme nakonec zapomněli na plachtu). Jo! Jenže teď to přijde:\r\n"Tak, máme hotovo. Ale vy si ho tady nemůžete koupit..."\r\nZdálo se mi, že se pod rouškou dokonce zašklebil jako Clint Eastwood. Naštěstí ale pokračoval. "Já vám dám tenhle štítek a vy si zajdete všechno vyřídit na pokladnu."\r\nJasně, na pokladně se platí, to nebude problém. \r\nBYL. "Podle nařízení vády... blablabla... musíte zboží objednat telefonicky. .."\r\nNebudu zdržovat dychtivé čtenáře, a tak jen názorný sled událostí:\r\nPokladní: "Vy mi jako zavoláte na tohle číslo a já vám to jako napíšu na eshop a vy si jako pro to přijedete..."\r\nTak jasně, mám školu ochotnického divadla, to svedu. \r\nDala číslo, já volal, objednal a měl jsem při tom ještě takové ty prima hlášky, jaký se dávají všem do call centra, abyste odlehčili situaci. \r\nPoslední věta prodavačky: "A kdy si pro to k nám zajedete?"\r\nJá zkušeně: "Noooo, mám to k vám tak půl hoďky... to máte ještě otevřeno, ne?"\r\n"Jasně, díky," cvak, telefon se položil a pokladní se ohne pod pokladnu v křečovém smíchu. "To mi doma neuvěřííííí..."\r\nNo, jak se zdá, nám asi taky ne. \r\nP. S. Bazén objednaný a zaplacený. Přijde až v polovině února :D\r\n\r\nJo, doba je zlá.. fakt :D'),
(336, '2021-02-03 20:48:23', 'Co napsat. Je toho tolik, že byste to hltali, pak mi dali miliony lajků a tisíce sdílení...\r\nStačí se zmínit, že je tu další etapa předělávání vnitřku domu a místo vany se koupeme v dětské vaničce '),
(337, '2021-02-22 22:00:28', 'Tak mě tak napadlo, nechce někdo mít něco jiného než tu jedinou současnou nemoc? Klidně pošlu trochu té mužské rýmy '),
(338, '2021-02-25 21:47:44', 'Milé děti. \r\nJe rok 2021. To je rok... ale to je jedno. Chtěl bych vám vyprávět o některých skvělých věcech, které vaši rodiče dříve užívali. Chtěl bych vám to vyprávět tak, jako to kdysi dělali naši prarodiče, když vzpomínali. Ono, nemyslete si, stačí krátká doba (kort těm, co dost hulí) a na všechno se zapomene. \r\nJak následně se nyní stává reálné české přísloví: Sejde z očí, sejde z mysli.\r\nKino. Jak bych vám to... no, zkrátka, máte doma určitě televizi aspoň s uhlopříčkou 139 cm a více. Tak nyní zavřete oči a tu televizi si mnohonásobně zvětšete. A máte kino. Stejně jako doma i v kině se mohlo jíst (hlavně to nezdravé, ale dobré '),
(339, '2021-03-14 20:44:37', 'Láska existuje, hranice nemaje. Lidi, dnes jsme se s Jájou rozněžněli jako Helenka Růžičková. Viděli jsme na parkovišti, jak jeden kluk přišel k dívce a protože umím odezírat ze rtů, říkal jí něco na způsob toho, že se mu líbí a jestli by nemohl dostat číslo. A ona mu ho dala a ten úsměv, který vyl vidět, ozářil celé parkoviště '),
(340, '2021-03-28 22:37:22', 'Jediné, co mě zaujalo na sčítání, bylo číslo odeslaného formuláře: 1050000 :D'),
(341, '2021-03-29 21:56:11', 'Psal jsem dlouhý status o tom, že se naše čuby do sebe pustily. \r\nAle je to spíš pláč na cizím hrobě. Dám si panáka a poprvé (!!) napíšu, že se z toho nepos*** a uvidím, co bude dál. Hlavně všichni klid. Domácí čovidní vězení nám (mi) už asi leze na mozek. No, zítra tu sem dám asi nějakou fotku roztomilého koťátka, abych zase nasbíral trochu víc lajků...'),
(342, '2021-04-15 23:15:40', 'Barák nám obsadili Pokémoni. Myslel jsem si, že to umřelo s rokem 2000. Nějaký vtipálek to pak asi našel a díky chytrým telefonům se to rozmohlo jako hledání kešek. Teď to dvojčata drtí  na Netflixu a dneska dorazil druhý Pikachu (jasně, jedna nejdřív nic nechtěla, ale nyní ho mají obě).\r\nRáno vstaneme, piští to jako Pikachu.\r\nOdpoledne jíme oběd, piští a mluví to jako Pikachu.\r\nVečer už mám žluto před očima a zase to doma piští jako ten vražedně elektrizující žlutý ďábel. \r\nTakže: pika pika a následně pika pika pika! Čůůůůůů(s)'),
(343, '2021-05-06 20:25:08', 'Jsem i muzikant. Někdo to ví, někdo ne, ale teď to zkrátka musím říct. Má to totiž návaznost. \r\nJája totiž v práci kolegyním říká že už se blíží čas, kdy zase - třeba na svatbách - zahraju a zazpívám. \r\nJedna kolegyně se jí zeptala: "A s kým hraje?"\r\nJája: "Hraje sám."\r\nKolegyně (asi pořádně neslyšela): "S kým, že to hraje?"\r\nJája: "SÁM!"\r\nA kolegyně jen k tomu pronese: "AHA, TAK TOHO NEZNÁM."\r\nMožná ještě teď se všichni válí na zemi smíchem a já zakládám uskupení nové kapely jednoho muže. Na plakátech mě můžete najít pod názvem kapely "SÁM." '),
(344, '2021-05-11 22:32:01', 'Můžu někomu na několik dní půjčit dvojčata s tím, že by psal za mě, co se nám tu událo? J totiž teď tak nějak hodně nestíhám a i kdybych chtěl, nejde mi sem všechno napsat a nestíhám ani fotit... :D\r\nTakže: Půjčím zadara naše dvojčata. Vhodná jako demoliční četa staré usedlosti. Pokud se někdo chce zbavit domácí zvěře, taktéž půjčím, jsou to dobří "deratizéři" :D Samo platí i zápůjčka na rychlejší pocuchání nervů a včasné dostání se do lázní Luhačovice :D :D'),
(345, '2021-07-04 22:42:26', 'Dnes u nás na návštěvě byl Jáji starší syn se ženou a vnučkama. No jo, jsem taky mimo jiné děda, že jo '),
(346, '2021-07-27 10:01:41', 'Naše prázdniny se dají definovat filmem Pásla kone na betóne... Holky byly zatím jen na příměstskému koňském táboře a já jsem stále betonující v holínkách. A co váš prázdninový film?'),
(347, '2021-08-30 00:13:53', 'Už víme, proč je Emča tak malá. Amálka nám to vysvětlila: Je malá, protože lež má krátké nohy a jelikož Emča furt lže a lhala už i v břiše maminky, tak jí nenarostly. '),
(348, '2021-10-19 12:05:33', 'Objednali jsme si balík. Stál docela hodně. Přesně tedy 3088,- Doposud dobrý. Jenže DPD jezdí na poledne, a to nejsme nikdo doma. Dvojčata doma byla. Jaká úleva, že Emča pohotově vše dokáže vyřídit. Nechám jí víc, aby se tak nemusela trápit s počítáním. Přeci jenom to je před několik tisíc a holky chodí teprve do 3. třídy. Telefon s kurýrem proběl dobře, Emču mi pochválil, jak dcera balík pak převzala a zaplatila. \r\nPřijedu domů, balík leží na stolku a peníze taky. Jenže namísto drobných na balíku leží pětikilo. \r\n"Emi? Kolik stál ten balíček? Neměl ti pán vrátit méně?"\r\n"Já nevím, tati. Pán mi dal tohle, že si to mám nechat, že nemá nazpátek."\r\n"Ale Emi, to by ti nechal hodně..." oponuju, načež mi dcera s rozverností v hlase a úsměvem od ucha k uchu řekne: "To bude asi tím, jak jsem šikovná a rozkošná..."\r\nNo, sakra...\r\n\r\n\r\n\r\nP.S. Tímto se pánovi z DPD omlouvám a pokud to čte, tak až si zase objednám balík, dám mu i velké dýško :)'),
(349, '2022-01-02 12:30:10', 'Včera jsme měli den pro sebe. To jen na omluvu, že jsem slíbil napsat prvního, ale zkrátka to nevyšlo. A myslím, že to i chápete '),
(350, '2022-01-08 01:23:13', 'V současné době různých rozkazů a nařízení jsme doma (už o Vánocích) shlédli film "K zemi hleď!" Čekal jsem docela dlouho na to, až se začne film rozkládat všemi směry. Čekal jsme mnoho, ale přišlo málo. Myslím, že stojí za to si film (na Netflixu) pustit (pokud jste tak již neučinili). Jenže pokud čtete recenze, mnoho deníků a internetových portálů trefuje jediné téma, a to klimatické změny na naší planetě... Každopádně - k věci:\r\nV první řadě musím říct, že za mne si Netflix střelil do vlastních řad alespoň bazukou. Pokud někdo aspoň trochu ví o televizní politice tohoto internetového kanálu, který v celku rychlým tempem přeskakuje i HBO(GO), musí se divit, že s propagací filmu a zájmem o něj (taky aby ne, když tam hraje DiCaprio a Streepová) se všude roztrhl pytel. JENŽE! Námětem a zpracováním je to zcela jiná podívaná. Kámen úrazu je v tom, že si každý (ALE OPRAVDU KAŽDÝ) najde na filmu to, co mu v této době nedá spát. Samozřejmě kromě klimatických změn. Jasně, chyběla tam Gréta a její páteční nicnedělání, ale buďme upřímní - asi by tam ani pro ni nebylo místo. Všechno totiž obstará jak Streepová v roli prezidentky, tak Rylance v roli (dovolím si říci parodií na Jobse, Gatese a Muska) Isherwella.\r\nFilm není černou komedií a možná ani ne sci-fi. Je prachprostým nastavením zrcadla (jo, už ho nastavili) dnešní doby. Bohužel s dovětkem staré Kelišové: "Velebnosti, jdu blejt..." \r\nJe mi z toho smutno a veselo zároveň. Smutno ze situací, co tam vidím a říkám si, že přeci tohle je nám servírováno denně! Veselo z toho, že se i u tak hořké "komedie" dokážu zasmát, ale také proto, že si někdo v této době, kdy se chodí po špičkách i u slonů, odváží říct věc tak, jak je, naservírovat ji a ještě za to zatleskají, i když to někteří zcela úplně stejně dělají. \r\nPakliže je tento film blízkou budoucností (přeci jen, co kdyby.. že?) doufám, že to nedopustíme. Nebo si to zasloužíme?\r\nCO MYSLÍTE?\r\nhttps://www.csfd.cz/film/906706-k-zemi-hled/zajimavosti/'),
(351, '2022-01-31 15:27:56', 'Emča rozdává jízdy na koni svým spolužačkám jak na běžícím pásu. Teď se právě dohodla, že přijede za svojí kamarádkou, aby se svezla.\r\n"Emi a odkud je ta tvoje kamarádka?"\r\n"Eeee.. z Chebu."\r\n"Hm, tak to jedině virtuálně..."\r\nBože, vždyť my bydlíme ve Středních Čechách!! Poslední kůň, co ušel štreku delší než 100 km žil v polovině 19. století '),
(352, '2022-02-01 19:53:40', 'Holky ještě nechtěly jít spát a chtěly jednu hru prší. I přes zákaz Jáji jsme si ji dali :) takže se moje žena "na oko" naštvala a řekla, že mě taky budí v půl čtvrtý, když teda ona taky vstává v půla. Emča se s ní dala do křížku (hele, je drzá - Emča - jak stepní kobyla a prostořeká jak královský šašek), že prý mi to přikázat nemůže, že jsem svobodný člověk.\r\nJája suše odpověděla: "Není, je ženatý...!"\r\nPrávě jsem se dozvěděl krutou pravdu. '),
(353, '2022-02-23 20:16:15', 'Krásný večer všem. \r\nZajímalo by mne, jaké hlášky putují k vašim dětem, když jim cokoli říkáte? \r\nMám tu jednu, kterou říkám dvojčatům, když kamkoli přijdeme: "NEDĚLEJTE NIC NEZÁKONNÉHO..!"'),
(354, '2022-03-03 06:18:47', 'Emča mě začala nazývat při hraní Prší “kocourem.” \r\n“Tak hraj, kocoure… Ty mas ale karty, kočičáku…”\r\nAsi jí ten karban zatrhnu. Asi taktika '),
(355, '2022-03-31 22:45:08', 'Proč sem nyní moc nedávám příspěvky? Inu, to je snadné - makám '),
(356, '2022-04-20 20:31:07', 'Amálka: "A tati, kočky v Británii mňoukají anglicky?"\r\nMIAOW'),
(357, '2022-05-03 14:13:59', 'Dnes Amálka pro virózu zůstala doma, a tak Emča sama se svojí třídou jela směr Praha na poznávací výlet. Jelo se vlakem. Emča s kamarádkou ve vlaku pri vystupování zůstala, ale naštěstí paní učitelka duchapřítomně zpunktovala návrat svých žáků na výbornou. Když jsem si telefonoval s Emčou, byla vysmátá a vůbec se nebála. \r\n“Tati, ty jsi víc v pohodě, než maminka…” glosovala, když jsem jí radil, co a jak dál. \r\nCo se mi vybavilo v hlavě? Jediná hláška: “Koljo, ty nikam neuběgaj a zůstaň v metro…” '),
(358, '2022-06-02 22:58:58', 'Když už něco malujete, musíte vědět, co to je :)\r\nAmálka: "Tati, český znak je sprostý?"\r\nJá: "Ne, proč by měl být sprostý?"\r\nAmálka: "Jenom se ptám, jestli je sprostý?"\r\nJá: "Je na něm lev i orlice, ale že by byl sprostý...?" Trochu zmatkuju a v duchu si znak představuji, jestli tam náhodou nemá lev pindíka :D No, trochu má, ale že by až tolik? Každopádně Emča mi přizvukuje a opakuje co tam je. Amálka však bezelstně pokračuje: \r\n"No, on byl nakreslený na chodníku a byl to DIAMANT S ČÁRKOU UPROSTŘED..."\r\nJá: "Jo, tak to opravdu NENÍ státní znak..." \r\nAch, ta představivost.'),
(359, '2022-06-14 15:08:08', 'Malá zpráva: ty jo - tak prý v mamablogu (tedy tatablog roku), jsme se - díky vám - umístili v TOPu '),
(360, '2022-06-21 14:19:38', 'Že všichni vyhlížíme začátek prázdnin, to je pochopitelné. Dvojčata, kupodivu, dostávají ještě nyní ve škole úkoly a já už stačil uzavřít známky a ano, neodolal jsem, protože Amálka byla zdrcená, že bude mít "nějakou horší" známku a podíval jsem se na jejich výsledky. Ne, není to vůbec hrozné. Ale jak říkávaly dříve babičky - hlavně, aby se naučily pro život. Tak v to doufám✌️'),
(361, '2022-08-01 22:47:14', 'Dvojčata jsou od víkendu na táboře. Holky se stihly požádat už při odjezdu i skoro u autobusu a teď, podle všech zpráv, by s největší pravděpodobnosti neměly být ani v jednom oddíle a pokud ano, tak každá v jiné chatce. \r\nMusím přiznat, že je to teď s nimi dost náročné a až si jednou tento deník přečtou, nebudou věřit, co všechno dělaly a já musel strpět. Emča nenechá Amalku napokoji a ona pak vypění. Což asi někteří z Vás znáte. Znám hodně dvojčat, ale nedělají si to, co musíme každý den zažívat my. Snad se to zlomí. Ale je to obyčejný život. Není to tsice zrovna to, co jiní se svými blogy sdílejí, ale zkrátka je někdy slunečno a někdy zataženo. \r\n\r\nTak jsem zvědavý, kdy dojde první dopis a co v něm bude. My už psali '),
(362, '2022-09-15 21:59:58', 'Tak jsem nyní tak trochu v rozkolu. Asi vrátím diplom. Témeř tři roky tu doma suplujeme školní výuku, ale výsledku ve vzdělávání jsem si nevšiml. Vlastně všiml. Dvojčata pořádně nic neumí a ve škole spíš tepou mě, že nemají domácí úkoly a nebo neumí češtinu či matiku. Nemluvě o tom, že jsem viníkem toho, že jsem z tuny potřeb pro výtvarku nekoupil ještě voskovky a tuhé lepidlo. \r\nTakže ne, milé školství. Chci, aby se moje děti naučili ZÁKLADNÍ vzdělání ve škole. Ne doma. Taktéž už nechci platit za státní školu ani cent. Povinná školní docházka je zdarma a přesto rodič každý rok zaplatí (hlavně na prvním stupni) cirka 4000,- za jedno dítě. Už mě to fakticky nebaví. \r\nA až teď si jdu dělat svoje přípravy. To jen, až zas budete nadávat, že máme nějaké prázdniny. Tak si vzpomeňte, že vy v pět až do rána na svoji práci ani nepomyslíte (někteří)... \r\n\r\nNo, tak jsem si ulevil a jdu zase něco dělat. Mír se všemi rodiči ????✌️\r\nP.S. Sorry za chybky (už jsem je opravil. Píšu to v telefonu).'),
(363, '2022-10-17 23:45:28', 'Záhada naší kuchyně. Než řeknu, co je onou záhadou, musím vysvětlit pár drobností:\r\n1) Máme filtr na vodu, ale je tu menší tlak a teče nám pomaleji (taky aby ne, když tu vodu musí fakt čistit, že jo? ????\r\n2) Proto taky napouštíme džbán, abychom si pak v klidu mohli vodu nalít a nečekat.\r\n3) Jája na tenhle rok na nás uvalila kletbu "Jak na Nový Rok, tak po celý rok" a prvním dnem džbán přelila, čímž udělala v kuchyni malou potopu. \r\n4) Tyhle potopy "vyrábíme" cirka jednu až dvě týdně (no jo, je to na nic, co?)\r\nA teď k záhadě. Osobně si myslím, že máme chaloupku na kuří nožce a jak se holka vyspí, tak se i postaví, respektive nahne. Jak si totiž máme vysvětlit to, že když přelijeme onu vodu ze džbánu a vyteče na kuchyňskou linku, tak jednou teče doprava a jindy zase doleva a pravé strany si ani nevšimne? \r\nTak, a teď mi to tu vysvětlete.'),
(364, '2022-11-08 23:54:21', 'Život je plný radosti, ale i strastí, zmaru a nejistot, jak to bude dál. Je toho mnoho, co mám v hlavě a jen vlastně málo utříděného, co chce ven. V neděli se nám zranila jedna z kobylek, neboť se podělalo všechno, co se podělat mohlo a souhra náhod připletla do cesty neočekávané a závažné změny, který by si nikdo nepřál. A to tak, že to bylo na převoz na kliniku a okamžitou operaci nohy. Nyní má kopyto fixované, je po operaci a zatím (opravdu jen zatím) nemá horečky, takže se asi daří antibiotiky případný zánět držet na uzdě. Protože jedna kobylka nemůže zůstat sama, je u přátel v hřebčíně a čeká se, co bude dál. Operace i léčba u koní jde klidně  na pět nul a víc s nejistým výsledkem. Takže druhá kobylka asi změní majitele a to jsem nejprve chtěl prodat i své oblíbené auto. U nás doma výběh zeje prázdnotou a zkuste si jen tak do šera zavolat jejich jména a čekat, že by někdo přišel... Tenhle týden zkrátka není dobrý. Ale i to asi k životu patří. \r\nKaždý den teď jen doufám, že se to všechno ustálí a skončí to dobrým koncem. Dvojčata, jakoby to chápaly a nechápaly. A pak je to všechno na nás, dospělých... \r\nJsme jako ten Atlas, co myslíte?'),
(365, '2022-12-10 18:49:46', 'Tak mě malém taky dostali. Kdo? Podvodníci. Nikdy nic neřešte hned po probuzení (teda aspoň půl hodiny po). To jsem takhle náhodou zabrouzdal na maily. A tam mě civí hláška Netflixu, že mám aktualizovat platbu. Oni se ti zmetci fakticky trefili, když se mi teď měnila kreditní karta. Tak jsem to hned odmáčkul (jsem totiž ten největší prokrastinátor). V zápětí mi přišla SMS, že mi chtěl někdo spatřovat se svým google účtem moji kartu, tak ji zablokovali. \r\nMusím pochválit svoji banku, která mi fakt ochránila peníze. Musím sebe polštář, ze si mám lip číst, kdo mi co posílá (hlavně název mailu, ne nadpisy). No a teď budu týden čekat na novou kreditku (takže mě to nakonec stalo "jen" 200 Kč).\r\nUf, resumé: Lidičky, dávejte si pozor! (ne při radovánkách - nová dítka, hlavně dvojčata jsou potřeba ????????)'),
(366, '2022-12-12 21:33:49', '???? Asi bych tu měl teď mít haldy fotek dvojčat od narození až dosud. Asi bych měl sdílet video z velké narozeninové oslavy, kdy si holky s kamarádkami užily krásných 5 hodin s mojí diskotékou a vymyšlenými hrami. Asi bych měl bilancovat, co s s dvojčaty podařilo nebo nepovedlo za celých deset let. \r\nVšichni, co tu jste tak nějak od začátku, nebo jen nakoukli a zůstali, nebo jste i mými bližšími kamarády, víte, že tato stránka je tak nějak nejpodivnější, co se dá tak na netu najít. Je tu všechno a přitom nic, nic vám nevnucujem ani neprodavame, jednou tu le legrace, podruhé fňukání nepochopeného otce rodiny nebo naopak nějaké to rodinné hoře. V bilanci mimo jiné jsem tu nebyl ani jednou sprostý a dokonce tu nebyla ani ta práva blogerská erotika ????\r\nKaždopádně i vám všem tady díky za rady, povzbuzení nebo jen počtení. Jednou vám určitě i holky samy poděkují ????\r\nDneska jim je DESET LET. Nejak to rychle letí. Před deseti lety jsem přišel vyřízený z nemocnice (Ok, něco na mě asi lezlo) a ani jsem je poradně nezapil. Každá je jiná. A to jsou od sebe jen minutu. \r\nCo jim popřát? \r\n❤️Aby se měly společně rády do konce svých dní. \r\n❤️Aby měly jedna druhou stále za největší kamarádku (a snad k toki fakt jednou dospějí).\r\n❤️Aby co nejdéle měly po boku i svoje rodiče, kteří je moc milují.\r\n❤️Aby je táta hodně dlouho ochraňoval a mamka co nejdéle hýčkala\r\n❤️Aby byly stále zdravé, veselé a své\r\n❤️Aby nikdy nepocítily bolest v srdci a zlo slova\r\n❤️Aby byly neustále našimi anděly\r\n????????KRÁSNÉ NAROZENINY, AMI a EMI.????????'),
(367, '2022-12-18 16:09:16', 'Jo, jasně. Holky (a to všechny tři) jsou (zase) nemocné. Tak ono není divu. Tuhle onehdá přijdu do třídy a smrká tam pět červenonosáků ???? pak je tu taky tohle počasí. Zkrátka všechno ke všemu.\r\nČetl jsem mnoho příspěvků různých komunit a shodují se: smrkání, kašlání, zvracení, horečky... \r\nNu což, tak ať jsme všichni do Štědrého dne v pořádku ????');
INSERT INTO `posts` (`id`, `date`, `content`) VALUES
(368, '2022-12-18 21:23:29', 'ONLINE: Tak tohleto musím ???? \r\nV naší rodině je už delší dobu na prvním místě sledování sitcomu Teorie velkého třesku. D9vají se na něj i dvojčata (ne pořád). Naštěstí tam o jistých věcech mluví docela "vědecky," takže moc nemusíme zasahovat. Ale zase na druhou stranu nechceme, aby si myslely o nějakých slovíčkách něco jiného, nežli to je. \r\nPrávě nyní proběhla rozprava Sheldona s holkama, že se chystá na něco výjimečného s Amy, jeho holkou. Na otázku, co přesně, zní h)jeho odpověď, že se jí "CHYSTÁ DÁT SVOJE GENITÁLIE." \r\nEmča: "Co jsou to genitálie?" .... (chvilka ticha, než jsem si rozmyslel odpověď) "To je mozek?"\r\nJá (trochu nesystematicky): "Ano, to je mozek... někdo tím myslí..."\r\nJe slyšet i Jáji smích a následné propálení: "Ne, Emi, to jsou přirození."\r\nEmča: "Jaká přirození?"\r\nJá: No, mužské i ženské. Pindík a buchta.\r\nEmča: Jo, aha! Fuuuuuuj. Preferuju ten mozek!\r\n????????????\r\nKaždopádně: Nelžete svým dětem - za a) když to někdo řekne ve škole nebo v partě, budou za trotla b) stejně se to pak dozví :)\r\n\r\nAle zase dobrý krytí: "Miláčku, nechceš můj mozek?" (zeptal se Hanibal Lecter????)'),
(369, '2023-01-11 23:26:12', 'Emču bolí boule na hlavě. Jo, holka, to máš tak, když jíš hodně čokolády. Přišla ke mně, co to tam jako má. Rozhrnu vlasy a on tam na mě kouká. Krásně uzrálý, až jsem si vzpomněl na dětství a neskutečnou trýzeň při rutině vymačkávání. \r\nNo jo, Emi, to je ale "žiďák!" Pronesu ledabyle, načeš dcera s výrazem mladého outloně vyráží k Jáje a zděšeně hlásí: "Mamíííí, mě se na hlavě usadil nějaký bezdomovec!!!"\r\nMiluju záměny slov a významu ????'),
(370, '2023-01-18 10:26:54', 'Pomalu se uzavírají známky za pololetí. Ok, že se s dvojčaty učíme a stejně to nikam nevede, o tom se rozepíšu (a posbírám rady) jindy.\r\nDneska jsem zkoušel "napravené hříšníky" ze zeměpisu. Přijdu ráno do třídy a jen si povzdechnu, že bych na to potřeboval silné kafe. Potud normální informace. Jenže:\r\nTak si tak zkouším, řeč je o Brazílii a ptám se, jakých plodin je to přední světový vývozce? Zkoušený žák se nejprve zaříkává železnou rudou, a tak raději pomáhám: "No tak, ráno jsem tu o tom mluvil. Co bych si kvalitního dal?"\r\nZkoušený žák v tu chvíli vyhrkne: "TRÁVU!"\r\nTakže, milí učitelé - káva  nebo tráva - nám už asi nic nepomůže :D'),
(371, '2023-03-02 14:14:02', 'Dneska ráno Amálka s dětskou nevinností v hlase:\r\n"Já tu s vámi budu muset být až do stáří...."\r\n"Proč, Amálko?" Ptám se.\r\n"No," povzdechne si. "Když vy tu máte Wi-fi."'),
(372, '2023-04-26 11:32:22', 'Dvojčata nám zase lehla. Amálka to tentokrát odnesla o dost víc a ještě včera zápolila s devětatřicítkami. Když jsem byl na rodičáku, tak musím říct, že to šlo jak po másle. Vystačili jsme si, vše se zvládlo. Teď si připadám jak na kolotoči a centrifuze najednou. Až bude víc času, zkusím se na počítači o dost více rozepsat, udělat jakysi rozbor. Bude to můj pohled na věci, které se točí kolem naší rodiny, mě osobně i mých dcer. Aspoň se tu - na blogu - bude zase něco dít ???? \r\nJinak letos se chystáme na pár tuzemských destinací a je možné, že se s někým i potkáme. V nejbližší době vyrážíme směr Rožnov pod Radhoštěm. Tak mne tak napadá, že za přispění na pohádku Největší dar by mne měl čekat i podepsaný plakát od slovanských bohů (tedy našich herců). Tak bych ho třeba na našich cestách někomu, koho potkáme a sleduje náš blog nebo IG. \r\nDětem zdar a nenechme se otrávit marasmem světa. Protože svět patří nám, ne bručounům ????????????????'),
(373, '2023-05-08 23:14:26', 'Sliboval jsem, že napíšu něco málo o cestě do Zlínského kraje, respektive na Vsetínsko. Město s přibližně 16000 obyvateli a krásnou krajinou. Rožnov pod Radhoštěm. Slovensko, co byste valaškou dohodili, Moravskoslezský kraj jakbysmet. \r\nJe tam nádherně. Proč by taky ne, Morava (nebo Slezsko) je pohostinná a lidé dobří. Mám to tam rád i kvůli tomu, že to mládí jsem tam prožil od Kopřivnice až po Frýdek, dál Ostravu k Vítkovicím. Do Rožnova jsme taky zajeli, Hukvaldy proskákali kámen po kameni a nohy v Ostravici smočili. Sezóna u Radhoště začíná až 1. 5. a do té doby jsou tam ceny (a to je ten malý kámen úrazu u nás v ČR celkově) skoro stejné, jako v Chorvatsku v ten stejný čas. POkud však chcete peníze nechávat doma, jsem jedině pro. I zdejší lidé si to zaslouží a slovy jedné známé - o práci tam jen tak nezavadíš (a elektřina je drahá ????). Horší je, že v sezóně to v některých hotelích a kempech vzroste až dvojnásobně za noc.\r\nV dalším výčtu už jen vstup na Jurkovičovu rozhlednu (tu doporučuji ráno, než půjdete do skanzenu - ještě tam nikdo nenííííí ???? (cena jen 80 za dospěláka), vstupy do skanzenu průměrné, toho bych se nebál, jen pak lanovka na Pustevny za téměř 800,- pro 4 lidi, rodinný vstup na rozhlednu Valaška (ale jo, nikdo jí nedotoval a nějak ji v provozu musí mít) také téměř 800,-.\r\nProč píšu i ceny? Abyste měli představu, až tam pojedete a řekli si, co stojí za to a co ne. Ono pustit za den a půl z portmonky cirka sedm tisíc (i s nějakou tou upomínkovou drobností, a to nepočítám naftu), to pak chtějte každý víkend něco drobotině ukazovat a dost si uvědomuji, že mnoho z nás na to dlouho šetří (v nejhorším případě ani nejede). \r\nAbychom to však nepočítali jen na finance - šest let jsme nikde takhle společně nebyli přes noc a opravdu se to všem moc líbilo. Morava je v tomhle unikátní. Dýchne na Vás zcela jiný duch - duch pohody, pozorných lidí, jako kdyby se na chvíli zastavil čas. Nikam nespěcháte. A když to spojíte s prima návštěvou, , je to pro vás kouzelné. \r\nResumé - Rožnov a Pustevny s Valaškou doporučuji, avšak vyhledat dobré přespání (je toho tam spousty). \r\nP.S. Chceme jet na Dolní Moravu na vysutou lávku a stezku v korunách stromů. Máte k tomu někdo něco? Díky předem.'),
(374, '2023-08-09 19:51:32', 'Bydlíme už asi tři roky nad náletem letadel na Ruzyň. Někdy v neděli je to jak na D1. Tuhle si to nějaký airbus brousil podvozek, že bylo vidět letušku jak laškuje s kapitánem. V tom Amálka je tak pronese: \r\n"Tady někde musí být asi nějaké letiště, ne?"\r\nTy Jo ????, v jaké dimenzi že to to dítě žije?\r\n????⭐️'),
(375, '2023-12-04 08:27:36', 'Je zajímavé, jak úderem prvního prosincového dne děti zjihnou, začnou plnit (sem tam) své úkoly, a hlavně ty školou povinné leží v učení a chtěj dobré známky. (Skoro) neodmlouvají, když mají jít spát a vůbec se se sourozenci nestrkají, neštěkají a nejlépe neperou. ????Jen je škola, že ten Mikuláš s čertem a andělem chodí hned z kraje měsíce, protože bych potřeboval, aby byl klid až do Štědrého dne. \r\nEmča už si napsala i Ježíškovi, Amálka takticky vyčkává, jak to dopadne u Mikuláše. \r\nTak jak u vás? Ještě držíte Mikuláše, nebo už jenom balíčky za oknem nebo dveřmi? ????'),
(376, '2024-01-29 22:34:19', 'Úžasné, jak ta technika jde dopředu. Máme nové GPS v autě. Milejší je nám hlas umělé inteligence, a tak je zvolená, aby nám povídala do řízení. To, že neustále každá navigace říká nesmyslnou větu: "Na kruhovém objezdu jeďte doleva..." to jsem si už zvykl. Ale nyní jsme jeli směr Mladá Boleslav. V navigaci je psaná jako Ml. Bolaslav. AI nám to čte a říká: "Jeďte směr MILILITR BOLESLAV..."\r\nZdravím do Mililitru Boleslavi!! :D'),
(377, '2024-11-14 10:02:25', 'Život letí. Proto není ani moc času sem něco napsat, ba dokonce i něco nafotit a ještě to sdílet s ostatními. NICMÉNĚ:\r\nPokud jsem si myslel, že dvojčata budou vždy o krok napřed (a proto také název "Dvojčata na útěku"), mohl bych v další etapě od blížícího se tuctu roků jejich narození změnit název na "Dvojčata na přesdžku!" To, co se nyní odehrává v našem malebném mini Hobotíně se nedá nazvat ani mezigenerační ponorkou natož roztomilými děvčátky. Někdy mám dojem, že už jsem v pekle a tohle je můj nekonečný trest. Tím však nenabádám, abyste si ratolesti nepořizovali. Naopak! Pojďme se držet za ruce snášeje příkoří dospívajících puberťáků!\r\nKAŽDOPÁDNĚ: Se těšte na výlevy unaveného rodiče. Třeba vám to pomůže se danému problému vyhnout obloukem (nebo si i vyměníme zkušenosti ????).\r\nTak jdu na to. Držte palec!');
INSERT INTO `strings` (`code`, `value`, `type`, `description`) VALUES
('page1_content', '<img src="img/nohy.png" style="width:300px">', 'html', 'Obsah stránky 1'),
('page1_h1', '<br/>\r\n<small>aneb život otce na rodičovské a po rodičovské</small>', 'plain', 'Hlavní nadpis stránky 1'),
('page1_h2', 'Radim Keith', 'plain', 'Vedlejší nadpis stránky 1'),
('page2_content', '<p>Začalo jaro a s ním i nucené práce vykoupené krví a bolavými zády na vlastní zahrádce. Na zahrádku jsme vypustili i oba tygry. Běhají mezi krumpáčem, lopatou a hlínou a nedají se zkrotit. I ten řev našich dvojčat nasvědčuje tomu, že se po dalších pár měsíců nastěhovala zuřivá šelma na náš dvůr a jen tak se jí rozhodně nezbavíme. Co si holky ale oblíbily jsou domácí (rozuměj zahradní) zvířátka. Žádný krtek nebo hraboš, ale ke štěstí postačí žížala. Žížala je opečovávaná.</p>\n', 'html', 'Obsah stránky 2'),
('page2_h1', '', 'plain', 'Hlavní nadpis stránky 2'),
('page2_h2', '', 'plain', 'Vedlejší nadpis stránky 2'),
('page3_content', '<p>Sledujte stránku na <a href="https://www.facebook.com/dvojcatanauteku/" target="_blank">facebooku</a>, nebo se začtěte v řádcích na zdejších stránkách, NEBO SI KNIHU, PRVNÍ DÍL (JAK TO BYLO OD ZAČÁTKU) můžete koupit zde.</p>\r\n\r\n<p><a href="https://eshop.librix.eu/produkt/detail/1111/dvojcata-na-uteku" class="btn-primary" target="_blank">OBJEDNAT KNIHU</a></p>\r\n\r\nA nebo, pokud si ke čtení chcete poslechnout muziku, vám mohu zahrát třeba do ouška - to se podívejte <a href="http://www.radim-keith.cz/" target="_blank">ZDE</a>', 'html', 'Obsah stránky 3'),
('page3_h1', 'DVOJČATA NA ÚTĚKU', 'plain', 'Hlavní nadpis stránky 3'),
('page3_h2', 'Dvojčata na útěku aneb život otce na rodičovské', 'plain', 'Vedlejší nadpis stránky 3'),
('page4_content', '<p>Narodil se v roce 1978. Ve studiích nejdále dosáhl na vysokoškolský titul v oblasti andragogiky. Jako mlád krátce psal do novin rodného města v rubrice sportovního redaktora a několik let se účastnil literárních přehlídek (např. ocenění Novinář 97 KOLÍNSKÝCH NOVIN). S kolegou, divadelním hercem a muzikantem, vytvořil scénář pro celovečerní divadelní hudební komedii, ale i sám napsal několik hudebních pohádek. Je i muzikantem a zpěvákem na volné noze. Do listopadu 2016 byl na rodičovské s dvojčaty. Nyní, prozatím, se i nadále stará o čtyřletá dvojčata a chod domácnosti (samozřejmě i s mužskými pracemi :D )</p> mail: radim.keith@seznam.cz', 'html', 'Obsah stránky 4'),
('page4_h1', '<center>\n  <img src="img/radim.png" /><br/>\n  BIO\n</center>', 'plain', 'Hlavní nadpis stránky 4'),
('page4_h2', '', 'plain', 'Vedlejší nadpis stránky 4'),
('slides_count', '4', 'number', 'Počet slajdů');
